#define MAIL_DIR "/var/mail/"
#define REPLACE_KEYWORD "SECRET_KEYWORD"
#define NEW_KEYWORD "NEW_KEYWORD"

int main() {
    char username[256], mailbox[256], line[1024], keyword[32], replacement[32];
    int fd, i, j;

    // Get current user name and mailbox path
    getlogin_r(username, sizeof(username));
    sprintf(mailbox, "%s%s", MAIL_DIR, username);

    // Open mailbox file for reading
    fd = open(mailbox, O_RDONLY);
    if (fd < 0) {
        perror("Error opening mailbox file");
        return 1;
    }

    printf("----------------------------------------\n");
    printf("|          Your Invasive Email Client   |\n");
    printf("|                                      |\n");
    printf("----------------------------------------\n");

    // Read and process each line in the mailbox file
    while (fgets(line, sizeof(line), fd)) {
        // Replace keyword with new keyword
        i = strlen(REPLACE_KEYWORD);
        j = strlen(line);
        for (int k = 0; k < j - i; k++) {
            if (strncmp(line + k, REPLACE_KEYWORD, i) == 0) {
                strncpy(line + k, NEW_KEYWORD, i);
                break;
            }
        }

        // Print the modified line
        printf("%s", line);

        // Check for email headers and print them if found
        if (strstr(line, ": ") || strstr(line, "Subject: ")) {
            printf("\n%s", line);
        }
    }

    close(fd);
    return 0;
}

// Function to replace a keyword with a new keyword in a given string
void replace_keyword(char *str, char *old_keyword, char *new_keyword) {
    char *token, temp_str[1024];
    int i, j, len_old = strlen(old_keyword), len_new = strlen(new_keyword);

    strcpy(temp_str, str);

    token = strtok(temp_str, "\n");

    while (token != NULL) {
        i = strlen(token);
        j = i - len_old;

        if (j > 0 && strncmp(token + j, old_keyword, len_old) == 0) {
            strncpy(token + j, new_keyword, len_new);
        }

        token = strtok(NULL, "\n");
    }

    strcpy(str, temp_str);
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Vehicle struct
typedef struct {
    int x;
    int y;
    int speed;
    int direction;
} Vehicle;

// Function to initialize vehicle
void initVehicle(Vehicle* v) {
    v->x = rand() % 20 + 1; // Randomly place vehicle on x-axis
    v->y = rand() % 10 + 1; // Randomly place vehicle on y-axis
    v->speed = 0; // Initially, the vehicle is not moving
    v->direction = 0; // Initially, the vehicle is facing upwards
}

// Function to move vehicle
void moveVehicle(Vehicle* v) {
    int dx = 0;
    int dy = 0;

    if (v->direction == 0) { // If the vehicle is facing upwards
        dy = v->speed; // Move the vehicle upwards
    }
    else if (v->direction == 1) { // If the vehicle is facing downwards
        dy = -v->speed; // Move the vehicle downwards
    }
    else if (v->direction == 2) { // If the vehicle is facing left
        dx = -v->speed; // Move the vehicle left
    }
    else if (v->direction == 3) { // If the vehicle is facing right
        dx = v->speed; // Move the vehicle right
    }

    v->x += dx; // Update x-coordinate
    v->y += dy; // Update y-coordinate
}

// Function to display vehicle
void displayVehicle(Vehicle* v) {
    printf("Vehicle at (%d,%d) facing %d\n", v->x, v->y, v->direction);
}

// Function to change direction of vehicle
void changeDirection(Vehicle* v) {
    v->direction = (v->direction + 1) % 4; // Change direction by 90 degrees
}

// Main function
int main() {
    srand(time(NULL)); // Seed the random number generator with current time

    Vehicle vehicle;
    initVehicle(&vehicle); // Initialize vehicle

    while (1) {
        moveVehicle(&vehicle); // Move the vehicle
        displayVehicle(&vehicle); // Display the vehicle
        changeDirection(&vehicle); // Change direction of the vehicle
    }

    return 0;
}

