                                                                     &(ehead->sourceUID), 
                                                                     SyntroUtils::convertUC2ToUInt(ehead->sourcePort), 
                                                                     sizeof(SYNTRO_CFSHEADER) + length);

	SYNTRO_CFSHEADER *responseHdr = (SYNTRO_CFSHEADER *)(responseE2E + 1);

	memset(responseHdr, 0, sizeof(SYNTRO_CFSHEADER));

