typedef enum {
    RED,
    YELLOW,
    GREEN
} LightState;

void init_lights(LightState *lights) {
    lights[0] = RED;
    lights[1] = GREEN;
    lights[2] = YELLOW;
}

void toggle_lights(LightState *lights) {
    lights[0] = (lights[0] == RED)? GREEN : RED;
    lights[1] = (lights[1] == GREEN)? RED : GREEN;
    lights[2] = (lights[2] == YELLOW)? GREEN : YELLOW;
}

void wait_for_switch(LightState *lights) {
    while (lights[0]!= RED) {
        printf(".");
        fflush(stdout);
        sleep(1);
    }
}

int main() {
    LightState lights[3];
    init_lights(lights);

    while (1) {
        printf("Switching traffic lights...\n");
        printf("Lights: %d %d %d\n", lights[0], lights[1], lights[2]);
        printf("Press enter to switch the lights.\n");
        getchar();

        toggle_lights(lights);
        wait_for_switch(lights);
        printf("Lights: %d %d %d\n", lights[0], lights[1], lights[2]);
        printf("Press enter to switch the lights.\n");
        getchar();

        toggle_lights(lights);
        wait_for_switch(lights);
        printf("Lights: %d %d %d\n", lights[0], lights[1], lights[2]);
        printf("Press enter to switch the lights.\n");
        getchar();
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

struct string {
    char *ptr;
    size_t len;
};

static size_t WriteCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct string *s = (struct string *)userp;

    s->len += realsize;
    s->ptr = (char *)realloc(s->ptr, s->len + 1);
    if (s->ptr == NULL) {
        /* out of memory */
        fprintf(stderr, "not enough memory to write response\n");
        return 0;
    }

    memcpy(s->ptr + s->len - realsize, contents, realsize);
    s->ptr[s->len] = '\0';

    return realsize;
}

int main(void) {
    CURL *curl;
    CURLcode res;
    struct string s;
    s.len = 0;
    s.ptr = malloc(1);
    if (s.ptr == NULL) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "https://www.example.com/");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
    free(s.ptr);

    printf("Received %ld bytes: %s\n", (long)s.len, s.ptr);

    return 0;
}

