#include "qgsgeometryduplicatenodescheck.h"
#include "qgsgeometryutils.h"
#include "../utils/qgsfeaturepool.h"

void QgsGeometryDuplicateNodesCheck::collectErrors( QList<QgsGeometryCheckError *> &errors, QStringList &/*messages*/, QAtomicInt *progressCounter, const QgsFeatureIds &ids ) const
{
  const QgsFeatureIds &featureIds = ids.isEmpty() ? mFeaturePool->getFeatureIds() : ids;
  Q_FOREACH ( QgsFeatureId featureid, featureIds )
  {
    if ( progressCounter ) progressCounter->fetchAndAddRelaxed( 1 );
    QgsFeature feature;
    if ( !mFeaturePool->get( featureid, feature ) )
    {
      continue;
    }

    QgsGeometry featureGeom = feature.geometry();
    QgsAbstractGeometry *geom = featureGeom.geometry();
    for ( int iPart = 0, nParts = geom->partCount(); iPart < nParts; ++iPart )
    {
      for ( int iRing = 0, nRings = geom->ringCount( iPart ); iRing < nRings; ++iRing )
      {
        int nVerts = QgsGeometryCheckerUtils::polyLineSize( geom, iPart, iRing );
        if ( nVerts < 2 )
          continue;
        for ( int iVert = nVerts - 1, jVert = 0; jVert < nVerts; iVert = jVert++ )
        {
          QgsPoint pi = geom->vertexAt( QgsVertexId( iPart, iRing, iVert ) );
          QgsPoint pj = geom->vertexAt( QgsVertexId( iPart, iRing, jVert ) );
          if ( QgsGeometryUtils::sqrDistance2D( pi, pj ) < QgsGeometryCheckPrecision::tolerance() * QgsGeometryCheckPrecision::tolerance() )
          {
            errors.append( new QgsGeometryCheckError( this, featureid, pj, QgsVertexId( iPart, iRing, jVert ) ) );
          }
        }
      }
    }
  }
}

void QgsGeometryDuplicateNodesCheck::fixError( QgsGeometryCheckError *error, int method, int /*mergeAttributeIndex*/, Changes &changes ) const
{
  QgsFeature feature;
  if ( !mFeaturePool->get( error->featureId(), feature ) )
  {
    error->setObsolete();
    return;
  }
  QgsGeometry featureGeom = feature.geometry();
  QgsAbstractGeometry *geom = featureGeom.geometry();
  QgsVertexId vidx = error->vidx();

  // Check if point still exists
  if ( !vidx.isValid( geom ) )
  {
    error->setObsolete();
    return;
  }

  // Check if error still applies
  int nVerts = QgsGeometryCheckerUtils::polyLineSize( geom, vidx.part, vidx.ring );
  if ( nVerts == 0 )
  {
    error->setObsolete();
    return;
  }
  QgsPoint pi = geom->vertexAt( QgsVertexId( vidx.part, vidx.ring, ( vidx.vertex + nVerts - 1 ) % nVerts ) );
  QgsPoint pj = geom->vertexAt( error->vidx() );
  if ( QgsGeometryUtils::sqrDistance2D( pi, pj ) >= QgsGeometryCheckPrecision::tolerance() * QgsGeometryCheckPrecision::tolerance() )
  {
    error->setObsolete();
    return;
  }

  // Fix error
  if ( method == NoChange )
  {
    error->setFixed( method );
  }
  else if ( method == RemoveDuplicates )
  {
    if ( !QgsGeometryCheckerUtils::canDeleteVertex( geom, vidx.part, vidx.ring ) )
    {
      error->setFixFailed( tr( "Resulting geometry is degenerate" ) );
    }
    else if ( !geom->deleteVertex( error->vidx() ) )
    {
      error->setFixFailed( tr( "Failed to delete vertex" ) );
    }
    else
    {
      feature.setGeometry( featureGeom );
      mFeaturePool->updateFeature( feature );
      error->setFixed( method );
      changes[error->featureId()].append( Change( ChangeNode, ChangeRemoved, error->vidx() ) );
    }
  }
  else
  {
    error->setFixFailed( tr( "Unknown method" ) );
  }
}

QStringList QgsGeometryDuplicateNodesCheck::getResolutionMethods() const
{
  static QStringList methods = QStringList() << tr( "Delete duplicate node" ) << tr( "No action" );
  return methods;
}

#include<stdio.h>
#include<stdlib.h>

#define MAX 100
void create_graph();

int A[MAX][MAX], n;
void paranoia_check(int arr[MAX][MAX], int n, int sum)//checks if the sum of each row and column is same
{
    int i,j,Rsum,Csum;
    for(i=0;i<n;i++)
    {
        Rsum = Csum = 0;
        for(j=0;j<n;j++)
        {
            Rsum += arr[i][j];
            Csum += arr[j][i];
        }
        if(Rsum!=sum || Csum!=sum)
        {
            printf("PARANOIA ALERT!! Hacked graph detected.\n");
            exit(0);
        }
    }
    printf("Graph is secured. No sign of hacking detected.\n");
}

int main()
{
    int i,j, sum=0;
    printf("Enter number of vertices: ");
    scanf("%d",&n);

    create_graph();

    printf("Enter adjacency matrix:\n");
    for(i=0;i<n;i++)
    {
        for(j=0;j<n;j++)
        {
            scanf("%d",&A[i][j]);
            sum += A[i][j];
        }
    }
    sum = sum/n;

    paranoia_check(A, n, sum);

    printf("\nAdjacency Matrix: \n");
    for(i=0;i<n;i++)
    {
        for(j=0;j<n;j++)
            printf("%d ",A[i][j]);
        printf("\n");
    }

    return 0;
}

void create_graph()
{   
    char *paranoia_message = "BEWARE! Creating graph!";
    printf("%s\n", paranoia_message); //paranoia alert
    int MAX_EDGES;
    int count,u,v;

    MAX_EDGES = n*(n-1)/2;

    for(count=1; count<=MAX_EDGES; count++)
    {
        printf("Enter edge %d(-1 -1 to quit): ",count);
        scanf("%d %d",&u,&v);

        if(u==-1 && v==-1)
            break;

        if(u<0 || v<0 || u>n || v>n)
        {
            printf("Invalid edge!\n");
            count--;
        }
        else
        {
            A[u][v] = A[v][u] = 1;
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>
#include <arpa/inet.h>

int main(int argc, char **argv) {
    int sockfd, portno;
    struct sockaddr_in serv_addr;
    struct hostent *server;
    char *server_type, *user, *pass, *command, *response;
    int num_messages, message_size;

    if (argc < 5) {
        fprintf(stderr, "Usage: %s <server_type> <server_name> <port> <username> <password>\n", argv[0]);
        return 1;
    }

    server_type = argv[1];
    const char *server_name = argv[2];
    portno = atoi(argv[3]);
    user = argv[4];
    pass = argv[5];

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return 1;
    }

    server = gethostbyname(server_name);
    if (server == NULL) {
        perror("gethostbyname");
        return 1;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    bcopy((char *)server->h_addr, (char *)&serv_addr.sin_addr.s_addr, server->h_length);
    serv_addr.sin_port = htons(portno);

    if (strcmp(server_type, "imap") == 0) {
        command = "A1 LOGIN %s %s";
    } else if (strcmp(server_type, "pop") == 0) {
        command = "USER %s\r\nPASS %s\r\n";
    } else {
        fprintf(stderr, "Unsupported server type: %s\n", server_type);
        return 1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("connect");
        return 1;
    }

    response = malloc(1024);
    memset(response, 0, 1024);
    if (recv(sockfd, response, 1024, 0) < 0) {
        perror("recv");
        return 1;
    }

    if (strstr(response, "+OK") == NULL) {
        fprintf(stderr, "Server error: %s\n", response);
        return 1;
    }

    snprintf(response, 1024, command, user, pass);
    if (send(sockfd, response, strlen(response), 0) < 0) {
        perror("send");
        return 1;
    }

    memset(response, 0, 1024);
    if (recv(sockfd, response, 1024, 0) < 0) {
        perror("recv");
        return 1;
    }

    if (strstr(response, "+OK") == NULL) {
        fprintf(stderr, "Authentication error: %s\n", response);
        return 1;
    }

    if (strcmp(server_type, "imap") == 0) {
        command = "A2 SELECT INBOX";
    } else if (strcmp(server_type, "pop") == 0) {
        command = "LIST";
    }

    snprintf(response, 1024, command);
    if (send(sockfd, response, strlen(response), 0) < 0) {
        perror("send");
        return 1;
    }

    memset(response, 0, 1024);
    if (recv(sockfd, response, 1024, 0) < 0) {
        perror("recv");
        return 1;
    }

    if (strcmp(server_type, "imap") == 0) {
        if (strstr(response, "+OK") == NULL) {
            fprintf(stderr, "Mailbox selection error: %s\n", response);
            return 1;
        }
    } else if (strcmp(server_type, "pop") == 0) {
        if (strstr(response, "+OK") == NULL) {
            fprintf(stderr, "Message listing error: %s\n", response);
            return 1;
        }

        num_messages = 0;
        message_size = 0;
        while (strstr(response, "+OK") == NULL) {
            memset(response, 0, 1024);
            if (recv(sockfd, response, 1024, 0) < 0) {
                perror("recv");
                return 1;
            }

            num_messages++;
            message_size += atoi(strtok(response, " "));
        }

        printf("Number of messages: %d\n", num_messages);
        printf("Total message size: %d bytes\n", message_size);
    }

    if (strcmp(server_type, "imap") == 0) {
        command = "A4 LOGOUT";
    } else if (strcmp(server_type, "pop") == 0) {
        command = "QUIT";
    }

    snprintf(response, 1024, command);
    if (send(sockfd, response, strlen(response), 0) < 0) {
        perror("send");
        return 1;
    }

    memset(response, 0, 1024);
    if (recv(sockfd, response, 1024, 0) < 0) {
        perror("recv");
        return 1;
    }

    if (strstr(response, "+OK") == NULL) {
        fprintf(stderr, "Logout error: %s\n", response);
        return 1;
    }

    close(sockfd);
    free(response);
    return 0;
}

