#include <fcntl.h>
#include <sys/soundcard.h>
#include <time.h>

#define SAMPLE_RATE 44100
#define FRAMES 2048
#define DELAY_LINE_LENGTH 512

typedef struct {
    float samples[FRAMES];
    int read_ptr, write_ptr;
} delay_line;

void delay_line_init(delay_line *dl) {
    dl->read_ptr = 0;
    dl->write_ptr = 0;
    memset(dl->samples, 0, FRAMES * sizeof(float));
}

void delay_line_write(delay_line *dl, float sample) {
    dl->samples[dl->write_ptr] = sample;
    dl->write_ptr = (dl->write_ptr + 1) % FRAMES;

    if ((dl->write_ptr - dl->read_ptr) >= DELAY_LINE_LENGTH) {
        float echo = dl->samples[dl->read_ptr];
        dl->samples[dl->read_ptr] = sample;
        dl->read_ptr = (dl->read_ptr + 1) % FRAMES;
        sample += echo * 0.9; // adjust echo level
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s input.wav output.wav\n", argv[0]);
        return 1;
    }

    int input_fd = open(argv[1], O_RDONLY);
    if (input_fd < 0) {
        perror("Error opening input file");
        return 1;
    }

    int output_fd = open(argv[2], O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (output_fd < 0) {
        perror("Error opening output file");
        close(input_fd);
        return 1;
    }

    delay_line dl;
    delay_line_init(&dl);

    struct timeval start_time, end_time;
    gettimeofday(&start_time, NULL);

    int frames_read;
    short int input_buf[FRAMES];

    while ((frames_read = read(input_fd, input_buf, FRAMES * sizeof(short int))) > 0) {
        for (int i = 0; i < frames_read / 2; i++) { // process each sample
            float sample = input_buf[i] / 32767.0f;
            delay_line_write(&dl, sample);
            short int output_sample = (short int)(dl.samples[dl.read_ptr] * 32767.0f);
            write(output_fd, &output_sample, sizeof(short int));
            input_buf[i] = output_sample;
        }
    }

    close(input_fd);
    close(output_fd);

    gettimeofday(&end_time, NULL);
    printf("Processed %d frames in %.2f ms\n", frames_read / 2, (end_time.tv_sec - start_time.tv_sec + end_time.tv_usec - start_time.tv_usec) / 1000.0);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_WORD_LEN 100
#define MAX_WORDS 10000

typedef struct {
    char word[MAX_WORD_LEN];
    int count;
} word_t;

int main(int argc, char **argv) {
    if (argc!= 2) {
        printf("Usage: %s <input file>\n", argv[0]);
        return 1;
    }

    FILE *input_file = fopen(argv[1], "r");
    if (!input_file) {
        perror("fopen");
        return 1;
    }

    char word[MAX_WORD_LEN];
    word_t words[MAX_WORDS];
    int num_words = 0;

    while (fscanf(input_file, "%s", word)!= EOF) {
        strcpy(words[num_words].word, word);
        words[num_words].count = 1;
        num_words++;
    }

    fclose(input_file);

    word_t *sorted_words = malloc(num_words * sizeof(word_t));
    int num_sorted_words = 0;

    for (int i = 0; i < num_words; i++) {
        if (words[i].count > sorted_words[num_sorted_words].count) {
            strcpy(sorted_words[num_sorted_words].word, words[i].word);
            sorted_words[num_sorted_words].count = words[i].count;
            num_sorted_words++;
        } else if (words[i].count == sorted_words[num_sorted_words].count) {
            strcpy(sorted_words[num_sorted_words].word, words[i].word);
            num_sorted_words++;
        }
    }

    FILE *output_file = fopen("summary.txt", "w");
    if (!output_file) {
        perror("fopen");
        return 1;
    }

    for (int i = 0; i < num_sorted_words; i++) {
        fprintf(output_file, "%s %d\n", sorted_words[i].word, sorted_words[i].count);
    }

    fclose(output_file);

    return 0;
}

