		game_state.key_rgt_mouse_down = (glfwGetMouseButton(window, GLFW_MOUSE_BUTTON_RIGHT) == GLFW_PRESS) || key_space;
		last_key_rgt_mouse = key_rgt_mouse;

		nova::tick(&game_state);

		char txt_buffer[256] = {};
		std::sprintf(txt_buffer, "Nova %.3fms", game_state.delta_time * 1000.0f);
		glfwSetWindowTitle(window, txt_buffer);

		glfwSwapBuffers(window);			
	}

	glfwDestroyWindow(window);
	glfwTerminate(); 

	return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define constants
#define NUM_CARDS 52
#define NUM_PLAYERS 4
#define NUM_HANDS 5
#define HAND_SIZE 5

// Define a structure to represent a card
typedef struct {
    int rank;
    int suit;
} Card;

// Define a structure to represent a player
typedef struct {
    char name[32];
    int score;
    Card* hand[HAND_SIZE];
} Player;

// Function to shuffle a deck of cards
void shuffle(Card* deck, int num_cards) {
    for (int i = 0; i < num_cards; i++) {
        int random_index = rand() % num_cards;
        Card temp = deck[i];
        deck[i] = deck[random_index];
        deck[random_index] = temp;
    }
}

// Function to deal cards to players
void deal(Player* players, Card* deck, int num_players, int num_cards) {
    for (int i = 0; i < num_players; i++) {
        for (int j = 0; j < HAND_SIZE; j++) {
            players[i].hand[j] = &deck[i * HAND_SIZE + j];
        }
    }
}

// Function to evaluate a hand
int evaluate_hand(Card* hand) {
    int rank = 0;
    int suit = 0;
    for (int i = 0; i < HAND_SIZE; i++) {
        rank += hand[i].rank;
        suit += hand[i].suit;
    }
    return rank + suit;
}

// Function to print the results of a hand
void print_results(Player* players, int num_players) {
    for (int i = 0; i < num_players; i++) {
        printf("Player %d: %d\n", i, players[i].score);
    }
}

int main() {
    // Initialize the deck of cards
    Card deck[NUM_CARDS];
    for (int i = 0; i < NUM_CARDS; i++) {
        deck[i].rank = i % 13 + 1;
        deck[i].suit = i / 13;
    }

    // Shuffle the deck of cards
    shuffle(deck, NUM_CARDS);

    // Initialize the players
    Player players[NUM_PLAYERS];
    for (int i = 0; i < NUM_PLAYERS; i++) {
        players[i].score = 0;
        for (int j = 0; j < HAND_SIZE; j++) {
            players[i].hand[j] = NULL;
        }
    }

    // Deal the cards to the players
    deal(players, deck, NUM_PLAYERS, NUM_CARDS);

    // Evaluate the hands of the players
    for (int i = 0; i < NUM_PLAYERS; i++) {
        players[i].score = evaluate_hand(players[i].hand);
    }

    // Print the results of the game
    print_results(players, NUM_PLAYERS);

    return 0;
}

// A unique C cryptographic hash function example program

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

// Define a struct for storing the hash function state
typedef struct {
    uint64_t a;
    uint64_t b;
    uint64_t c;
    uint64_t d;
} hash_state_t;

// Define the hash function
void hash(const char* input, hash_state_t* state) {
    uint64_t a = state->a;
    uint64_t b = state->b;
    uint64_t c = state->c;
    uint64_t d = state->d;

    for (int i = 0; i < strlen(input); i++) {
        a = (a + input[i]) % 256;
        b = (b + a) % 256;
        c = (c + b) % 256;
        d = (d + c) % 256;
    }

    state->a = a;
    state->b = b;
    state->c = c;
    state->d = d;
}

// Define a function to print the hash value
void print_hash(hash_state_t* state) {
    printf("%llx %llx %llx %llx\n", state->a, state->b, state->c, state->d);
}

int main() {
    // Initialize the hash state
    hash_state_t state = { 0, 0, 0, 0 };

    // Hash some input
    char* input = "Hello, World!";
    hash(input, &state);

    // Print the hash value
    print_hash(&state);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_STRING_LENGTH 100

// Function to check if the given string is a QR code
bool isQRCode(char *str) {
    int len = strlen(str);
    if(len == 0 || len % 2 == 1) {
        return false;
    }
    for(int i = 0; i < len; i++) {
        if(str[i] != '0' && str[i] != '1') {
            return false;
        }
    }
    return true;
}

// Function to convert a QR code string to binary
void QRCodeToBinary(char *str, char *binary) {
    int len = strlen(str);
    for(int i = 0; i < len; i+=2) {
        if(str[i] == '0' && str[i+1] == '0') {
            strcat(binary, "0000");
        } else if(str[i] == '0' && str[i+1] == '1') {
            strcat(binary, "0001");
        } else if(str[i] == '1' && str[i+1] == '0') {
            strcat(binary, "0010");
        } else if(str[i] == '1' && str[i+1] == '1') {
            strcat(binary, "0011");
        }
    }
}

// Function to read a QR code from the user
void readQRCode(char *QRCode) {
    printf("Please scan the QR code:\n");
    fgets(QRCode, MAX_STRING_LENGTH, stdin);
    // Remove the newline character from the end of the string
    QRCode[strcspn(QRCode, "\n")] = 0;
}

int main() {
    char QRCode[MAX_STRING_LENGTH];
    char binary[MAX_STRING_LENGTH] = "";
    printf("Welcome to the QR code reader app!\n");
    while(true) {
        readQRCode(QRCode);
        if(isQRCode(QRCode)) {
            QRCodeToBinary(QRCode, binary);
            printf("QR code detected and converted to binary: %s\n", binary);
            break;
        } else {
            printf("Invalid QR code. Please try again.\n");
        }
    }
    return 0;
}

