#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    unsigned char character;
    unsigned char bit;
    int frequency;
    struct node* left;
    struct node* right;
} Node;

typedef struct heap {
    Node* array[256];
    int size;
} Heap;

void init_heap(Heap* heap) {
    heap->size = 0;
}

void swap_nodes(Heap* heap, int i, int j) {
    Node* temp = heap->array[i];
    heap->array[i] = heap->array[j];
    heap->array[j] = temp;
}

void bubble_up(Heap* heap, int index) {
    if (index > 0) {
        int parent = (index - 1) / 2;
        if (heap->array[parent]->frequency > heap->array[index]->frequency) {
            swap_nodes(heap, parent, index);
            bubble_up(heap, parent);
        }
    }
}

void bubble_down(Heap* heap, int index) {
    int left = index * 2 + 1;
    int right = index * 2 + 2;
    int min_index = index;
    if (left < heap->size && heap->array[left]->frequency < heap->array[min_index]->frequency) {
        min_index = left;
    }
    if (right < heap->size && heap->array[right]->frequency < heap->array[min_index]->frequency) {
        min_index = right;
    }
    if (min_index != index) {
        swap_nodes(heap, index, min_index);
        bubble_down(heap, min_index);
    }
}

void insert(Heap* heap, Node* node) {
    heap->array[heap->size] = node;
    heap->size++;
    bubble_up(heap, heap->size - 1);
}

Node* extract_min(Heap* heap) {
    Node* min = heap->array[0];
    heap->array[0] = heap->array[heap->size - 1];
    heap->size--;
    bubble_down(heap, 0);
    return min;
}

Node* build_huffman_tree(int* frequencies) {
    Heap heap;
    init_heap(&heap);
    for (int i = 0; i < 256; i++) {
        if (frequencies[i] > 0) {
            Node* node = (Node*) malloc(sizeof(Node));
            node->character = i;
            node->bit = 0;
            node->frequency = frequencies[i];
            node->left = NULL;
            node->right = NULL;
            insert(&heap, node);
        }
    }
    while (heap.size > 1) {
        Node* node1 = extract_min(&heap);
        Node* node2 = extract_min(&heap);
        Node* new_node = (Node*) malloc(sizeof(Node));
        new_node->character = 0;
        new_node->bit = 0;
        new_node->frequency = node1->frequency + node2->frequency;
        new_node->left = node1;
        new_node->right = node2;
        insert(&heap, new_node);
    }
    return extract_min(&heap);
}

void assign_codes(Node* node, unsigned char code, int depth) {
    if (node->left == NULL && node->right == NULL) {
        node->bit = code;
        printf("Character '%c' (ASCII %d) has code: ", node->character, node->character);
        for (int i = depth - 1; i >= 0; i--) {
            if (code & (1 << i)) {
                printf("1");
            } else {
                printf("0");
            }
        }
        printf("\n");
    } else {
        assign_codes(node->left, code << 1, depth + 1);
        assign_codes(node->right, (code << 1) | 1, depth + 1);
    }
}

void destroy_tree(Node* node) {
    if (node != NULL) {
        destroy_tree(node->left);
        destroy_tree(node->right);
        free(node);
    }
}

void huffman(int* frequencies) {
    Node* root = build_huffman_tree(frequencies);
    assign_codes(root, 0, 0);
    destroy_tree(root);
}

int main() {
    int frequencies[256] = {0};
    char input[1024];
    printf("Enter a string to Huffman encode: ");
    scanf("%[^\n]", input);
    for (int i = 0; input[i] != '\0'; i++) {
        frequencies[input[i]]++;
    }
    huffman(frequencies);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 1000                        // Maximum size of the input file
#define DICTIONARY_SIZE 500                  // Maximum size of the dictionary

// Structure of a single node in the dictionary
typedef struct Node {
    char data;
    int code;
    struct Node* next;
} Node;

// Function declarations
void compress(char* input_file, char* output_file);
Node* build_dictionary(char* input_file);
int search_dictionary(Node* dictionary, char c);
void add_to_dictionary(Node** dictionary, char c, int code);
void print_dictionary(Node* dictionary);
void write_to_file(int* buffer, int count, FILE* fp);

// Main function
int main() {
    char* input_file = "input.txt";          // Input file
    char* output_file = "output.bin";        // Compressed file

    compress(input_file, output_file);

    return 0;
}

// Function that performs the compression operation
void compress(char* input_file, char* output_file) {
    Node* dictionary = build_dictionary(input_file);  // Build the dictionary from input file
    FILE* in_fp = fopen(input_file, "r");             // Open input file for reading
    FILE* out_fp = fopen(output_file, "wb");          // Open output file for writing

    if (in_fp == NULL || out_fp == NULL) {
        printf("Error opening file");
        exit(1);
    }

    int buffer[MAX_SIZE];                 // Buffer to store the binary code
    int count = 0;                        // Counter to keep track of buffer size
    char c;
    int code;
    int dictionary_index;

    // Traverse the input file and compress each character using dictionary entries
    while ((c = fgetc(in_fp)) != EOF) {
        dictionary_index = search_dictionary(dictionary, c);
        code = dictionary_index + DICTIONARY_SIZE;
        buffer[count++] = code;
        add_to_dictionary(&dictionary, c, code);
    }

    // Write the compressed binary code to the output file
    write_to_file(buffer, count, out_fp);

    // Free memory allocated to the dictionary
    Node* temp;
    while (dictionary != NULL) {
        temp = dictionary;
        dictionary = dictionary->next;
        free(temp);
    }

    fclose(in_fp);                       // Close input file
    fclose(out_fp);                      // Close output file
}

// Function that builds the initial dictionary from the input file
Node* build_dictionary(char* input_file) {
    FILE* in_fp = fopen(input_file, "r");  // Open input file for reading
    Node* dictionary = NULL;

    if (in_fp == NULL) {
        printf("Error opening file");
        exit(1);
    }

    char c;
    int code = 0;

    // Traverse the input file and add each unique character to the dictionary
    while ((c = fgetc(in_fp)) != EOF) {
        if (search_dictionary(dictionary, c) == -1) {
            add_to_dictionary(&dictionary, c, code++);
        }
    }

    fclose(in_fp);                       // Close input file

    return dictionary;
}

// Function that searches the dictionary for a given character and returns its code
int search_dictionary(Node* dictionary, char c) {
    Node* temp = dictionary;

    while (temp != NULL) {
        if (temp->data == c) {
            return temp->code;
        }
        temp = temp->next;
    }
    return -1;
}

// Function that adds a new character and its code to the dictionary
void add_to_dictionary(Node** dictionary, char c, int code) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->data = c;
    new_node->code = code;
    new_node->next = *dictionary;
    *dictionary = new_node;
}

// Function that prints the dictionary
void print_dictionary(Node* dictionary) {
    printf("Dictionary:\n");
    Node* temp = dictionary;
    while (temp != NULL) {
        printf("%c: %d\n", temp->data, temp->code);
        temp = temp->next;
    }
    printf("\n");
}

// Function that writes the compressed binary code to the output file
void write_to_file(int* buffer, int count, FILE* fp) {
    int i, j;
    char byte = 0;
    int bit_position = 8;

    for (i = 0; i < count; i++) {
        for (j = 10; j >= 0; j--) {
            if ((buffer[i] >> j) & 1) {
                byte |= 1 << --bit_position;
            }
            else {
                bit_position--;
            }
            if (bit_position == 0) {
                fwrite(&byte, sizeof(char), 1, fp);
                byte = 0;
                bit_position = 8;
            }
        }
    }

    if (bit_position != 8) {
        byte <<= bit_position;
        fwrite(&byte, sizeof(char), 1, fp);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ENTRIES 100
#define NAME_LENGTH 50
#define MESSAGE_LENGTH 200

typedef struct {
    char name[NAME_LENGTH];
    char message[MESSAGE_LENGTH];
} LoveLetter;

LoveLetter database[MAX_ENTRIES];
int current_size = 0;

void addLetter(const char *name, const char *message) {
    if (current_size < MAX_ENTRIES) {
        strncpy(database[current_size].name, name, NAME_LENGTH);
        strncpy(database[current_size].message, message, MESSAGE_LENGTH);
        current_size++;
        printf("A new letter hath been added, sweet words from %s.\n", name);
    } else {
        printf("Alack! The database is full, cannot add more letters.\n");
    }
}

void displayLetters() {
    if (current_size == 0) {
        printf("No letters to display, thy hearts lie still.\n");
        return;
    }

    printf("\n--- Love Letters Database ---\n");
    for (int i = 0; i < current_size; i++) {
        printf("Letter %d:\n", i + 1);
        printf("From: %s\n", database[i].name);
        printf("Message: %s\n", database[i].message);
        printf("---------------------------\n");
    }
}

void searchLettersByName(const char *name) {
    int found = 0;
    printf("\nSearching letters from %s...\n", name);
    for (int i = 0; i < current_size; i++) {
        if (strcmp(database[i].name, name) == 0) {
            printf("Letter %d:\n", i + 1);
            printf("From: %s\n", database[i].name);
            printf("Message: %s\n", database[i].message);
            printf("---------------------------\n");
            found = 1;
        }
    }
    if (!found) {
        printf("No letters found from %s, a love lost in the fabric of time.\n", name);
    }
}

int main() {
    char name[NAME_LENGTH];
    char message[MESSAGE_LENGTH];
    int choice;

    printf("Welcome to the Love Letters Database, a tale of hearts entwined.\n");

    while (1) {
        printf("\nSelect thy action:\n");
        printf("1. Add a Love Letter\n");
        printf("2. Display All Love Letters\n");
        printf("3. Search Love Letters by Name\n");
        printf("4. Exit\n");
        printf("Enter thy choice: ");
        scanf("%d", &choice);
        getchar(); // clear newline after choice input

        switch (choice) {
            case 1:
                printf("Enter thy name (Romeo, Juliet, etc.): ");
                fgets(name, NAME_LENGTH, stdin);
                name[strcspn(name, "\n")] = 0; // remove newline char

                printf("Enter thy heart's message: ");
                fgets(message, MESSAGE_LENGTH, stdin);
                message[strcspn(message, "\n")] = 0; // remove newline char

                addLetter(name, message);
                break;
            case 2:
                displayLetters();
                break;
            case 3:
                printf("Whose letters dost thou seek? ");
                fgets(name, NAME_LENGTH, stdin);
                name[strcspn(name, "\n")] = 0; // remove newline char

                searchLettersByName(name);
                break;
            case 4:
                printf("Farewell! Thy heart's desires linger on...\n");
                return 0;
            default:
                printf("Soft! An invalid choice, choose wisely.\n");
        }
    }

    return 0;
}

