void display_single_record(struct record *records, int num_records) {
    int account_number;

    if (num_records == 0) {
        printf("No records found\n");
        return;
    }

    printf("Enter account number: ");
    scanf("%d", &account_number);

    for (int i = 0; i < num_records; i++) {
        if (records[i].account_number == account_number) {
            printf("%-20s\t\t%-10d\t\t%.2f\n", records[i].customer_name, records[i].account_number, records[i].balance);
            return;
        }
    }

    printf("No record found with account number %d\n", account_number);
}

void deposit_amount(struct record *records, int num_records) {
    int account_number;
    float amount;

    if (num_records == 0) {
        printf("No records found\n");
        return;
    }

    printf("Enter account number: ");
    scanf("%d", &account_number);

    for (int i = 0; i < num_records; i++) {
        if (records[i].account_number == account_number) {
            printf("Enter amount to deposit: ");
            scanf("%f", &amount);

            records[i].balance += amount;

            printf("Deposit successful\n");
            printf("New balance for account %d: %.2f\n", account_number, records[i].balance);

            return;
        }
    }

    printf("No record found with account number %d\n", account_number);
}

void withdraw_amount(struct record *records, int num_records) {
    int account_number;
    float amount;

    if (num_records == 0) {
        printf("No records found\n");
        return;
    }

    printf("Enter account number: ");
    scanf("%d", &account_number);

    for (int i = 0; i < num_records; i++) {
        if (records[i].account_number == account_number) {
            printf("Enter amount to withdraw: ");
            scanf("%f", &amount);

            if (amount <= records[i].balance) {
                records[i].balance -= amount;

                printf("Withdrawal successful\n");
                printf("New balance for account %d: %.2f\n", account_number, records[i].balance);
            } else {
                printf("Insufficient balance\n");
            }

            return;
        }
    }

    printf("No record found with account number %d\n", account_number);
}

/*
 * GPS Navigation Simulation Program
 *
 * This program simulates the navigation of a GPS receiver using a
 * set of predefined locations and a set of predefined navigation
 * instructions.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_LOCATIONS 100
#define MAX_INSTRUCTIONS 100

/* Structure to store location information */
typedef struct {
    char name[20];
    double latitude;
    double longitude;
} location_t;

/* Structure to store navigation instruction information */
typedef struct {
    char instruction[20];
    double distance;
    double direction;
} instruction_t;

/* Function to calculate the distance between two locations */
double calculate_distance(location_t location1, location_t location2) {
    double R = 6371; // Earth radius in km
    double d_lat = (location2.latitude - location1.latitude) * (M_PI / 180);
    double d_lon = (location2.longitude - location1.longitude) * (M_PI / 180);
    double a = sin(d_lat / 2) * sin(d_lat / 2) +
              cos(location1.latitude * (M_PI / 180)) * cos(location2.latitude * (M_PI / 180)) *
              sin(d_lon / 2) * sin(d_lon / 2);
    double c = 2 * atan2(sqrt(a), sqrt(1 - a));
    return R * c;
}

/* Function to calculate the direction between two locations */
double calculate_direction(location_t location1, location_t location2) {
    double d_lat = location2.latitude - location1.latitude;
    double d_lon = location2.longitude - location1.longitude;
    double y = sin(d_lon) * cos(location2.latitude * (M_PI / 180));
    double x = cos(location1.latitude * (M_PI / 180)) * sin(location2.latitude * (M_PI / 180)) -
              sin(location1.latitude * (M_PI / 180)) * cos(location2.latitude * (M_PI / 180)) *
              cos(d_lon);
    double direction = atan2(y, x) * (180 / M_PI);
    return direction;
}

/* Function to calculate the next location based on the current location and instruction */
location_t calculate_next_location(location_t current_location, instruction_t instruction) {
    double distance = instruction.distance;
    double direction = instruction.direction;
    double new_latitude = current_location.latitude + (distance / 111.3) * cos(direction * (M_PI / 180));
    double new_longitude = current_location.longitude + (distance / 111.3) * sin(direction * (M_PI / 180));
    location_t new_location = { "", new_latitude, new_longitude };
    return new_location;
}

/* Main function */
int main() {
    /* Initialize locations and instructions */
    location_t locations[MAX_LOCATIONS];
    instruction_t instructions[MAX_INSTRUCTIONS];
    int num_locations = 0;
    int num_instructions = 0;

    /* Read locations and instructions from file */
    FILE *fp = fopen("locations.txt", "r");
    if (fp == NULL) {
        printf("Error opening file\n");
        return 1;
    }
    char line[100];
    while (fgets(line, 100, fp) != NULL) {
        char *token;
        token = strtok(line, " ");
        if (token == NULL) {
            continue;
        }
        strcpy(locations[num_locations].name, token);
        token = strtok(NULL, " ");
        if (token == NULL) {
            continue;
        }
        locations[num_locations].latitude = atof(token);
        token = strtok(NULL, " ");
        if (token == NULL) {
            continue;
        }
        locations[num_locations].longitude = atof(token);
        num_locations++;
    }
    fclose(fp);

    fp = fopen("instructions.txt", "r");
    if (fp == NULL) {
        printf("Error opening file\n");
        return 1;
    }
    while (fgets(line, 100, fp) != NULL) {
        char *token;
        token = strtok(line, " ");
        if (token == NULL) {
            continue;
        }
        strcpy(instructions[num_instructions].instruction, token);
        token = strtok(NULL, " ");
        if (token == NULL) {
            continue;
        }
        instructions[num_instructions].distance = atof(token);
        token = strtok(NULL, " ");
        if (token == NULL) {
            continue;
        }
        instructions[num_instructions].direction = atof(token);
        num_instructions++;
    }
    fclose(fp);

    /* Simulate navigation */
    location_t current_location = { "START", 0, 0 };
    location_t next_location;
    for (int i = 0; i < num_instructions; i++) {
        next_location = calculate_next_location(current_location, instructions[i]);
        printf("Current location: %s\n", current_location.name);
        printf("Next location: %s\n", next_location.name);
        current_location = next_location;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <fcntl.h>

#define BUFFER_SIZE 1024
#define LOGIN_MSG "Login successful...\n"
#define WELCOME_MSG "Welcome to the cyberFTP server!\n"
#define ERROR_MSG "Error: "

void login(int sockfd) {
    char username[BUFFER_SIZE], password[BUFFER_SIZE];
    int res;
    printf("Enter username: ");
    fflush(stdout);
    scanf("%s", username);
    send(sockfd, username, strlen(username) + 1, 0);
    printf("Enter password: ");
    fflush(stdout);
    scanf("%s", password);
    send(sockfd, password, strlen(password) + 1, 0);
    recv(sockfd, &res, sizeof(res), 0);
    if (res != 0) {
        printf(ERROR_MSG "Login failed\n");
        exit(1);
    }
    printf(LOGIN_MSG);
}

void receive_file(int sockfd, char* filename) {
    char buffer[BUFFER_SIZE];
    int recvfd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    while (1) {
        int bytesReceived = recv(sockfd, buffer, BUFFER_SIZE, 0);
        if (bytesReceived == 0) break;
        write(recvfd, buffer, bytesReceived);
    }
    close(recvfd);
}

void send_file(int sockfd, char* filename) {
    char buffer[BUFFER_SIZE];
    int sendfd = open(filename, O_RDONLY);
    while (1) {
        int bytesRead = read(sendfd, buffer, BUFFER_SIZE);
        if (bytesRead == 0) break;
        send(sockfd, buffer, bytesRead, 0);
    }
    close(sendfd);
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        printf(ERROR_MSG "Usage: %s [server IP] [username] [password]\n", argv[0]);
        exit(1);
    }

    struct sockaddr_in serv_addr;
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        printf(ERROR_MSG "Error opening socket.\n");
        exit(1);
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = inet_addr(argv[1]);
    serv_addr.sin_port = htons(21);

    if (connect(sockfd, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        printf(ERROR_MSG "Error connecting to server.\n");
        exit(1);
    }

    char msg[BUFFER_SIZE];
    recv(sockfd, msg, BUFFER_SIZE, 0);

    if (strcmp(msg, WELCOME_MSG) != 0) {
        printf(ERROR_MSG "Error receiving welcome message from server.\n");
        exit(1);
    }

    printf("Connected to cyberFTP server!\n");

    login(sockfd);

    char cmd[BUFFER_SIZE];
    char arg[BUFFER_SIZE];

    while (1) {
        printf("cyberFTP> ");
        fflush(stdout);

        scanf("%s", cmd);

        if (strcasecmp(cmd, "get") == 0) {
            scanf("%s", arg);
            send(sockfd, cmd, strlen(cmd) + 1, 0);
            send(sockfd, arg, strlen(arg) + 1, 0);

            int res;
            recv(sockfd, &res, sizeof(res), 0);
            if (res != 0) {
                printf(ERROR_MSG "Error receiving file from server.\n");
            }
            else {
                receive_file(sockfd, arg);
                printf("File %s received successfully.\n", arg);
            }
        }
        else if (strcasecmp(cmd, "put") == 0) {
            scanf("%s", arg);
            send(sockfd, cmd, strlen(cmd) + 1, 0);
            send(sockfd, arg, strlen(arg) + 1, 0);

            int res;
            recv(sockfd, &res, sizeof(res), 0);
            if (res != 0) {
                printf(ERROR_MSG "Error sending file to server.\n");
            }
            else {
                send_file(sockfd, arg);
                printf("File %s sent successfully.\n", arg);
            }
        }
        else if (strcasecmp(cmd, "quit") == 0) {
            send(sockfd, cmd, strlen(cmd) + 1, 0);
            break;
        }
        else {
            printf(ERROR_MSG "Invalid command.\n");
        }
    }

    close(sockfd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

#define MAX_FILENAME_LENGTH 255
#define BUFFER_SIZE 1024

// Function prototypes
void countFileContent(const char *filename, long *wordCount, long *lineCount, long *charCount);
void usage(const char *programName);
int isWhitespace(char ch);

int main(int argc, char *argv[]) {
    long wordCount = 0, lineCount = 0, charCount = 0;

    // Check if the correct number of arguments is passed
    if (argc != 2) {
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    // Count words, lines, and characters in the specified file
    countFileContent(argv[1], &wordCount, &lineCount, &charCount);

    // Display the results
    printf("File: %s\n", argv[1]);
    printf("Words: %ld\n", wordCount);
    printf("Lines: %ld\n", lineCount);
    printf("Characters: %ld\n", charCount);

    return EXIT_SUCCESS;
}

// Function to count words, lines, and characters in a file
void countFileContent(const char *filename, long *wordCount, long *lineCount, long *charCount) {
    FILE *file;
    char buffer[BUFFER_SIZE];

    // Open the file for reading
    file = fopen(filename, "r");
    if (!file) {
        perror("Could not open file");
        exit(EXIT_FAILURE);
    }

    // Read file content line by line
    while (fgets(buffer, BUFFER_SIZE, file)) {
        (*lineCount)++;  // Increment the line count
        *charCount += strlen(buffer);  // Increment the character count

        // Count words in the current line
        int inWord = 0;
        for (size_t i = 0; i < strlen(buffer); i++) {
            if (isWhitespace(buffer[i])) {
                if (inWord) {
                    (*wordCount)++;  // Increment word count if we've just exited a word
                    inWord = 0;  // Reset in-word flag
                }
            } else {
                inWord = 1;  // We're in a word
            }
        }
        if (inWord) {  // Check if the last segment is a word
            (*wordCount)++;
        }
    }

    // Close the file
    fclose(file);
}

// Function to display how to use the program
void usage(const char *programName) {
    fprintf(stderr, "Usage: %s <filename>\n", programName);
}

// Function to determine if a character is a whitespace
int isWhitespace(char ch) {
    return (ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r');
}

