#include <stdlib.h>
#include <string.h>

typedef struct Node {
    struct Node* next;
    void* data;
    size_t size;
} Node;

typedef struct MemManager {
    Node* head;
    size_t size;
    size_t allocSize;
    size_t freeSize;
} MemManager;

MemManager* memManager_init(size_t size) {
    MemManager* manager = malloc(sizeof(MemManager));
    manager->head = NULL;
    manager->size = size;
    manager->allocSize = 0;
    manager->freeSize = size;
    return manager;
}

void* memManager_alloc(MemManager* manager, size_t size) {
    if (manager->freeSize < size) {
        return NULL;
    }

    size_t allocSize = manager->allocSize + size;
    if (allocSize > manager->size) {
        return NULL;
    }

    Node* newNode = malloc(sizeof(Node) + size);
    newNode->next = manager->head;
    manager->head = newNode;
    manager->allocSize += size;
    manager->freeSize -= size;

    return (void*)newNode->data;
}

void memManager_free(MemManager* manager, void* ptr) {
    Node* node = manager->head;
    while (node) {
        if (node->data == ptr) {
            manager->allocSize -= node->size;
            manager->freeSize += node->size;
            free(node);
            manager->head = node->next;
            return;
        }
        node = node->next;
    }

    return NULL;
}

int main() {
    MemManager* manager = memManager_init(1024);
    void* ptr = memManager_alloc(manager, 16);
    memcpy(ptr, "Hello, world!", 16);
    memManager_free(manager, ptr);

    return 0;
}

