const string

QualCSymbolMathCheck::getMessage (const ASTNode& node, const SBase& object)

{



  ostringstream msg;



  //msg << getPreamble();

  char * formula = SBML_formulaToString(&node);

  msg << "\nThe formula '" << formula;

  msg << "' in the math element of the " << getTypename(object);

  msg << " uses a csymbol.";

  safe_free(formula);



  return msg.str();

