// #define DEBUG 1  //调试开关
struct IO {
#define MAXSIZE (1 << 20)
#define isdigit(x) (x >= '0' && x <= '9')
    char buf[MAXSIZE], *p1, *p2;
    char pbuf[MAXSIZE], *pp;
#if DEBUG
#else
    IO() : p1(buf), p2(buf), pp(pbuf) {}
    ~IO() { fwrite(pbuf, 1, pp - pbuf, stdout); }
#endif
    inline char gc() {
#if DEBUG  //调试，可显示字符
        return getchar();
#endif
        if (p1 == p2) p2 = (p1 = buf) + fread(buf, 1, MAXSIZE, stdin);
        return p1 == p2 ? -1 : *p1++;
    }
    inline bool blank(char ch) { return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t'; }
    template <class T>
    inline void read(T &x) {
        register double tmp = 1;
        register bool sign = 0;
        x = 0;
        register char ch = gc();
        for (; !isdigit(ch); ch = gc())
            if (ch == '-') sign = 1;
        for (; isdigit(ch); ch = gc()) x = x * 10 + (ch - '0');
        if (ch == '.')
            for (ch = gc(); isdigit(ch); ch = gc()) tmp /= 10.0, x += tmp * (ch - '0');
        if (sign) x = -x;
    }
    inline void read(char *s) {
        register char ch = gc();
        for (; blank(ch); ch = gc())
            ;
        for (; !blank(ch); ch = gc()) *s++ = ch;
        *s = 0;
    }
    inline void read(char &c) {
        for (c = gc(); blank(c); c = gc())
            ;
    }
    inline void push(const char &c) {
#if DEBUG  //调试，可显示字符
        putchar(c);
#else
        if (pp - pbuf == MAXSIZE) fwrite(pbuf, 1, MAXSIZE, stdout), pp = pbuf;
        *pp++ = c;
#endif
    }
    template <class T>
    inline void write(T x) {
        if (x < 0) x = -x, push('-');  // 负数输出
        static T sta[35];
        T top = 0;
        do {
            sta[top++] = x % 10, x /= 10;
        } while (x);
        while (top) push(sta[--top] + '0');
    }
    inline void write(const char *s) {
        while (*s != '\0') push(*(s++));
    }
    template <class T>
    inline void write(T x, char lastChar) {
        write(x), push(lastChar);
    }
} io;

int a[510][510];

int main() {
#ifdef LOCAL
    freopen("input", "r", stdin);
#endif
    int n;
    io.read(n);
    rep(i, 1, n) {
        rep(j, i + 1, n) {
            io.read(a[i][j]);
            a[j][i] = a[i][j];
        }
    }
    int ans = 0;
    rep(i, 1, n) {
        std::sort(a[i] + 1, a[i] + 1 + n);
        ans = std::max(ans, a[i][n - 1]);
    }
    io.write("1\n");
    io.write(ans);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ENTRIES 100

typedef struct {
    char name[50];
    char number[15];
} entry;

int main() {
    entry phonebook[MAX_ENTRIES];
    int numEntries = 0;
    int choice;
    char searchName[50];
    char newName[50];
    char newNumber[15];

    system("clear");
    printf("Welcome to the Phone Book!\n");

    while(1) {
        printf("\nWhat would you like to do?\n");
        printf("1. Add a new entry\n");
        printf("2. Search for an entry\n");
        printf("3. Exit\n");
        scanf("%d", &choice);

        if(choice == 1) {
            printf("\nEnter the name for the new entry: ");
            scanf("%s", newName);

            for(int i = 0; i < numEntries; i++) {
                if(strcmp(phonebook[i].name, newName) == 0) {
                    printf("\nThis name already exists. Please enter a different name.\n");
                    continue;
                }
            }

            printf("\nEnter the phone number for the new entry: ");
            scanf("%s", newNumber);

            strcpy(phonebook[numEntries].name, newName);
            strcpy(phonebook[numEntries].number, newNumber);
            numEntries++;

            printf("\nEntry added successfully!\n");
        }
        else if(choice == 2) {
            printf("\nEnter the name to search: ");
            scanf("%s", searchName);

            for(int i = 0; i < numEntries; i++) {
                if(strcmp(phonebook[i].name, searchName) == 0) {
                    printf("\n%s - %s\n", phonebook[i].name, phonebook[i].number);
                    break;
                }
            }
        }
        else if(choice == 3) {
            printf("\nExiting program...\n");
            break;
        }
        else {
            printf("\nInvalid choice. Please try again.\n");
        }

        system("clear");
    }

    return 0;
}

