/*--------------------------------------------------------------
 *  This is an example from the Inventor Mentor,
 *  chapter 4, example 1.
 *
 *  Camera example.  
 *  A blinker node is used to switch between three 
 *  different views of the same scene. The cameras are 
 *  switched once per second.
 *------------------------------------------------------------*/

#include <cstdlib>
#include <Inventor/SbLinear.h>

#include <Inventor/SoDB.h>
#include <Inventor/SoInput.h>
#include <Inventor/Xt/SoXt.h>
#include <Inventor/Xt/SoXtRenderArea.h>
#include <Inventor/nodes/SoBlinker.h>
#include <Inventor/nodes/SoDirectionalLight.h>
#include <Inventor/nodes/SoMaterial.h>
#include <Inventor/nodes/SoOrthographicCamera.h>
#include <Inventor/nodes/SoPerspectiveCamera.h>
#include <Inventor/nodes/SoSeparator.h>
#include <Inventor/nodes/SoTransform.h>

int
main(int, char **argv)
{
   // Initialize Inventor and Xt
   Widget myWindow = SoXt::init(argv[0]);
   if (myWindow == NULL) exit(1);

   SoSeparator *root = new SoSeparator;
   root->ref();

   // Create a blinker node and put it in the scene. A blinker
   // switches between its children at timed intervals.
   SoBlinker *myBlinker = new SoBlinker;
   root->addChild(myBlinker);

   // Create three cameras. Their positions will be set later.
   // This is because the viewAll method depends on the size
   // of the render area, which has not been created yet.
   SoOrthographicCamera *orthoViewAll =new SoOrthographicCamera;
   SoPerspectiveCamera *perspViewAll = new SoPerspectiveCamera;
   SoPerspectiveCamera *perspOffCenter =new SoPerspectiveCamera;
   myBlinker->addChild(orthoViewAll);
   myBlinker->addChild(perspViewAll);
   myBlinker->addChild(perspOffCenter);

   // Create a light
   root->addChild(new SoDirectionalLight);

   // Read the object from a file and add to the scene
   SoInput myInput;
   if (!myInput.openFile("/usr/share/src/Inventor/examples/data/parkbench.iv")) 
      exit (1);
   SoSeparator *fileContents = SoDB::readAll(&myInput);
   if (fileContents == NULL) 
      exit (1);

   SoMaterial *myMaterial = new SoMaterial;
   myMaterial->diffuseColor.setValue(0.8, 0.23, 0.03); 
   root->addChild(myMaterial);
   root->addChild(fileContents);

   SoXtRenderArea *myRenderArea = new SoXtRenderArea(myWindow);

   // Establish camera positions. 
   // First do a viewAll on all three cameras.  
   // Then modify the position of the off-center camera.
   SbViewportRegion myRegion(myRenderArea->getSize());
   orthoViewAll->viewAll(root, myRegion);
   perspViewAll->viewAll(root, myRegion);
   perspOffCenter->viewAll(root, myRegion);
   SbVec3f initialPos; 
   initialPos = perspOffCenter->position.getValue();
   float x, y, z;
   initialPos.getValue(x,y,z);
   perspOffCenter->position.setValue(x+x/2., y+y/2., z+z/4.);

   myRenderArea->setSceneGraph(root);
   myRenderArea->setTitle("Cameras");
   myRenderArea->show();

   SoXt::show(myWindow);
   SoXt::mainLoop();
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CLIENT_LENGTH 1024
#define MAX_PACKET_LENGTH 1024

int main(int argc, char *argv[]) {
  int sock = socket(AF_INET, SOCK_STREAM, 0);
  if (sock < 0) {
    perror("socket failed");
    exit(EXIT_FAILURE);
  }

  struct sockaddr_in server_addr;
  server_addr.sin_family = AF_INET;
  server_addr.sin_port = htons(8080);
  inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

  if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
    perror("bind failed");
    exit(EXIT_FAILURE);
  }

  if (listen(sock, 3) < 0) {
    perror("listen failed");
    exit(EXIT_FAILURE);
  }

  while (1) {
    int client_sock = accept(sock, NULL, NULL);
    if (client_sock < 0) {
      perror("accept failed");
      continue;
    }

    char client_address[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &server_addr.sin_addr, client_address, sizeof(client_address));
    printf("Accepted connection from %s\n", client_address);

    char packet[MAX_PACKET_LENGTH];
    int packet_len = recv(client_sock, packet, MAX_PACKET_LENGTH, 0);
    if (packet_len < 0) {
      perror("recv failed");
      close(client_sock);
      continue;
    }

    // Drop any packets that are not from a trusted source
    if (strcmp(packet, "Hello from an untrusted source") != 0) {
      close(client_sock);
      continue;
    }

    // Allow packets from trusted sources
    char *ptr = packet;
    while (*ptr != '\0') {
      printf("%c", *ptr);
      ptr++;
    }

    close(client_sock);
  }

  close(sock);
  return 0;
}

#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>

// Graph data structure
typedef struct graph {
    int V;              // Number of vertices
    int E;              // Number of edges
    int **adj;          // Adjacency matrix
} graph;

// Create a new graph
graph *create_graph(int V) {
    graph *g = malloc(sizeof(graph));
    g->V = V;
    g->E = 0;
    g->adj = malloc(V * sizeof(int *));
    for (int i = 0; i < V; i++) {
        g->adj[i] = malloc(V * sizeof(int));
        for (int j = 0; j < V; j++) {
            g->adj[i][j] = 0;
        }
    }
    return g;
}

// Add an edge to the graph
void add_edge(graph *g, int u, int v, int weight) {
    g->adj[u][v] = weight;
    g->adj[v][u] = weight;
    g->E++;
}

// Print the adjacency matrix of the graph
void print_graph(graph *g) {
    for (int i = 0; i < g->V; i++) {
        for (int j = 0; j < g->V; j++) {
            printf("%d ", g->adj[i][j]);
        }
        printf("\n");
    }
}

// Free the memory allocated to the graph
void free_graph(graph *g) {
    for (int i = 0; i < g->V; i++) {
        free(g->adj[i]);
    }
    free(g->adj);
    free(g);
}

// Main function
int main() {
    // Create a new graph
    graph *g = create_graph(5);

    // Add edges to the graph
    add_edge(g, 0, 1, 1);
    add_edge(g, 0, 2, 2);
    add_edge(g, 1, 2, 3);
    add_edge(g, 1, 3, 4);
    add_edge(g, 2, 3, 5);
    add_edge(g, 3, 4, 6);

    // Print the adjacency matrix of the graph
    printf("Adjacency matrix:\n");
    print_graph(g);

    // Free the memory allocated to the graph
    free_graph(g);

    return 0;
}

