const FX_FLOAT curve_collinearity_epsilon              = 1e-30f;
enum curve_recursion_limit_e { curve_recursion_limit = 16 };
void curve4_div::init(FX_FLOAT x1, FX_FLOAT y1,
                      FX_FLOAT x2, FX_FLOAT y2,
                      FX_FLOAT x3, FX_FLOAT y3,
                      FX_FLOAT x4, FX_FLOAT y4)
{
    m_points.remove_all();
    m_distance_tolerance_square = 1.0f / 4;
    m_distance_tolerance_manhattan = 1.0f * 4;
    bezier(x1, y1, x2, y2, x3, y3, x4, y4);
    m_count = 0;
}
void curve4_div::recursive_bezier(FX_FLOAT x1, FX_FLOAT y1,
                                  FX_FLOAT x2, FX_FLOAT y2,
                                  FX_FLOAT x3, FX_FLOAT y3,
                                  FX_FLOAT x4, FX_FLOAT y4,
                                  unsigned level)
{
    if(level > curve_recursion_limit) {
        return;
    }
    FX_FLOAT x12   = (x1 + x2) / 2;
    FX_FLOAT y12   = (y1 + y2) / 2;
    FX_FLOAT x23   = (x2 + x3) / 2;
    FX_FLOAT y23   = (y2 + y3) / 2;
    FX_FLOAT x34   = (x3 + x4) / 2;
    FX_FLOAT y34   = (y3 + y4) / 2;
    FX_FLOAT x123  = (x12 + x23) / 2;
    FX_FLOAT y123  = (y12 + y23) / 2;
    FX_FLOAT x234  = (x23 + x34) / 2;
    FX_FLOAT y234  = (y23 + y34) / 2;
    FX_FLOAT x1234 = (x123 + x234) / 2;
    FX_FLOAT y1234 = (y123 + y234) / 2;
    FX_FLOAT dx = x4 - x1;
    FX_FLOAT dy = y4 - y1;
    FX_FLOAT d2 = FXSYS_fabs(FXSYS_Mul(x2 - x4, dy) - FXSYS_Mul(y2 - y4, dx));
    FX_FLOAT d3 = FXSYS_fabs(FXSYS_Mul(x3 - x4, dy) - FXSYS_Mul(y3 - y4, dx));
    switch((int(d2 > curve_collinearity_epsilon) << 1) +
            int(d3 > curve_collinearity_epsilon)) {
        case 0:
            if(FXSYS_fabs(x1 + x3 - x2 - x2) +
                    FXSYS_fabs(y1 + y3 - y2 - y2) +
                    FXSYS_fabs(x2 + x4 - x3 - x3) +
                    FXSYS_fabs(y2 + y4 - y3 - y3) <= m_distance_tolerance_manhattan) {
                m_points.add(point_type(x1234, y1234, path_flags_jr));
                return;
            }
            break;
        case 1:
            if(FXSYS_Mul(d3, d3) <= FXSYS_Mul(m_distance_tolerance_square,
                                              FXSYS_Mul(dx, dx) + FXSYS_Mul(dy, dy))) {
                m_points.add(point_type(x23, y23, path_flags_jr));
                return;
            }
            break;
        case 2:
            if(FXSYS_Mul(d2, d2) <= FXSYS_Mul(m_distance_tolerance_square,
                                              FXSYS_Mul(dx, dx) + FXSYS_Mul(dy, dy))) {
                m_points.add(point_type(x23, y23, path_flags_jr));
                return;
            }
            break;
        case 3:
            if(FXSYS_Mul(d2 + d3, d2 + d3) <= FXSYS_Mul(m_distance_tolerance_square,
                    FXSYS_Mul(dx, dx) + FXSYS_Mul(dy, dy))) {
                m_points.add(point_type(x23, y23, path_flags_jr));
                return;
            }
            break;
    }
    recursive_bezier(x1, y1, x12, y12, x123, y123, x1234, y1234, level + 1);
    recursive_bezier(x1234, y1234, x234, y234, x34, y34, x4, y4, level + 1);
}
void curve4_div::bezier(FX_FLOAT x1, FX_FLOAT y1,
                        FX_FLOAT x2, FX_FLOAT y2,
                        FX_FLOAT x3, FX_FLOAT y3,
                        FX_FLOAT x4, FX_FLOAT y4)
{
    m_points.add(point_type(x1, y1));
    recursive_bezier(x1, y1, x2, y2, x3, y3, x4, y4, 0);
    m_points.add(point_type(x4, y4));
}
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <assert.h>

#define MAX_WORD_LEN 256
#define MAX_LOG_LEN 1024

struct word {
    char *word;
    int freq;
};

int main(void) {
    char log[MAX_LOG_LEN];
    struct word *words = NULL;
    int word_count = 0;

    // read log file
    FILE *log_file = fopen("log.txt", "r");
    assert(log_file != NULL);
    while (fgets(log, MAX_LOG_LEN, log_file) != NULL) {
        // tokenize log line
        char *token = strtok(log, " ");
        while (token != NULL && token[0] != '\0') {
            // check if word is not empty and not a whitespace
            if (token[0] != ' ' && token[0] != '\0') {
                // count word frequency
                int freq = 1;
                for (int i = 0; i < word_count; i++) {
                    if (strcmp(words[i].word, token) == 0) {
                        freq = words[i].freq + freq;
                        break;
                    }
                }
                if (freq > words[word_count - 1].freq) {
                    // add word to list
                    words = realloc(words, (word_count + 1) * sizeof(struct word));
                    words[word_count].word = token;
                    words[word_count].freq = freq;
                    word_count++;
                }
            }
            token = strtok(NULL, " ");
        }
    }
    fclose(log_file);

    // print summary
    printf("Top words and their frequencies:\n");
    for (int i = 0; i < word_count; i++) {
        printf("%d. %s (%d)\n", i + 1, words[i].word, words[i].freq);
    }

    // free memory
    free(words);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define ROWS 5
#define COLS 5

int main() {
    int matrix[ROWS][COLS];

    // Initialize the matrix with random values from 1-20
    for(int i=0; i<ROWS; i++) {
        for(int j=0; j<COLS; j++) {
            matrix[i][j] = (rand() % 20) + 1;
        }
    }

    // Print the matrix before manipulation
    printf("Original Matrix:\n");
    for(int i=0; i<ROWS; i++) {
        for(int j=0; j<COLS; j++) {
            printf("%d\t", matrix[i][j]);
        }
        printf("\n");
    }

    // Find the maximum value in the matrix and its location
    int max = -1, max_row, max_col;
    for(int i=0; i<ROWS; i++) {
        for(int j=0; j<COLS; j++) {
            if(matrix[i][j] > max) {
                max = matrix[i][j];
                max_row = i;
                max_col = j;
            }
        }
    }
    printf("Maximum value in matrix: %d\n", max);
    printf("Location of maximum value: row %d, column %d\n", max_row, max_col);

    // Transpose the matrix
    int transpose[COLS][ROWS];
    for(int i=0; i<COLS; i++) {
        for(int j=0; j<ROWS; j++) {
            transpose[i][j] = matrix[j][i];
        }
    }

    // Print the transposed matrix
    printf("Transposed Matrix:\n");
    for(int i=0; i<COLS; i++) {
        for(int j=0; j<ROWS; j++) {
            printf("%d\t", transpose[i][j]);
        }
        printf("\n");
    }

    // Find the sum of each row in the transposed matrix
    int row_sums[COLS] = {0};
    for(int i=0; i<COLS; i++) {
        for(int j=0; j<ROWS; j++) {
            row_sums[i] += transpose[i][j];
        }
    }

    // Print the row sums
    printf("Row Sums:\n");
    for(int i=0; i<COLS; i++) {
        printf("Row %d: %d\n", i+1, row_sums[i]);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define ARRAY_SIZE 100

// Randomized searching algorithm
int search(int arr[], int low, int high, int target) {
  int mid = (low + high) / 2;
  int i = 0;
  int j = ARRAY_SIZE - 1;

  // Generate a random index between low and high
  int random_index = (low + high) * (rand() / (RAND_MAX + 1));

  // Check if the target is found
  if (arr[random_index] == target) {
    return random_index;
  }

  // If not found, search the left and right subarrays
  if (arr[random_index] < target) {
    // Search the left subarray
    for (i = low; i <= mid; i++) {
      if (arr[i] == target) {
        return i;
      }
    }
    // If still not found, search the right subarray
    for (j = mid + 1; j <= high; j++) {
      if (arr[j] == target) {
        return j;
      }
    }
  } else {
    // Search the right subarray
    for (j = mid + 1; j <= high; j++) {
      if (arr[j] == target) {
        return j;
      }
    }
    // If still not found, search the left subarray
    for (i = low; i <= mid; i++) {
      if (arr[i] == target) {
        return i;
      }
    }
  }

  // If still not found, return -1
  return -1;
}

int main() {
  int arr[ARRAY_SIZE] = {1, 2, 3, 4, 5, 6, 7, 8, 9};
  int target = 8;
  int index = search(arr, 0, ARRAY_SIZE - 1, target);

  if (index != -1) {
    printf("Target found at index %d\n", index);
  } else {
    printf("Target not found\n");
  }

  return 0;
}

#include "EnginePCH.hpp"

using namespace Poly;

//-----------------------------------------------------------------------------
TransformComponent::~TransformComponent() {
	if (Parent != nullptr)
	{
		Parent->Children.Remove(this);
	}
}

//-----------------------------------------------------------------------------
void TransformComponent::SetParent(TransformComponent* parent)
{
	if (parent != nullptr)
	{
		parent->UpdateGlobalTransformationCache();
		LocalTranslation = LocalTranslation - parent->GlobalTranslation;
		LocalRotation = LocalRotation * parent->GlobalRotation.GetConjugated();
		Vector parentGlobalScale = parent->GlobalScale;
		LocalScale.X = LocalScale.X / parentGlobalScale.X;
		LocalScale.Y = LocalScale.Y / parentGlobalScale.Y;
		LocalScale.Z = LocalScale.Z / parentGlobalScale.Z;
		UpdateLocalTransformationCache();

		Parent = parent;
		Parent->Children.PushBack(this);
	}
	else
	{
		ResetParent();
	}
}

//-----------------------------------------------------------------------------
void TransformComponent::ResetParent()
{
	ASSERTE(Parent, "ResetParent() called with parent == nullptr");
	Matrix globalTransform = GetGlobalTransformationMatrix();
	Parent->Children.Remove(this);
	Parent = nullptr;
	SetLocalTransformationMatrix(globalTransform);
}

//------------------------------------------------------------------------------
const Vector& TransformComponent::GetGlobalTranslation() const
{
	UpdateGlobalTransformationCache();
	return GlobalTranslation;
}

//------------------------------------------------------------------------------
void TransformComponent::SetLocalTranslation(const Vector& position)
{
	LocalTranslation = position;
	LocalDirty = true;
	SetGlobalDirty();
}

//------------------------------------------------------------------------------
const Quaternion& TransformComponent::GetGlobalRotation() const
{
	UpdateGlobalTransformationCache();
	return GlobalRotation;
}

//------------------------------------------------------------------------------
void TransformComponent::SetLocalRotation(const Quaternion& quaternion)
{
	LocalRotation = quaternion;
	LocalDirty = true;
	SetGlobalDirty();
}

//------------------------------------------------------------------------------
const Vector& TransformComponent::GetGlobalScale() const
{
	UpdateGlobalTransformationCache();
	return GlobalScale;
}

//------------------------------------------------------------------------------
void TransformComponent::SetLocalScale(const Vector& scale)
{
	LocalScale = scale;
	LocalDirty = true;
	SetGlobalDirty();
}

//------------------------------------------------------------------------------
const Matrix& TransformComponent::GetLocalTransformationMatrix() const
{
	UpdateLocalTransformationCache();
	return LocalTransform;
}

//------------------------------------------------------------------------------
const Matrix& TransformComponent::GetGlobalTransformationMatrix() const
{
	UpdateGlobalTransformationCache();
	return GlobalTransform;
}

//------------------------------------------------------------------------------
void TransformComponent::SetLocalTransformationMatrix(const Matrix& localTransformation)
{
	LocalTransform = localTransformation;
	localTransformation.Decompose(LocalTranslation, LocalRotation, LocalScale);
	LocalDirty = false;
	SetGlobalDirty();
}

//------------------------------------------------------------------------------
bool TransformComponent::UpdateLocalTransformationCache() const
{
	if (LocalDirty)
	{
		Matrix translation;
		Matrix rotation = LocalRotation.ToRotationMatrix();
		Matrix scale;
		translation.SetTranslation(LocalTranslation);
		scale.SetScale(LocalScale);
		LocalTransform = translation * rotation * scale;
		LocalDirty = false;
		return true;
	}
	return false;
}

//------------------------------------------------------------------------------
void TransformComponent::UpdateGlobalTransformationCache() const
{
	if (!GlobalDirty) return;
	if (Parent == nullptr)
	{
		GlobalTransform = GetLocalTransformationMatrix();
	}
	else
	{
		GlobalTransform = Parent->GetGlobalTransformationMatrix() * GetLocalTransformationMatrix();
	}
	GlobalTransform.Decompose(GlobalTranslation, GlobalRotation, GlobalScale);
	GlobalDirty = false;
}

//------------------------------------------------------------------------------
void TransformComponent::SetGlobalDirty() const
{
	GlobalDirty = true;
	for (TransformComponent* c : Children)
	{
		c->SetGlobalDirty();
	}
}

