#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <time.h>

#define WIDTH 21
#define HEIGHT 21

typedef struct {
    int x, y;
} point;

bool maze[HEIGHT][WIDTH];
bool visited[HEIGHT][WIDTH];
point start = {1, 1}, end = {WIDTH - 2, HEIGHT - 2};
point stack[WIDTH * HEIGHT / 2];
int top = -1;

void print_maze() {
    for (int i = 0; i < HEIGHT; ++i) {
        for (int j = 0; j < WIDTH; ++j) {
            printf(maze[i][j] ? "##" : "  ");
        }
        putchar('\n');
    }
}

void dfs(point cur) {
    visited[cur.y][cur.x] = true;
    stack[++top] = cur;

    if (cur.x == end.x && cur.y == end.y) {
        printf("Path found:\n");
        while (top >= 0) {
            point p = stack[top--];
            printf("(%d, %d) ", p.x, p.y);
        }
        putchar('\n');
        exit(0);
    }

    for (int dx = -2; dx <= 2; ++dx) {
        for (int dy = -2; dy <= 2; ++dy) {
            if (dx == 0 && dy == 0) continue;

            int nx = cur.x + dx, ny = cur.y + dy;
            if (nx >= 0 && nx < WIDTH && ny >= 0 && ny < HEIGHT &&
                !visited[ny][nx] && !maze[ny][nx]) {
                maze[ny][nx] = true;
                dfs((point){nx, ny});
                maze[ny][nx] = false;
            }
        }
    }
}

int main() {
    srand(time(NULL));

    for (int i = 0; i < HEIGHT; ++i)
        for (int j = 0; j < WIDTH; ++j)
            maze[i][j] = (i == HEIGHT / 2 || j == WIDTH / 2) ? false : rand() % 2;

    maze[start.y][start.x] = false;
    dfs(start);

    printf("Maze:\n");
    print_maze();

    return 0;
}

