int main() {
    FILE *file = fopen("data.txt", "r");
    if (file == NULL) {
        printf("Error reading file.\n");
        return 1;
    }

    readItemNames(file);
    processTransactions(file);
    getItemSupports();

    fclose(file);

    printf("Frequent itemsets:\n");
    printFrequentItemsets(3);

    printf("Closed itemsets:\n");
    printClosedItemsets(3);

    return 0;
}

// Read the names of the distinct items from the first line of the file
void readItemNames(FILE *file) {
    char *line = NULL;
    size_t len = 0;
    getline(&line, &len, file);

    char *token = strtok(line, " ");
    while (token != NULL) {
        strcpy(itemNames[numItems], token);
        items[numItems] = true;
        numItems++;
        token = strtok(NULL, " ");
    }

    free(line);
}

// Read the transactions from the rest of the file
void processTransactions(FILE *file) {
    char *line = NULL;
    size_t len = 0;

    while (getline(&line, &len, file) != -1) {
        char *token = strtok(line, " ");
        int i = 0;
        while (token != NULL) {
            int itemId = atoi(token);

            if (items[itemId - 1]) {
                transactions[numTransactions][i] = itemId - 1;
                i++;
            }

            token = strtok(NULL, " ");
        }

        numTransactions++;
    }

    free(line);
}

// Count the support of each item
void getItemSupports() {
    for (int i = 0; i < numItems; i++) {
        itemSupports[i] = 0;

        for (int j = 0; j < numTransactions; j++) {
            bool found = false;

            for (int k = 0; k < MAX_ITEMS_PER_TRANS && transactions[j][k] != -1; k++) {
                if (transactions[j][k] == i) {
                    found = true;
                    break;
                }
            }

            if (found) {
                itemSupports[i]++;
            }
        }
    }
}

// Print frequent itemsets with support greater than or equal to minSupp
void printFrequentItemsets(int minSupp) {
    int numItemsets = 0;
    int itemsets[MAX_NUM_ITEMS][MAX_ITEMS_PER_TRANS];

    for (int i = 0; i < numItems; i++) {
        if (itemSupports[i] >= minSupp) {
            itemsets[numItemsets][0] = i;
            itemsets[numItemsets][1] = -1;
            numItemsets++;
        }
    }

    for (int k = 2; k <= MAX_ITEMS_PER_TRANS; k++) {
        for (int i = 0; i < numItemsets; i++) {
            for (int j = i + 1; j < numItemsets; j++) {
                if (itemsets[i][k - 2] != itemsets[j][k - 2]) {
                    break;
                }

                int newItemset[MAX_ITEMS_PER_TRANS];

                for (int l = 0; l < k - 1; l++) {
                    newItemset[l] = itemsets[i][l];
                }

                newItemset[k - 1] = itemsets[j][k - 2];

                bool valid = true;

                for (int l = 0; l < k - 1; l++) {
                    for (int m = 0; m < k; m++) {
                        if (newItemset[l] == newItemset[m] || newItemset[m] == -1) {
                            continue;
                        }

                        int count = 0;

                        for (int n = 0; n < numTransactions; n++) {
                            bool found1 = false;
                            bool found2 = false;

                            for (int o = 0; o < MAX_ITEMS_PER_TRANS && transactions[n][o] != -1; o++) {
                                if (transactions[n][o] == newItemset[l]) {
                                    found1 = true;
                                }

                                if (transactions[n][o] == newItemset[m]) {
                                    found2 = true;
                                }
                            }

                            if (found1 && found2) {
                                count++;
                            }
                        }

                        if (count < minSupp) {
                            valid = false;
                            break;
                        }
                    }

                    if (!valid) {
                        break;
                    }
                }

                if (valid) {
                    int l = 0;
                    while (itemsets[numItemsets][l] != -1) {
                        l++;
                    }

                    for (int m = 0; m < k; m++) {
                        itemsets[numItemsets][l + m] = newItemset[m];
                    }

                    itemsets[numItemsets][l + k] = -1;
                    numItemsets++;
                }
            }
        }
    }

    for (int i = 0; i < numItemsets; i++) {
        printf("{ ");
        int j = 0;
        while (itemsets[i][j] != -1) {
            printf("%s ", itemNames[itemsets[i][j]]);
            j++;
        }
        printf("} (%d)\n", itemSupports[itemsets[i][0]]);
    }
}

// Print closed itemsets with support greater than or equal to minSupp
void printClosedItemsets(int minSupp) {
    int numClosedItemsets = 0;
    int closedItemsets[MAX_NUM_ITEMS][MAX_ITEMS_PER_TRANS];
    bool closedSet[MAX_NUM_ITEMS];

    for (int i = 0; i < numItems; i++) {
        closedSet[i] = true;
    }

    for (int i = 0; i < numItems; i++) {
        if (itemSupports[i] < minSupp) {
            closedSet[i] = false;
        }
    }

    for (int i = 0; i < numItems; i++) {
        if (closedSet[i]) {
            closedItemsets[numClosedItemsets][0] = i;
            closedItemsets[numClosedItemsets][1] = -1;
            numClosedItemsets++;
        }
    }

    for (int k = 2; k <= MAX_ITEMS_PER_TRANS; k++) {
        for (int i = 0; i < numClosedItemsets; i++) {
            bool isClosed = true;

            for (int j = 0; j < numItems; j++) {
                if (items[j] && closedSet[j] && itemSupports[j] >= minSupp) {
                    int newItemset[MAX_ITEMS_PER_TRANS];

                    for (int l = 0; l < k - 1; l++) {
                        newItemset[l] = closedItemsets[i][l];
                    }

                    newItemset[k - 1] = j;

                    bool valid = true;

                    for (int l = 0; l < k - 1; l++) {
                        int count1 = itemSupports[closedItemsets[i][l]];
                        int count2 = itemSupports[j];
                        int count3 = 0;

                        for (int m = 0; m < numTransactions; m++) {
                            bool found1 = false;
                            bool found2 = false;

                            for (int n = 0; n < MAX_ITEMS_PER_TRANS && transactions[m][n] != -1; n++) {
                                if (transactions[m][n] == closedItemsets[i][l]) {
                                    found1 = true;
                                }

                                if (transactions[m][n] == j) {
                                    found2 = true;
                                }
                            }

                            if (found1 && found2) {
                                count3++;
                            }
                        }

                        if (count1 == count2 && count3 == count1) {
                            valid = false;
                            break;
                        }
                    }

                    if (valid) {
                        int count1 = itemSupports[j];
                        int count2 = 0;

                        for (int l = 0; l < numTransactions; l++) {
                            bool found = true;

                            for (int m = 0; m < k; m++) {
                                if (transactions[l][m] == -1 || !closedSet[transactions[l][m]]) {
                                    found = false;
                                    break;
                                }
                            }

                            if (found) {
                                bool included = true;

                                for (int m = 0; m < k; m++) {
                                    if (transactions[l][m] == j) {
                                        included = false;
                                        break;
                                    }
                                }

                                if (included) {
                                    count2++;
                                }
                            }
                        }

                        if (count2 == count1) {
                            isClosed = false;
                            closedSet[j] = false;

                            int l = 0;
                            while (closedItemsets[numClosedItemsets][l] != -1) {
                                l++;
                            }

                            for (int m = 0; m < k; m++) {
                                closedItemsets[numClosedItemsets][l + m] = newItemset[m];
                            }

                            closedItemsets[numClosedItemsets][l + k] = -1;
                            numClosedItemsets++;
                        }
                    }
                }
            }

            if (isClosed) {
                printf("{ ");
                int j = 0;
                while (closedItemsets[i][j] != -1) {
                    printf("%s ", itemNames[closedItemsets[i][j]]);
                    j++;
                }
                printf("} (%d)\n", itemSupports[closedItemsets[i][0]]);
            }
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

// Define constants
#define MAX_FILENAME_LENGTH 50
#define MAX_COMMAND_LENGTH 10

// Define pixel struct
typedef struct Pixel {
    uint8_t red;
    uint8_t green;
    uint8_t blue;
} Pixel;

// Define image struct
typedef struct Image {
    Pixel** pixels;
    int width;
    int height;
} Image;

// Function to allocate memory for a new image
Image* create_image(int width, int height) {
    // Allocate memory for the struct
    Image* new_image = (Image*) malloc(sizeof(Image));

    // Allocate memory for the pixel array
    new_image->pixels = (Pixel**) malloc(sizeof(Pixel*) * height);
    for (int i = 0; i < height; i++) {
        new_image->pixels[i] = (Pixel*) malloc(sizeof(Pixel) * width);
    }

    // Set the width and height
    new_image->width = width;
    new_image->height = height;

    return new_image;
}

// Function to free memory allocated for an image
void destroy_image(Image* image) {
    // Free the pixel array memory
    for (int i = 0; i < image->height; i++) {
        free(image->pixels[i]);
    }
    free(image->pixels);

    // Free the struct memory
    free(image);
}

// Function to read an image from a file
Image* read_image_from_file(char* filename) {
    FILE* file = fopen(filename, "rb");

    // Check if file was opened successfully
    if (file == NULL) {
        printf("Error opening file %s\n", filename);
        exit(1);
    }

    // Read the width and height from the file
    int width, height;
    fread(&width, sizeof(int), 1, file);
    fread(&height, sizeof(int), 1, file);

    // Create a new image with the given dimensions
    Image* image = create_image(width, height);

    // Read the pixels from the file
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            fread(&(image->pixels[i][j]), sizeof(Pixel), 1, file);
        }
    }

    // Close the file
    fclose(file);

    return image;
}

// Function to write an image to a file
void write_image_to_file(Image* image, char* filename) {
    FILE* file = fopen(filename, "wb");

    // Write the width and height to the file
    fwrite(&(image->width), sizeof(int), 1, file);
    fwrite(&(image->height), sizeof(int), 1, file);

    // Write the pixels to the file
    for (int i = 0; i < image->height; i++) {
        for (int j = 0; j < image->width; j++) {
            fwrite(&(image->pixels[i][j]), sizeof(Pixel), 1, file);
        }
    }

    // Close the file
    fclose(file);
}

// Function to apply a grayscale filter to an image
void grayscale_filter(Image* image) {
    // Loop through all pixels
    for (int i = 0; i < image->height; i++) {
        for (int j = 0; j < image->width; j++) {
            // Calculate the grayscale value for each pixel
            uint8_t gray = (image->pixels[i][j].red + image->pixels[i][j].green + image->pixels[i][j].blue) / 3;
            image->pixels[i][j].red = gray;
            image->pixels[i][j].green = gray;
            image->pixels[i][j].blue = gray;
        }
    }
}

// Function to apply an invert filter to an image
void invert_filter(Image* image) {
    // Loop through all pixels
    for (int i = 0; i < image->height; i++) {
        for (int j = 0; j < image->width; j++) {
            // Invert each color value for each pixel
            image->pixels[i][j].red = 255 - image->pixels[i][j].red;
            image->pixels[i][j].green = 255 - image->pixels[i][j].green;
            image->pixels[i][j].blue = 255 - image->pixels[i][j].blue;
        }
    }
}

// Function to apply a sepia filter to an image
void sepia_filter(Image* image) {
    // Loop through all pixels
    for (int i = 0; i < image->height; i++) {
        for (int j = 0; j < image->width; j++) {
            // Calculate the sepia values for each color value for each pixel
            uint8_t gray = (image->pixels[i][j].red + image->pixels[i][j].green + image->pixels[i][j].blue) / 3;
            uint8_t sepia_red = gray + 40;
            uint8_t sepia_green = gray + 20;
            uint8_t sepia_blue = gray;

            // Clamp the values to between 0 and 255
            if (sepia_red > 255) {
                sepia_red = 255;
            }
            if (sepia_green > 255) {
                sepia_green = 255;
            }
            if (sepia_blue > 255) {
                sepia_blue = 255;
            }

            // Set the new color values for the pixel
            image->pixels[i][j].red = sepia_red;
            image->pixels[i][j].green = sepia_green;
            image->pixels[i][j].blue = sepia_blue;
        }
    }
}

int main() {
    // Allocate memory for the filename and command strings
    char* filename = (char*) malloc(sizeof(char) * MAX_FILENAME_LENGTH);
    char* command = (char*) malloc(sizeof(char) * MAX_COMMAND_LENGTH);

    // Loop until the user enters "exit"
    while (strcmp(command, "exit") != 0) {
        // Ask the user for a filename and command
        printf("Enter a filename (or 'exit' to quit):\n");
        scanf("%s", filename);

        if (strcmp(filename, "exit") != 0) {
            printf("Enter a command:\n");
            scanf("%s", command);

            // Read the image from the file
            Image* image = read_image_from_file(filename);

            // Apply the appropriate filter based on the command
            if (strcmp(command, "grayscale") == 0) {
                grayscale_filter(image);
            }
            else if (strcmp(command, "invert") == 0) {
                invert_filter(image);
            }
            else if (strcmp(command, "sepia") == 0) {
                sepia_filter(image);
            }
            else {
                printf("Command not recognized\n");
            }

            // Write the modified image to a new file
            char* output_filename = (char*) malloc(sizeof(char) * (strlen(filename) + 5));
            strcpy(output_filename, "new_");
            strcat(output_filename, filename);
            write_image_to_file(image, output_filename);

            // Free the image and output filename memory
            destroy_image(image);
            free(output_filename);
        }
    }

    // Free the filename and command memory
    free(filename);
    free(command);

    return 0;
}

