#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netdb.h>

#define BUF_SIZE 1024

int main(int argc, char *argv[]) {
    if (argc!= 3) {
        printf("Usage: %s <IP Address> <Port Number>\n", argv[0]);
        return 1;
    }

    char *ip_address = argv[1];
    int port_number = atoi(argv[2]);

    struct hostent *host_info;
    if ((host_info = gethostbyname(ip_address)) == NULL) {
        printf("Error: Invalid IP address.\n");
        return 1;
    }

    int sockfd;
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        printf("Error: Could not create socket.\n");
        return 1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port_number);
    inet_pton(AF_INET, inet_ntoa(*(struct in_addr *)host_info->h_addr), &server_addr.sin_addr);

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        printf("Error: Could not connect to server.\n");
        close(sockfd);
        return 1;
    }

    char send_buf[BUF_SIZE];
    strcpy(send_buf, "PING");
    send(sockfd, send_buf, strlen(send_buf), 0);

    char recv_buf[BUF_SIZE];
    int recv_len;
    if ((recv_len = recv(sockfd, recv_buf, BUF_SIZE, 0)) == -1) {
        printf("Error: Could not receive response.\n");
        close(sockfd);
        return 1;
    }

    printf("Response: %.*s\n", recv_len, recv_buf);

    close(sockfd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <sys/socket.h>
#include <errno.h>
#include <pthread.h>

#define MAX_BUFFER 65536
#define PORT_TO_MONITOR 8080
#define FIREWALL_LOG "firewall_log.txt"

typedef struct {
    struct sockaddr_in addr;
    char payload[MAX_BUFFER];
    int len;
} packet_info;

void log_packet(const packet_info *packet) {
    FILE *log_file = fopen(FIREWALL_LOG, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "Source IP: %s\n", inet_ntoa(packet->addr.sin_addr));
    fprintf(log_file, "Packet Length: %d\n", packet->len);
    fprintf(log_file, "Payload: %s\n\n", packet->payload);
    fclose(log_file);
}

void *packet_sniffer(void *arg) {
    int sock_raw = *(int *)arg;
    struct sockaddr_in addr;
    socklen_t addr_len = sizeof(addr);
    packet_info p_info;

    while (1) {
        p_info.len = recvfrom(sock_raw, p_info.payload, MAX_BUFFER, 0, (struct sockaddr *)&addr, &addr_len);
        if (p_info.len < 0) {
            perror("Failed to receive packet");
            continue;
        }

        p_info.addr = addr;
        log_packet(&p_info);

        if (ntohs(addr.sin_port) == PORT_TO_MONITOR) {
            printf("Blocked packet from IP: %s on port %d\n", inet_ntoa(addr.sin_addr), PORT_TO_MONITOR);
        }
    }

    return NULL;
}

int create_raw_socket() {
    int sock_raw = socket(AF_INET, SOCK_RAW, IPPROTO_TCP);
    if (sock_raw < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    int option = 1;
    if (setsockopt(sock_raw, IPPROTO_IP, IP_HDRINCL, &option, sizeof(option)) < 0) {
        perror("Failed to set socket options");
        close(sock_raw);
        exit(EXIT_FAILURE);
    }

    return sock_raw;
}

void initialize_firewall() {
    printf("Initializing Firewall...\n");
    int sock_raw = create_raw_socket();

    pthread_t sniffer_thread;
    if (pthread_create(&sniffer_thread, NULL, packet_sniffer, (void *)&sock_raw) != 0) {
        perror("Failed to create sniffer thread");
        close(sock_raw);
        exit(EXIT_FAILURE);
    }

    pthread_join(sniffer_thread, NULL);
}

int main() {
    initialize_firewall();

    return 0;
}

#include <stdio.h>
