#define MAX_LINE_LENGTH 1024

struct csv_reader {
    FILE *file;
    char *buffer;
    size_t buffer_size;
    size_t buffer_pos;
};

struct csv_reader *csv_reader_new(const char *filename) {
    struct csv_reader *reader = malloc(sizeof(struct csv_reader));
    if (reader == NULL) {
        return NULL;
    }
    reader->file = fopen(filename, "r");
    if (reader->file == NULL) {
        free(reader);
        return NULL;
    }
    reader->buffer = malloc(MAX_LINE_LENGTH);
    if (reader->buffer == NULL) {
        fclose(reader->file);
        free(reader);
        return NULL;
    }
    reader->buffer_size = MAX_LINE_LENGTH;
    reader->buffer_pos = 0;
    return reader;
}

void csv_reader_free(struct csv_reader *reader) {
    fclose(reader->file);
    free(reader->buffer);
    free(reader);
}

int csv_reader_next_line(struct csv_reader *reader, char ***fields, size_t *num_fields) {
    char *line = NULL;
    size_t line_length = 0;
    int in_quotes = 0;
    int field_count = 0;
    char **fields_array = NULL;

    while (fgets(reader->buffer, reader->buffer_size, reader->file)) {
        line = reader->buffer;
        line_length = strlen(line);
        if (line_length > 0 && line[line_length - 1] == '\n') {
            line[line_length - 1] = '\0';
            line_length--;
        }
        if (line_length > 0 && line[0] == '"') {
            in_quotes = 1;
        }
        for (size_t i = 0; i < line_length; i++) {
            char c = line[i];
            if (c == ',' && !in_quotes) {
                field_count++;
            } else if (c == '"') {
                in_quotes = !in_quotes;
            }
        }
        field_count++;
        fields_array = malloc(sizeof(char *) * field_count);
        if (fields_array == NULL) {
            return -1;
        }
        char *field_start = line;
        char *field_end = NULL;
        int field_index = 0;
        for (size_t i = 0; i < line_length; i++) {
            char c = line[i];
            if (c == ',' && !in_quotes) {
                field_end = &line[i];
                char *field = malloc(field_end - field_start + 1);
                if (field == NULL) {
                    free(fields_array);
                    return -1;
                }
                strncpy(field, field_start, field_end - field_start);
                field[field_end - field_start] = '\0';
                fields_array[field_index] = field;
                field_index++;
                field_start = &line[i + 1];
            } else if (c == '"') {
                in_quotes = !in_quotes;
            }
        }
        field_end = &line[line_length];
        char *field = malloc(field_end - field_start + 1);
        if (field == NULL) {
            free(fields_array);
            return -1;
        }
        strncpy(field, field_start, field_end - field_start);
        field[field_end - field_start] = '\0';
        fields_array[field_index] = field;
        *fields = fields_array;
        *num_fields = field_count;
        return 0;
    }
    return -1;
}

int main() {
    struct csv_reader *reader = csv_reader_new("data.csv");
    if (reader == NULL) {
        fprintf(stderr, "Error opening file\n");
        return EXIT_FAILURE;
    }
    char **fields;
    size_t num_fields;
    while (csv_reader_next_line(reader, &fields, &num_fields) == 0) {
        printf("Fields: ");
        for (size_t i = 0; i < num_fields; i++) {
            printf("%s, ", fields[i]);
        }
        printf("\n");
    }
    csv_reader_free(reader);
    return EXIT_SUCCESS;
}

