vector<T> tokenize(string s, const string &delim=" ")

{

    vector<T> ret_val;

    string::size_type i=0;

    string::size_type len = delim.length();

    if (delim != " ")

        while ((i=s.find(delim)) != string::npos)

            s.replace(i, len, " ");



    istringstream is(s);

    T val;



    while (is >> val)

        ret_val.push_back(val);

    return ret_val;

}

