// Defining heralds of the email kingdom
#define MAX_SUBJECT 256
#define MAX_BODY 1024
#define MAX_SENDER 256
#define MAX_RECEIVER 256
#define MAX_EMAILS 100

typedef struct {
    char sender[MAX_SENDER];
    char receiver[MAX_RECEIVER];
    char subject[MAX_SUBJECT];
    char body[MAX_BODY];
} Scroll;

// The kingdom of the Email Client
typedef struct {
    Scroll scrolls[MAX_EMAILS];
    int count;
} Kingdom;

void initialize_kingdom(Kingdom* kingdom) {
    kingdom->count = 0;
    printf("Welcome to the Kingdom of Email, brave scribe!\n");
}

void send_scroll(Kingdom* kingdom) {
    if (kingdom->count >= MAX_EMAILS) {
        printf("Alas! The scrolls of the kingdom are full; cannot send more.\n");
        return;
    }

    Scroll* new_scroll = &kingdom->scrolls[kingdom->count];

    printf("Enter the name of the sender (e.g., 'Sir Arthur'): ");
    fgets(new_scroll->sender, MAX_SENDER, stdin);
    strtok(new_scroll->sender, "\n"); // remove newline

    printf("Enter the name of the receiver (e.g., 'Lady Guinevere'): ");
    fgets(new_scroll->receiver, MAX_RECEIVER, stdin);
    strtok(new_scroll->receiver, "\n"); // remove newline

    printf("Enter the subject of the scroll: ");
    fgets(new_scroll->subject, MAX_SUBJECT, stdin);
    strtok(new_scroll->subject, "\n"); // remove newline

    printf("Compose the body of the scroll:\n");
    fgets(new_scroll->body, MAX_BODY, stdin);
    strtok(new_scroll->body, "\n"); // remove newline

    kingdom->count++;
    printf("The scroll has been dispatched forthwith to %s!\n", new_scroll->receiver);
}

void read_scrolls(Kingdom* kingdom) {
    if (kingdom->count == 0) {
        printf("There are no scrolls within the kingdom to read.\n");
        return;
    }

    for (int i = 0; i < kingdom->count; i++) {
        Scroll* scroll = &kingdom->scrolls[i];
        printf("\n--- Scroll %d ---\n", i + 1);
        printf("From: %s\n", scroll->sender);
        printf("To: %s\n", scroll->receiver);
        printf("Subject: %s\n", scroll->subject);
        printf("Body: %s\n", scroll->body);
    }
}

void castle_menu() {
    printf("\n--- Welcome to the Scribe’s Castle ---\n");
    printf("1. Send a scroll\n");
    printf("2. Read received scrolls\n");
    printf("3. Exit the kingdom\n");
    printf("Choose thine action: ");
}

int main() {
    Kingdom kingdom;
    initialize_kingdom(&kingdom);

    int choice;

    while (1) {
        castle_menu();
        scanf("%d", &choice);
        getchar(); // Clear the newline from the input buffer

        switch (choice) {
            case 1:
                send_scroll(&kingdom);
                break;

            case 2:
                read_scrolls(&kingdom);
                break;

            case 3:
                printf("Farewell, noble scribe! May your quill never run dry.\n");
                exit(0);

            default:
                printf("Thou hast made an unwise choice; pick again!\n");
        }
    }

    return 0;
}

