#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <termios.h>
#include <unistd.h>

// change value to 1 if DTR should be set to high
#define CONFIG_SET_DTR_HIGH 0

int main(int argc, const char *argv[])
{
   int fd;
   char key[255];
   char data[255];
   size_t bi;
   struct termios old_stdin_tconf;
   struct termios saved_options;
   struct termios options;
   struct pollfd fds;
   struct {
      speed_t     speed;
      const char* name;
   } baudrate[] = {
      { B9600, "9600" }, { B19200, "19200" }, { B38400, "38400" },
      { B57600, "57600" }, { B115200, "115200" }, { B230400, "230400" }
   };

   if (argc != 4 || strcmp(argv[3], "8N1")) {
USAGE:
      printf("Usage: %s /dev/ttyXXX <baudrate> 8N1\n", argv[0]);
      exit(1);
   }

   fd = open(argv[1], O_RDWR|O_NOCTTY|O_NONBLOCK|O_CLOEXEC);
   if (fd == -1) {
      perror("open");
      exit(1);
   }

   if (tcgetattr(0, &old_stdin_tconf)) {
      perror("tcgetattr");
      exit(1);
   }

   if (tcgetattr(fd, &saved_options)) {
      perror("tcgetattr");
      exit(1);
   }

   for (bi = 0; bi < sizeof(baudrate)/sizeof(baudrate[0]); ++bi) {
      if (strcmp(baudrate[bi].name, argv[2]) == 0) break;
   }

   if (bi == sizeof(baudrate)/sizeof(baudrate[0])) {
      errno = EINVAL;
      perror("Unsupported baudrate");
      printf("Supported baudrates:");
      for (bi = 0; bi < sizeof(baudrate)/sizeof(baudrate[0]); ++bi) {
         printf(" %s", baudrate[bi].name);
      }
      printf("\n");
      exit(1);
   }

   options = saved_options;
   options.c_cflag |= (CLOCAL|CREAD);
   options.c_lflag &= ~(ICANON | ECHO | ECHOE);
   options.c_iflag &= ~(IXON | IXOFF | IXANY); // no software flow control
   options.c_iflag &= ~(ICRNL);
   options.c_oflag &= ~(OPOST|OCRNL);
   cfsetispeed(&options, baudrate[bi].speed);
   cfsetospeed(&options, baudrate[bi].speed);

   if (0 == strcmp(argv[3], "8N1")) {
      options.c_cflag |= (CLOCAL|CREAD);
      options.c_cflag &= ~PARENB;
      options.c_cflag &= ~CSTOPB;
      options.c_cflag &= ~CSIZE;
      options.c_cflag |= CS8;
   } else {
      errno = EINVAL;
      perror("Unsupported format");
      goto USAGE;
   }

   if (tcsetattr(fd, TCSANOW, &options)) {
      perror("tcsetattr");
      exit(1);
   }

   // switch stdin/stdout (terminal/keyboard) to single character mode
   {
      struct termios tconf = old_stdin_tconf;
      int fl = fcntl(0, F_GETFL);
      fcntl(0, F_SETFL, (fl != -1 ? fl:0)|O_NONBLOCK);
      tconf.c_iflag &= (unsigned) ~(IXON|ICRNL|INLCR);
      tconf.c_oflag &= (unsigned) ~(OCRNL);
      tconf.c_oflag |= (unsigned)  (ONLCR); // map \n to \r\n on output
      tconf.c_lflag &= (unsigned) ~(ICANON/*char mode*/ | ECHO/*echo off*/ | ISIG);
      tconf.c_cc[VMIN]  = 1;
      tconf.c_cc[VTIME] = 0;
      tcsetattr(0, TCSANOW, &tconf);
   }

   if (CONFIG_SET_DTR_HIGH) {
      // set DTR high
      int flag = TIOCM_DTR;
      ioctl(fd, TIOCMBIS, &flag);
   }

   printf("Press <CTRL>-D to end program\n");
   fds.fd = fd;
   fds.events = POLLIN;
   for (;;) {
      if (1 == poll(&fds, 1, 100)) {
         int bytes = read(fd, data, sizeof(data));
         if (bytes == -1) {
            if (errno == EAGAIN) continue;
            perror("read");
            goto DONE;
         }
         write(1, data, bytes);
      }
      int nrkeys = read(0, key, sizeof(key));
      if (nrkeys > 0) {
         if (key[nrkeys-1] == old_stdin_tconf.c_cc[VEOF]) {
            write(fd, key, nrkeys-1);
            break;
         } else {
            write(fd, key, nrkeys);
         }
      }
   }

DONE:
   tcsetattr(0, TCSANOW, &old_stdin_tconf);
   tcsetattr(fd, TCSANOW, &saved_options);
   close(fd);

   return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

struct node
{
    int x, y, f, g, h;
    bool traversable;
    struct node *parent;
};

typedef struct node node_t;

int **create_map(int rows, int cols)
{
    int **map = (int **)malloc(rows * sizeof(int *));
    for (int i = 0; i < rows; i++)
        map[i] = (int *)malloc(cols * sizeof(int));

    // initialize map with random values
    for (int i = 0; i < rows; i++)
        for (int j = 0; j < cols; j++)
            map[i][j] = rand() % 2;

    return map;
}

void free_map(int **map, int rows)
{
    for (int i = 0; i < rows; i++)
        free(map[i]);
    free(map);
}

// euclidean distance heuristic
int heuristic(node_t *node, node_t *goal)
{
    int x_dist = abs(node->x - goal->x);
    int y_dist = abs(node->y - goal->y);
    return x_dist + y_dist;
}

node_t *create_node(int x, int y, bool traversable)
{
    node_t *node = (node_t *)malloc(sizeof(node_t));
    node->x = x;
    node->y = y;
    node->f = 0;
    node->g = 0;
    node->h = 0;
    node->traversable = traversable;
    node->parent = NULL;
    return node;
}

void free_node(node_t *node)
{
    free(node);
}

node_t *get_lowest_f_node(node_t **open_set, int open_set_size)
{
    int lowest_f = open_set[0]->f;
    int lowest_f_index = 0;

    for (int i = 1; i < open_set_size; i++)
    {
        if (open_set[i]->f < lowest_f)
        {
            lowest_f = open_set[i]->f;
            lowest_f_index = i;
        }
    }

    return open_set[lowest_f_index];
}

bool is_in_closed_set(node_t *node, node_t **closed_set, int closed_set_size)
{
    for (int i = 0; i < closed_set_size; i++)
    {
        if (node->x == closed_set[i]->x && node->y == closed_set[i]->y)
        {
            return true;
        }
    }

    return false;
}

bool is_in_open_set(node_t *node, node_t **open_set, int open_set_size)
{
    for (int i = 0; i < open_set_size; i++)
    {
        if (node->x == open_set[i]->x && node->y == open_set[i]->y)
        {
            return true;
        }
    }

    return false;
}

node_t **get_neighbours(node_t *node, int **map, int rows, int cols)
{
    static node_t *neighbours[8];

    int index = 0;

    for (int i = -1; i <= 1; i++)
    {
        for (int j = -1; j <= 1; j++)
        {
            if (i == 0 && j == 0)
                continue;

            int x = node->x + i;
            int y = node->y + j;

            if (x < 0 || x >= rows || y < 0 || y >= cols)
                continue;

            if (!map[x][y])
                continue;

            neighbours[index++] = create_node(x, y, true);
        }
    }

    return neighbours;
}

void reconstruct_path(node_t *current)
{
    node_t *p = current;
    while (p->parent)
    {
        printf("(%d,%d) -> ", p->x, p->y);
        p = p->parent;
    }
    printf("(%d,%d)\n", p->x, p->y);
}

node_t *a_star_search(int **map, int rows, int cols, node_t *start, node_t *goal)
{
    node_t *open_set[rows * cols];
    int open_set_size = 0;

    node_t *closed_set[rows * cols];
    int closed_set_size = 0;

    open_set[open_set_size++] = start;

    while (open_set_size > 0)
    {
        node_t *current = get_lowest_f_node(open_set, open_set_size);
        if (current->x == goal->x && current->y == goal->y)
        {
            return current;
        }

        open_set_size--;
        for (int i = 0; i < open_set_size; i++)
        {
            if (open_set[i] == current)
            {
                open_set[i] = open_set[open_set_size];
                break;
            }
        }

        closed_set[closed_set_size++] = current;

        node_t **neighbours = get_neighbours(current, map, rows, cols);
        int neighbours_size = sizeof(neighbours) / sizeof(node_t *);

        for (int i = 0; i < neighbours_size; i++)
        {
            node_t *neighbour = neighbours[i];

            if (is_in_closed_set(neighbour, closed_set, closed_set_size))
            {
                free_node(neighbour);
                continue;
            }

            int tentative_g_score = current->g + 1;

            if (!is_in_open_set(neighbour, open_set, open_set_size))
            {
                open_set[open_set_size++] = neighbour;
                neighbour->h = heuristic(neighbour, goal);
            }
            else if (tentative_g_score >= neighbour->g)
            {
                free_node(neighbour);
                continue;
            }

            neighbour->parent = current;
            neighbour->g = tentative_g_score;
            neighbour->f = neighbour->g + neighbour->h;
        }
    }

    return NULL;
}

int main()
{
    int rows = 10;
    int cols = 10;

    int **map = create_map(rows, cols);

    node_t *start = create_node(0, 0, true);
    node_t *goal = create_node(rows - 1, cols - 1, true);

    node_t *path = a_star_search(map, rows, cols, start, goal);

    if (path == NULL)
    {
        printf("No path found.\n");
    }
    else
    {
        printf("Path found:\n");
        reconstruct_path(path);
    }

    free_map(map, rows);
    free_node(start);
    free_node(goal);
    free_node(path);

    return 0;
}

