// Function to beautify HTML code
void html_beautifier(char* input) {
  // Step 1: Remove unnecessary whitespace
  char* temp = input;
  while (*temp != '\0') {
    if (*temp == ' ' || *temp == '\t') {
      temp[0] = '\0';
    }
    temp++;
  }

  // Step 2: Indent code
  int indent = 0;
  for (int i = 0; i < strlen(input); i++) {
    if (input[i] == '\n') {
      indent = 0;
    } else if (input[i] == '{' || input[i] == '(' || input[i] == '[') {
      indent++;
    } else if (input[i] == '}' || input[i] == ')' || input[i] == ']') {
      indent--;
    }
  }

  // Step 3: Add spaces to maintain indentation
  for (int i = 0; i < strlen(input); i++) {
    if (input[i] == '\n') {
      continue;
    }
    if (indent > 0) {
      input[i] = ' ';
      indent--;
    } else if (indent < 0) {
      input[i] = '\n';
      indent = 0;
    }
  }

  // Step 4: Remove empty lines
  char* line = input;
  while (*line != '\0') {
    if (*line == '\n' && line[1] == '\0') {
      line[0] = '\0';
    } else {
      line++;
    }
  }

  // Step 5: Print the beautified code
  print_message("Beautified HTML Code:\n");
  printf("%s\n", input);
}

int main() {
  char input[] = "Hello World!<p>This is a paragraph.</p>";
  html_beautifier(input);
  return 0;
}

