#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <stdio.h>

#define BUFFER_SIZE 1024

int main(int argc, char *argv[]) {
    int sock1, sock2;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];

    // Create the first socket
    sock1 = socket(AF_INET, SOCK_STREAM, 0);
    if (sock1 < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set up the server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(8080);

    // Bind the first socket to the address and port
    if (bind(sock1, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("binding failed");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(sock1, 3) < 0) {
        perror("listening failed");
        exit(EXIT_FAILURE);
    }

    // Create the second socket
    sock2 = socket(AF_INET, SOCK_STREAM, 0);
    if (sock2 < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set up the client address
    client_addr.sin_family = AF_INET;
    client_addr.sin_addr.s_addr = INADDR_ANY;
    client_addr.sin_port = htons(8081);

    // Connect the second socket to the server
    if (connect(sock2, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connecting failed");
        exit(EXIT_FAILURE);
    }

    // Start the signal processing loop
    while (1) {
        // Receive data from the client
        recv(sock2, buffer, BUFFER_SIZE, 0);

        // Process the received data
        // (in this example, we'll just print it to the console)
        printf("Received data: %s\n", buffer);

        // Send the processed data back to the client
        send(sock1, buffer, BUFFER_SIZE, 0);
    }

    // Close the sockets
    close(sock1);
    close(sock2);

    return 0;
}

#include <stdio.h>
#include <string.h>

// function to check if a password is strong
int is_password_strong(char password[]) {
    // length of the password must be at least 8 characters
    int length = strlen(password);
    if (length < 8) {
        return 0;
    }

    // the password must contain a lowercase letter, an uppercase letter and a digit
    int has_lowercase = 0, has_uppercase = 0, has_digit = 0;
    for (int i = 0; i < length; i++) {
        char c = password[i];
        if (c >= 'a' && c <= 'z') {
            has_lowercase = 1;
        } else if (c >= 'A' && c <= 'Z') {
            has_uppercase = 1;
        } else if (c >= '0' && c <= '9') {
            has_digit = 1;
        }
    }
    if (!(has_lowercase && has_uppercase && has_digit)) {
        return 0;
    }

    // the password must not contain common words or patterns
    char common_patterns[5][10] = {"123", "password", "qwerty", "admin", "letmein"};
    for (int i = 0; i < 5; i++) {
        if (strstr(password, common_patterns[i]) != NULL) {
            return 0;
        }
    }

    // if the password passes all the tests, it is considered strong
    return 1;
}

int main() {
    char password[100];
    printf("Enter a password: ");
    scanf("%s", password);
    if (is_password_strong(password)) {
        printf("The password is strong!\n");
    } else {
        printf("The password is weak.\n");
    }
    return 0;
}

