#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define KEY_SIZE 16 // 128-bit key
#define BLOCK_SIZE 16 // 128-bit block

void generate_key(char *key) {
    for (int i = 0; i < KEY_SIZE; i++) {
        key[i] = rand() % 256;
    }
}

void encrypt(char *data, char *key) {
    for (int i = 0; i < strlen(data); i++) {
        data[i] ^= key[i % KEY_SIZE];
    }
}

void decrypt(char *data, char *key) {
    encrypt(data, key);
}

int main() {
    srand(time(NULL));

    char key[KEY_SIZE];
    generate_key(key);

    char data[BLOCK_SIZE];
    for (int i = 0; i < BLOCK_SIZE; i++) {
        data[i] = rand() % 256;
    }

    printf("Plaintext: ");
    for (int i = 0; i < BLOCK_SIZE; i++) {
        printf("%02X ", data[i]);
    }
    printf("\n");

    encrypt(data, key);

    printf("Ciphertext: ");
    for (int i = 0; i < BLOCK_SIZE; i++) {
        printf("%02X ", data[i]);
    }
    printf("\n");

    decrypt(data, key);

    printf("Decrypted text: ");
    for (int i = 0; i < BLOCK_SIZE; i++) {
        printf("%c", data[i]);
    }
    printf("\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <sys/time.h>

#define MAX_URL_LEN 512

struct url_info {
    char url[MAX_URL_LEN];
    int interval;
    time_t last_check;
};

static size_t WriteCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((char*)userp)[size*nmemb] = '\0';
    return size*nmemb;
}

int main(int argc, char *argv[]) {
    CURL *curl;
    FILE *fp;
    char buffer[1024];
    struct url_info urls[10];
    int num_urls = 0;
    time_t current_time;

    if (argc < 3) {
        printf("Usage: %s <config_file> <log_file>\n", argv[0]);
        return 1;
    }

    fp = fopen(argv[1], "r");
    if (fp == NULL) {
        printf("Error opening config file.\n");
        return 1;
    }

    while (fscanf(fp, "%s %d\n", urls[num_urls].url, &urls[num_urls].interval)!= EOF) {
        num_urls++;
        if (num_urls >= 10) {
            break;
        }
    }

    fclose(fp);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (curl) {
        while (1) {
            current_time = time(NULL);

            for (int i = 0; i < num_urls; i++) {
                if (difftime(current_time, urls[i].last_check) >= urls[i].interval) {
                    sprintf(buffer, "Checking %s...\n", urls[i].url);
                    fwrite(buffer, strlen(buffer), 1, stdout);

                    curl_easy_setopt(curl, CURLOPT_URL, urls[i].url);
                    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
                    curl_easy_setopt(curl, CURLOPT_WRITEDATA, buffer);

                    curl_easy_perform(curl);

                    if (buffer[0] == '2') {
                        printf("Website is up.\n");
                    } else {
                        printf("Website is down.\n");
                    }

                    urls[i].last_check = current_time;
                }
            }

            sleep(5);
        }

        curl_easy_cleanup(curl);
        curl_global_cleanup();
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#define BOARD_SIZE 9
#define BLOCK_SIZE 3

typedef struct {
    int board[BOARD_SIZE][BOARD_SIZE];
    int p_x, p_y;
} SudokuBoard;

bool is_valid(int board[BOARD_SIZE][BOARD_SIZE], int num, int row, int col) {
    for (int i = 0; i < BOARD_SIZE; i++) {
        if (board[row][i] == num) return false;
        if (board[i][col] == num) return false;
    }

    int box_x = col / BLOCK_SIZE;
    int box_y = row / BLOCK_SIZE;

    for (int i = box_y * BLOCK_SIZE; i < box_y * BLOCK_SIZE + BLOCK_SIZE; i++) {
        for (int j = box_x * BLOCK_SIZE; j < box_x * BLOCK_SIZE + BLOCK_SIZE; j++) {
            if (board[i][j] == num) return false;
        }
    }

    return true;
}

bool solve_sudoku(SudokuBoard *board, int num, int row, int col) {
    if (num > BOARD_SIZE * BOARD_SIZE) return true;

    int back_num = board->board[row][col];
    if (back_num != 0 && back_num != num) return false;

    if (back_num == 0) {
        board->board[row][col] = num;

        for (int i = 0; i < BOARD_SIZE; i++) {
            if (solve_sudoku(board, num + 1, row, i)) return true;
            if (solve_sudoku(board, num + 1, i, col)) return true;
        }

        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board->board[i][j] == 0 && is_valid(board->board, num, i, j)) {
                    board->p_x = i;
                    board->p_y = j;
                    break;
                }
            }
            if (board->p_x >= 0 && board->p_y >= 0) break;
        }

        board->board[row][col] = back_num;
    }

    return false;
}

void print_sudoku(SudokuBoard *board) {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (j > 0) printf(" | ");
            printf("%d ", board->board[i][j]);
        }
        if (i < BOARD_SIZE - 1) printf("\n---+---+---\n");
    }
}

int main() {
    SudokuBoard board;
    int num = 0;

    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            board.board[i][j] = rand() % 10 + 1;
            if (board.board[i][j] == 0) {
                num++;
                board.p_x = i;
                board.p_y = j;
            }
        }
    }

    printf("Initial board:\n");
    print_sudoku(&board);

    if (solve_sudoku(&board, num + 1, 0, 0)) {
        printf("\nSolved board:\n");
        print_sudoku(&board);
    } else {
        printf("Error: could not solve the board.\n");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE_LENGTH 1024
#define MAX_NEST_LEVEL 100

typedef struct {
    int indent;
    char line[MAX_LINE_LENGTH];
} IndentedLine;

// Function declarations
void beautify_html(const char *file_path);
void process_line(const char *line, IndentedLine *indented_lines, int *indent_level, int *line_count);
void print_beautified_html(IndentedLine *indented_lines, int line_count);
void trim_whitespace(char *str);

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <html_file_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *file_path = argv[1];
    beautify_html(file_path);

    return EXIT_SUCCESS;
}

void beautify_html(const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        fprintf(stderr, "Error: Cannot open file %s\n", file_path);
        exit(EXIT_FAILURE);
    }

    IndentedLine indented_lines[MAX_LINE_LENGTH];
    int indent_level = 0;
    int line_count = 0;
    char line[MAX_LINE_LENGTH];

    while (fgets(line, sizeof(line), file)) {
        process_line(line, indented_lines, &indent_level, &line_count);
    }
    fclose(file);

    print_beautified_html(indented_lines, line_count);
}

void process_line(const char *line, IndentedLine *indented_lines, int *indent_level, int *line_count) {
    char trimmed_line[MAX_LINE_LENGTH];
    strcpy(trimmed_line, line);
    trim_whitespace(trimmed_line);

    // Ignore empty lines
    if (strlen(trimmed_line) == 0) return;

    // Detect opening tags
    if (trimmed_line[0] == '<' && trimmed_line[1] != '/') {
        indented_lines[*line_count].indent = *indent_level;
        strcpy(indented_lines[*line_count].line, trimmed_line);
        (*line_count)++;
        (*indent_level)++;
    } 
    // Detect closing tags
    else if (trimmed_line[0] == '<' && trimmed_line[1] == '/') {
        if (*indent_level > 0) (*indent_level)--;
        indented_lines[*line_count].indent = *indent_level;
        strcpy(indented_lines[*line_count].line, trimmed_line);
        (*line_count)++;
    } 
    // Non-tag lines
    else {
        indented_lines[*line_count].indent = *indent_level;
        strcpy(indented_lines[*line_count].line, trimmed_line);
        (*line_count)++;
    }
}

void print_beautified_html(IndentedLine *indented_lines, int line_count) {
    for (int i = 0; i < line_count; i++) {
        for (int j = 0; j < indented_lines[i].indent; j++) {
            putchar('\t'); // Indent using tab characters
        }
        printf("%s\n", indented_lines[i].line);
    }
}

void trim_whitespace(char *str) {
    // Trim leading whitespace
    while (isspace((unsigned char)*str)) str++;

    // Trim trailing whitespace
    char *end = str + strlen(str) - 1;
    while (end > str && isspace((unsigned char)*end)) end--;

    // Null terminate the trimmed string
    *(end + 1) = '\0';
}

