double loopSimple (double x,int n) // simple exponential loop
{
	double result = 1;
	for (int i = 0; i < n; i++)
	{
		result = x * result;
	}
	return result;
}

double loopRecursion (double x,int n) // loop using recursion
{
	if ( n == 0 )
		return 1;
	else
		return x * loopRecursion (x, n - 1); // call of function in function is recursive

}

double loopRecursLog (double x,int n) // more efficient calculation because the possibility is cut in half each time
{
	if ( n == 0 )                                // if n is zero, just return 1 (terminating case)
		return 1;
	else if ( n == 1 )                           // if n is 1, send back x. //why?
		return x;
	else if (n % 2 == 0)                         // if n mod 2 = 0 (in other words its even)
		return loopRecursLog (x*x, n/2);         // return half
	else 
		return loopRecursLog (x*x, n/2) * x;     // else return the other half
}

void loopExponential (int n) // long long loop to calculate exponential, can take a long time.
{
	double power = 1, result = 0;
	double j = 1, k = 1;
	for(j=1; j <= n; j++)
	{
		power = power * 2;
		for(k=1; k<= power; k++)
			cout << k << endl;
	}
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
#include <pthread.h>

#define MAX_EXPRESSION_LENGTH 100
#define MAX_PLAYERS 5

typedef struct {
    int player_id;
    char expression[MAX_EXPRESSION_LENGTH];
} Player;

Player players[MAX_PLAYERS];

void *calculate(void *arg) {
    Player *p = (Player *)arg;
    double result;

    // Convert expression into a valid C expression
    // Note: Here we strictly evaluate basic calculations for simplicity
    // Ideally, you should use a parser for complex expressions
    if (sscanf(p->expression, "%lf", &result) == 0) {
        printf("Player %d: Could not parse expression %s\n", p->player_id, p->expression);
        pthread_exit(NULL);
    }

    // Example of hardcoded operations based on input, can be modified for more operations
    if (strstr(p->expression, "sqrt") != NULL) {
        result = sqrt(result);
    } else if (strstr(p->expression, "pow") != NULL) {
        double exponent;
        sscanf(strchr(p->expression, ',')+1, "%lf", &exponent);
        result = pow(result, exponent);
    } else if (strstr(p->expression, "sin") != NULL) {
        result = sin(result);
    } else if (strstr(p->expression, "cos") != NULL) {
        result = cos(result);
    } else if (strstr(p->expression, "tan") != NULL) {
        result = tan(result);
    } else {
        printf("Player %d: Invalid expression %s\n", p->player_id, p->expression);
        pthread_exit(NULL);
    }

    printf("Player %d: Result of '%s' is %.2f\n", p->player_id, p->expression, result);
    pthread_exit(NULL);
}

int main() {
    pthread_t threads[MAX_PLAYERS];
    int i, num_players;

    printf("Welcome to the Multiplayer Scientific Calculator!\n");
    printf("Enter number of players (max %d): ", MAX_PLAYERS);
    scanf("%d", &num_players);

    if (num_players < 1 || num_players > MAX_PLAYERS) {
        printf("Invalid number of players! Exiting.\n");
        return 1;
    }

    // Gather input for each player
    for (i = 0; i < num_players; i++) {
        players[i].player_id = i + 1;
        printf("Player %d, enter your expression (e.g., sqrt(9), pow(2,3), sin(30)): ", players[i].player_id);
        scanf(" %[^\n]", players[i].expression);
    }

    // Create threads for each player to calculate their expression
    for (i = 0; i < num_players; i++) {
        if (pthread_create(&threads[i], NULL, calculate, (void *)&players[i]) != 0) {
            printf("Error creating thread for player %d\n", players[i].player_id);
            return 1;
        }
    }

    // Wait for all threads to finish
    for (i = 0; i < num_players; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("All calculations are done!\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to calculate subnet, broadcast, and usable IP addresses
void calculateSubnet(char *ip, char *mask) {
    char *subnet = (char*)malloc(sizeof(char) * 8);
    char *broadcast = (char*)malloc(sizeof(char) * 8);
    int usableIPs = 0;

    // Convert IP and mask to binary
    int i;
    int ipBinary[32] = {0};
    int maskBinary[32] = {0};
    int maskLength = strlen(mask);
    for (i = 0; i < maskLength; i++) {
        maskBinary[i] = mask[i] - '0';
    }
    for (i = 0; i < strlen(ip); i++) {
        ipBinary[i] = ip[i] - '0';
    }

    // Calculate subnet and broadcast
    for (i = 0; i < 32; i++) {
        if (maskBinary[i] == 0) {
            subnet[i] = '1';
            broadcast[i] = '1';
            continue;
        }
        if (ipBinary[i] == 1 && maskBinary[i] == 1) {
            subnet[i] = '0';
            broadcast[i] = '1';
        } else if (ipBinary[i] == 0 && maskBinary[i] == 0) {
            subnet[i] = '0';
            broadcast[i] = '0';
        } else {
            subnet[i] = '1';
            broadcast[i] = '0';
        }
        if (subnet[i] == '1' || broadcast[i] == '1') {
            usableIPs++;
        }
    }

    // Print results
    printf("Subnet: %s\n", subnet);
    printf("Broadcast: %s\n", broadcast);
    printf("Number of usable IP addresses: %d\n", usableIPs);
}

int main() {
    char ip[16] = "192.168.1.0";
    char mask[16] = "255.255.255.0";
    calculateSubnet(ip, mask);
    return 0;
}

#include <stdio.h>
