#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_BIDDERS 100
#define MAX_AUCTIONS 100
#define ITEM_NAME_LENGTH 50

// Struct for Bidder
typedef struct {
    int id;
    char name[ITEM_NAME_LENGTH];
    float max_bid;
} Bidder;

// Struct for Auction Item
typedef struct {
    int id;
    char item_name[ITEM_NAME_LENGTH];
    float starting_price;
    float highest_bid;
    int highest_bidder_id;
    time_t end_time;
} AuctionItem;

// Globals
Bidder bidders[MAX_BIDDERS];
AuctionItem auctions[MAX_AUCTIONS];
int num_bidders = 0;
int num_auctions = 0;

// Function Prototypes
void display_auction_items();
void create_bidder(const char *name, float max_bid);
void create_auction_item(const char *item_name, float starting_price, int duration);
void place_bid(int auction_id, int bidder_id, float bid_amount);
void display_winner(int auction_id);
void auction_timer(int auction_id);

int main() {
    create_bidder("Alice", 1000);
    create_bidder("Bob", 500);
    create_bidder("Charlie", 800);

    create_auction_item("Vintage Vase", 100, 30);
    create_auction_item("Antique Clock", 200, 30);

    // Start the auction process
    display_auction_items();

    // Alice bids on the Vintage Vase
    place_bid(0, 0, 120);
    // Bob bids on the Vintage Vase
    place_bid(0, 1, 130);
    // Charlie bids on the Antique Clock
    place_bid(1, 2, 250);

    // Display bidders of finished auctions
    auction_timer(0);
    auction_timer(1);

    return 0;
}

// Function to create a new bidder
void create_bidder(const char *name, float max_bid) {
    if (num_bidders < MAX_BIDDERS) {
        bidders[num_bidders].id = num_bidders;
        strncpy(bidders[num_bidders].name, name, ITEM_NAME_LENGTH);
        bidders[num_bidders].max_bid = max_bid;
        num_bidders++;
    } else {
        printf("Maximum number of bidders reached.\n");
    }
}

// Function to create a new auction item
void create_auction_item(const char *item_name, float starting_price, int duration) {
    if (num_auctions < MAX_AUCTIONS) {
        auctions[num_auctions].id = num_auctions;
        strncpy(auctions[num_auctions].item_name, item_name, ITEM_NAME_LENGTH);
        auctions[num_auctions].starting_price = starting_price;
        auctions[num_auctions].highest_bid = starting_price;
        auctions[num_auctions].highest_bidder_id = -1; // No bids yet
        auctions[num_auctions].end_time = time(NULL) + duration; // Setting end time
        num_auctions++;
    } else {
        printf("Maximum number of auctions reached.\n");
    }
}

// Function to display available auction items
void display_auction_items() {
    printf("Available Auction Items:\n");
    for (int i = 0; i < num_auctions; i++) {
        printf("ID: %d | Item: %s | Starting Price: %.2f | Current Highest Bid: %.2f\n",
               auctions[i].id,
               auctions[i].item_name,
               auctions[i].starting_price,
               auctions[i].highest_bid);
    }
}

// Function to place a bid on an auction item
void place_bid(int auction_id, int bidder_id, float bid_amount) {
    if (auction_id < num_auctions && bidder_id < num_bidders) {
        AuctionItem *auction = &auctions[auction_id];

        if (time(NULL) < auction->end_time) {
            if (bid_amount > auction->highest_bid && bid_amount <= bidders[bidder_id].max_bid) {
                auction->highest_bid = bid_amount;
                auction->highest_bidder_id = bidder_id;
                printf("%s placed a bid of %.2f on %s.\n", 
                        bidders[bidder_id].name, 
                        bid_amount, 
                        auction->item_name);
            } else {
                printf("Bid rejected: Amount is not higher than the current bid or over your limit.\n");
            }
        } else {
            printf("The auction has ended.\n");
        }
    } else {
        printf("Invalid auction or bidder ID.\n");
    }
}

// Function to handle auction timer and display winners
void auction_timer(int auction_id) {
    if (auction_id < num_auctions) {
        AuctionItem *auction = &auctions[auction_id];

        // Wait for the auction duration to conclude (simulated with sleep)
        while (time(NULL) < auction->end_time) {
            // Simulating auction countdown
            sleep(1);
        }
        display_winner(auction_id);
    } else {
        printf("Invalid auction ID.\n");
    }
}

// Function to display the winner of an auction
void display_winner(int auction_id) {
    if (auction_id < num_auctions) {
        AuctionItem *auction = &auctions[auction_id];
        if (auction->highest_bidder_id >= 0) {
            printf("Auction for %s won by %s with a bid of %.2f.\n",
                   auction->item_name,
                   bidders[auction->highest_bidder_id].name,
                   auction->highest_bid);
        } else {
            printf("No bids were placed for %s.\n", auction->item_name);
        }
    } else {
        printf("Invalid auction ID.\n");
    }
}

#include <pcap/pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

// The main function is the entry point of the program.
int main() {
  // Define the network interface to capture packets from.
  char *device = "wlan0";
  // Define the filter expression to capture only TCP packets.
  char *filter = "tcp";
  // Define the number of packets to capture.
  int num_packets = 10;

  // Open the network interface for packet capture.
  pcap_t *handle = pcap_open_live(device, BUFSIZ, 1, 1000, NULL);
  if (handle == NULL) {
    fprintf(stderr, "Unable to open the network interface for packet capture.\n");
    return -1;
  }

  // Compile the filter expression.
  struct bpf_program fp;
  if (pcap_compile(handle, &fp, filter, 0, PCAP_NETMASK_UNKNOWN) == -1) {
    fprintf(stderr, "Unable to compile the filter expression.\n");
    return -1;
  }

  // Set the filter on the network interface.
  if (pcap_setfilter(handle, &fp) == -1) {
    fprintf(stderr, "Unable to set the filter on the network interface.\n");
    return -1;
  }

  // Create a packet buffer to store the captured packets.
  u_char *buffer = (u_char *)malloc(BUFSIZ);
  if (buffer == NULL) {
    fprintf(stderr, "Unable to allocate memory for the packet buffer.\n");
    return -1;
  }

  // Capture packets until the specified number of packets is reached.
  int count = 0;
  while (count < num_packets) {
    // Wait for a packet to arrive.
    struct pcap_pkthdr *header;
    const u_char *data;
    int res = pcap_next_ex(handle, &header, &data);
    if (res == -1) {
      fprintf(stderr, "Unable to capture a packet.\n");
      return -1;
    } else if (res == 0) {
      continue;
    }

    // Print the packet header.
    printf("Packet number: %d\n", count + 1);
    printf("Packet length: %d bytes\n", header->len);
    printf("Capture time: %s\n", ctime((const time_t *)&header->ts.tv_sec));

    // Print the packet data.
    for (int i = 0; i < header->len; i++) {
      printf("%02x ", data[i]);
      if ((i + 1) % 16 == 0) {
        printf("\n");
      }
    }

    printf("\n");

    count++;
  }

  // Free the packet buffer.
  free(buffer);

  // Close the network interface.
  pcap_close(handle);

  return 0;
}

