#define PHONE_BOOK_SIZE 100
#define PHONE_NUMBER_LENGTH 10

struct phone_book {
    char name[50];
    char phone_number[PHONE_NUMBER_LENGTH];
};

struct phone_book g_phone_book[PHONE_BOOK_SIZE];
int g_num_entries = 0;

void add_entry(char *name, char *phone_number) {
    if (g_num_entries >= PHONE_BOOK_SIZE) {
        printf("Surprise! The phone book is full! :O\n");
        return;
    }

    strcpy(g_phone_book[g_num_entries].name, name);
    strcpy(g_phone_book[g_num_entries].phone_number, phone_number);
    g_num_entries++;

    printf("Entry added successfully! :D\n");
}

void search_entry(char *name) {
    int i;
    for (i = 0; i < g_num_entries; i++) {
        if (strcmp(g_phone_book[i].name, name) == 0) {
            printf("Found! %s's phone number is %s\n", name, g_phone_book[i].phone_number);
            return;
        }
    }

    printf("Oops! %s not found in the phone book :(\n", name);
}

int main() {
    char name[50];
    char phone_number[PHONE_NUMBER_LENGTH];

    srand(time(NULL));

    for (int i = 0; i < 10; i++) {
        printf("Add a new entry: ");
        fgets(name, 50, stdin);
        printf("Add a new phone number: ");
        fgets(phone_number, PHONE_NUMBER_LENGTH, stdin);
        add_entry(name, phone_number);
    }

    for (int i = 0; i < 10; i++) {
        printf("Search for %s: ", name[i]);
        search_entry(name[i]);
    }

    return 0;
}

/*
 * Building a FTP Client in C
 *
 * This is a simple example program that demonstrates how to use the C standard library
 * functions to build a FTP client.
 *
 * This program connects to a FTP server using the FTP protocol and retrieves a file.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define FTP_PORT 21
#define FTP_USER "user"
#define FTP_PASS "password"
#define FTP_FILE "example.txt"

int main() {
    int sock;
    struct sockaddr_in server_addr;
    char buf[1024];
    FILE *fp;

    // Create a socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket() failed");
        return 1;
    }

    // Set up the server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(FTP_PORT);
    server_addr.sin_addr.s_addr = inet_addr("127.0.0.1");

    // Connect to the server
    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect() failed");
        return 1;
    }

    // Login to the server
    fprintf(sock, "USER %s\r\n", FTP_USER);
    fprintf(sock, "PASS %s\r\n", FTP_PASS);

    // Get the file
    fprintf(sock, "RETR %s\r\n", FTP_FILE);

    // Open the file for writing
    fp = fopen("example.txt", "w");
    if (fp == NULL) {
        perror("fopen() failed");
        return 1;
    }

    // Read the file from the server and write it to the file
    while (1) {
        int n = read(sock, buf, sizeof(buf));
        if (n < 0) {
            perror("read() failed");
            break;
        } else if (n == 0) {
            break;
        }
        fwrite(buf, 1, n, fp);
    }

    // Close the file and socket
    fclose(fp);
    close(sock);

    return 0;
}

