/*
 * RomeoAndJulietTaskScheduler.c
 *
 * This program implements a unique C task scheduler in a Romeo and Juliet style.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TASKS 10

typedef struct task {
    char name[32];
    int priority;
    int duration;
    time_t start_time;
    time_t end_time;
} task_t;

void print_task(task_t *task) {
    printf("Task: %s\n", task->name);
    printf("Priority: %d\n", task->priority);
    printf("Duration: %d\n", task->duration);
    printf("Start time: %s\n", ctime(&task->start_time));
    printf("End time: %s\n", ctime(&task->end_time));
}

int compare_tasks(const void *a, const void *b) {
    task_t *task1 = (task_t *)a;
    task_t *task2 = (task_t *)b;

    if (task1->priority > task2->priority) {
        return -1;
    } else if (task1->priority < task2->priority) {
        return 1;
    } else {
        return 0;
    }
}

int main(void) {
    task_t tasks[MAX_TASKS];
    int ntasks = 0;

    // Initialize tasks
    strcpy(tasks[0].name, "Task 1");
    tasks[0].priority = 1;
    tasks[0].duration = 10;
    tasks[0].start_time = time(NULL);
    tasks[0].end_time = tasks[0].start_time + tasks[0].duration;

    strcpy(tasks[1].name, "Task 2");
    tasks[1].priority = 2;
    tasks[1].duration = 5;
    tasks[1].start_time = tasks[0].end_time;
    tasks[1].end_time = tasks[1].start_time + tasks[1].duration;

    strcpy(tasks[2].name, "Task 3");
    tasks[2].priority = 3;
    tasks[2].duration = 8;
    tasks[2].start_time = tasks[1].end_time;
    tasks[2].end_time = tasks[2].start_time + tasks[2].duration;

    // Sort tasks by priority
    qsort(tasks, ntasks, sizeof(task_t), compare_tasks);

    // Print tasks
    for (int i = 0; i < ntasks; i++) {
        print_task(&tasks[i]);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[50];
    int age;
    float love_level;
} lover_t;

typedef struct index_node {
    char key[20];
    int leaf;
    int next;
} index_node_t;

typedef struct b_tree {
    int order;
    index_node_t *nodes;
    int size;
    lover_t *records;
} b_tree_t;

void create_tree(b_tree_t *tree, int order) {
    tree->order = order;
    tree->nodes = (index_node_t *)calloc(order, sizeof(index_node_t));
    tree->records = (lover_t *)calloc(order * 2, sizeof(lover_t));
    tree->size = 0;
}

int is_leaf(b_tree_t *tree, int index) {
    return tree->nodes[index].leaf;
}

int get_next_index(b_tree_t *tree, int index) {
    return tree->nodes[index].next;
}

int get_key_index(b_tree_t *tree, char *key) {
    int i;
    for (i = 0; i < tree->size; i++) {
        if (strcmp(tree->nodes[i].key, key) == 0 && is_leaf(tree, i)) {
            return i;
        }
    }
    return -1;
}

void insert_record(b_tree_t *tree, char *key, lover_t record) {
    int i, j;
    if (get_key_index(tree, key) != -1) {
        printf("Error: Key already exists.\n");
        return;
    }
    i = tree->size;
    strcpy(tree->nodes[i].key, key);
    tree->nodes[i].leaf = 1;
    tree->records[i] = record;
    tree->size++;
    while (i > 0 && strcmp(tree->nodes[i-1].key, key) > 0) {
        j = get_next_index(tree, i-1);
        tree->nodes[i].next = j;
        tree->nodes[j].next = i;
        strcpy(tree->nodes[i].key, tree->nodes[i-1].key);
        i--;
    }
    strcpy(tree->nodes[i].key, key);
}

void print_tree(b_tree_t *tree, int index) {
    int i;
    if (is_leaf(tree, index)) {
        printf("%s: %s, %d, %.2f\n", tree->nodes[index].key, tree->records[index].name, tree->records[index].age, tree->records[index].love_level);
        return;
    }
    printf("%s: INDEX\n", tree->nodes[index].key);
    for (i = 0; i < tree->order && index+i < tree->size; i++) {
        print_tree(tree, get_next_index(tree, index+i));
    }
}

int main() {
    b_tree_t my_tree;
    lover_t lover1 = {"Romeo", 25, 10.0};
    lover_t lover2 = {"Juliet", 18, 15.0};
    char key1[] = "Montague";
    char key2[] = "Capulet";

    create_tree(&my_tree, 5);

    insert_record(&my_tree, key1, lover1);
    insert_record(&my_tree, key2, lover2);

    printf("ROMANTIC INDEX:\n");
    print_tree(&my_tree, 0);

    return 0;
}

#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

struct Graph {
    int num_vertices;
    int** adjacency_matrix;
};

struct Graph* create_graph(int num_vertices) {
    struct Graph* graph = (struct Graph*)malloc(sizeof(struct Graph));
    graph->num_vertices = num_vertices;
    graph->adjacency_matrix = (int**)malloc(num_vertices * sizeof(int*));
    for (int i = 0; i < num_vertices; i++) {
        graph->adjacency_matrix[i] = (int*)malloc(num_vertices * sizeof(int));
    }
    for (int i = 0; i < num_vertices; i++) {
        for (int j = 0; j < num_vertices; j++) {
            graph->adjacency_matrix[i][j] = 0;
        }
    }
    return graph;
}

void free_graph(struct Graph* graph) {
    for (int i = 0; i < graph->num_vertices; i++) {
        free(graph->adjacency_matrix[i]);
    }
    free(graph->adjacency_matrix);
    free(graph);
}

bool is_safe(struct Graph* graph, int vertex, int color, int* colors) {
    for (int i = 0; i < graph->num_vertices; i++) {
        if (graph->adjacency_matrix[vertex][i] == 1 && colors[i] == color) {
            return false;
        }
    }
    return true;
}

bool graph_coloring(struct Graph* graph, int* colors, int vertex) {
    if (vertex == graph->num_vertices) {
        return true;
    }
    for (int color = 1; color <= graph->num_vertices; color++) {
        if (is_safe(graph, vertex, color, colors)) {
            colors[vertex] = color;
            if (graph_coloring(graph, colors, vertex + 1)) {
                return true;
            }
            colors[vertex] = 0;
        }
    }
    return false;
}

int main() {
    int num_vertices;
    printf("Enter the number of vertices: ");
    scanf("%d", &num_vertices);
    struct Graph* graph = create_graph(num_vertices);
    for (int i = 0; i < num_vertices; i++) {
        for (int j = 0; j < num_vertices; j++) {
            int edge;
            printf("Enter 1 if there is an edge between %d and %d, otherwise enter 0: ", i + 1, j + 1);
            scanf("%d", &edge);
            graph->adjacency_matrix[i][j] = edge;
        }
    }
    int* colors = (int*)malloc(num_vertices * sizeof(int));
    for (int i = 0; i < num_vertices; i++) {
        colors[i] = 0;
    }
    if (graph_coloring(graph, colors, 0)) {
        printf("The graph can be colored using %d colors:\n", graph->num_vertices);
        for (int i = 0; i < num_vertices; i++) {
            printf("Vertex %d: Color %d\n", i + 1, colors[i]);
        }
    } else {
        printf("The graph cannot be colored using %d colors.\n", graph->num_vertices);
    }
    free_graph(graph);
    free(colors);
    return 0;
}

