/*
 * Airport Baggage Handling Simulation using recursive functions
 */

#include <stdio.h>

// Global variables
int num_passengers = 0;
int num_bags = 0;
int num_checkins = 0;
int num_xrays = 0;

// Function prototypes
void checkin(int id);
void baggage(int id);
void xray(int id);

// Main function
int main() {
  int id, choice;

  printf("Welcome to Airport Baggage Handling Simulation!\n");
  printf("How many passengers would you like to simulate? ");
  scanf("%d", &num_passengers);

  // Loop for each passenger
  for (id = 1; id <= num_passengers; id++) {
    printf("\nPassenger %d:\n", id);
    printf("1. Check in\n");
    printf("2. Baggage\n");
    printf("3. X-ray\n");
    printf("4. Exit\n");
    printf("Choice: ");
    scanf("%d", &choice);

    // Check in
    if (choice == 1) {
      checkin(id);
    }

    // Baggage
    else if (choice == 2) {
      baggage(id);
    }

    // X-ray
    else if (choice == 3) {
      xray(id);
    }

    // Exit
    else if (choice == 4) {
      printf("Goodbye!\n");
      break;
    }
  }

  // Display results
  printf("\n\nPassengers: %d\n", num_passengers);
  printf("Check-ins: %d\n", num_checkins);
  printf("Baggage: %d\n", num_bags);
  printf("X-rays: %d\n", num_xrays);

  return 0;
}

// Check in function
void checkin(int id) {
  int choice;

  printf("\nPassenger %d: Check in\n", id);
  printf("1. Yes\n");
  printf("2. No\n");
  printf("Choice: ");
  scanf("%d", &choice);

  // If checked in
  if (choice == 1) {
    num_checkins++;
    printf("You have checked in.\n");

    // Baggage
    printf("Would you like to check your baggage?\n");
    printf("1. Yes\n");
    printf("2. No\n");
    printf("Choice: ");
    scanf("%d", &choice);

    // If baggage checked
    if (choice == 1) {
      baggage(id);
    }

    // If baggage not checked
    else if (choice == 2) {
      printf("You have not checked your baggage.\n");

      // X-ray
      printf("Would you like to go through X-ray?\n");
      printf("1. Yes\n");
      printf("2. No\n");
      printf("Choice: ");
      scanf("%d", &choice);

      // If X-ray
      if (choice == 1) {
        xray(id);
      }

      // If no X-ray
      else if (choice == 2) {
        printf("You have not gone through X-ray.\n");
      }
    }
  }

  // If not checked in
  else if (choice == 2) {
    printf("You have not checked in.\n");
  }
}

// Baggage function
void baggage(int id) {
  int choice;

  printf("\nPassenger %d: Baggage\n", id);
  printf("1. Yes\n");
  printf("2. No\n");
  printf("Choice: ");
  scanf("%d", &choice);

  // If baggage checked
  if (choice == 1) {
    num_bags++;
    printf("You have checked your baggage.\n");

    // X-ray
    printf("Would you like to go through X-ray?\n");
    printf("1. Yes\n");
    printf("2. No\n");
    printf("Choice: ");
    scanf("%d", &choice);

    // If X-ray
    if (choice == 1) {
      xray(id);
    }

    // If no X-ray
    else if (choice == 2) {
      printf("You have not gone through X-ray.\n");
    }
  }

  // If baggage not checked
  else if (choice == 2) {
    printf("You have not checked your baggage.\n");
  }
}

// X-ray function
void xray(int id) {
  int choice;

  printf("\nPassenger %d: X-ray\n", id);
  printf("1. Yes\n");
  printf("2. No\n");
  printf("Choice: ");
  scanf("%d", &choice);

  // If X-ray
  if (choice == 1) {
    num_xrays++;
    printf("You have gone through X-ray.\n");
  }

  // If no X-ray
  else if (choice == 2) {
    printf("You have not gone through X-ray.\n");
  }
}

/*
 * Functions related to generic helpers functions
 */
#include <linux/kernel.h>
#include <linux/module.h>
#include <linux/bio.h>
#include <linux/blkdev.h>
#include <linux/scatterlist.h>
#include <linux/gfp.h>

#include "blk.h"

struct bio_batch {
	atomic_t		done;
	unsigned long		flags;
	struct completion	*wait;
};

static void bio_batch_end_io(struct bio *bio, int err)
{
	struct bio_batch *bb = bio->bi_private;

	if (err && (err != -EOPNOTSUPP))
		clear_bit(BIO_UPTODATE, &bb->flags);
	if (atomic_dec_and_test(&bb->done))
		complete(bb->wait);
	bio_put(bio);
}

/**
 * blkdev_issue_discard - queue a discard
 * @bdev:	blockdev to issue discard for
 * @sector:	start sector
 * @nr_sects:	number of sectors to discard
 * @gfp_mask:	memory allocation flags (for bio_alloc)
 * @flags:	BLKDEV_IFL_* flags to control behaviour
 *
 * Description:
 *    Issue a discard request for the sectors in question.
 */
int blkdev_issue_discard(struct block_device *bdev, sector_t sector,
		sector_t nr_sects, gfp_t gfp_mask, int flags)
{
	DECLARE_COMPLETION_ONSTACK(wait);
	struct request_queue *q = bdev_get_queue(bdev);
	int type = (1 << BIO_RW) | (1 << BIO_RW_DISCARD);
	unsigned int max_discard_sectors;
	struct bio_batch bb;
	struct bio *bio;
	int ret = 0;

	/*
	 * DEPRECATED support for DISCARD_FL_BARRIER which will
	 * fail with -EOPNOTSUPP (due to implicit BIO_RW_BARRIER)
	 */
	if (flags & DISCARD_FL_BARRIER)
		type = DISCARD_BARRIER;

	if (!q)
		return -ENXIO;

	if (!blk_queue_discard(q))
		return -EOPNOTSUPP;

	/*
	 * Ensure that max_discard_sectors is of the proper
	 * granularity
	 */
	max_discard_sectors = min(q->limits.max_discard_sectors, UINT_MAX >> 9);
	if (unlikely(!max_discard_sectors)) {
		/* Avoid infinite loop below. Being cautious never hurts. */
		return -EOPNOTSUPP;
	} else if (q->limits.discard_granularity) {
		unsigned int disc_sects = q->limits.discard_granularity >> 9;

		max_discard_sectors &= ~(disc_sects - 1);
	}

	atomic_set(&bb.done, 1);
	bb.flags = 1 << BIO_UPTODATE;
	bb.wait = &wait;

	while (nr_sects) {
		bio = bio_alloc(gfp_mask, 1);
		if (!bio) {
			ret = -ENOMEM;
			break;
		}

		bio->bi_sector = sector;
		bio->bi_end_io = bio_batch_end_io;
		bio->bi_bdev = bdev;
		bio->bi_private = &bb;

		if (nr_sects > max_discard_sectors) {
			bio->bi_size = max_discard_sectors << 9;
			nr_sects -= max_discard_sectors;
			sector += max_discard_sectors;
		} else {
			bio->bi_size = nr_sects << 9;
			nr_sects = 0;
		}

		atomic_inc(&bb.done);
		submit_bio(type, bio);
	}

	/* Wait for bios in-flight */
	if (!atomic_dec_and_test(&bb.done))
		wait_for_completion(&wait);

	if (!test_bit(BIO_UPTODATE, &bb.flags))
		ret = -EIO;

	return ret;
}
EXPORT_SYMBOL(blkdev_issue_discard);

/**
 * blkdev_issue_zeroout - generate number of zero filed write bios
 * @bdev:	blockdev to issue
 * @sector:	start sector
 * @nr_sects:	number of sectors to write
 * @gfp_mask:	memory allocation flags (for bio_alloc)
 *
 * Description:
 *  Generate and issue number of bios with zerofiled pages.
 */

int blkdev_issue_zeroout(struct block_device *bdev, sector_t sector,
			sector_t nr_sects, gfp_t gfp_mask)
{
	int ret;
	struct bio *bio;
	struct bio_batch bb;
	unsigned int sz;
	DECLARE_COMPLETION_ONSTACK(wait);

	atomic_set(&bb.done, 1);
	bb.flags = 1 << BIO_UPTODATE;
	bb.wait = &wait;

	ret = 0;
	while (nr_sects != 0) {
		bio = bio_alloc(gfp_mask,
				min(nr_sects, (sector_t)BIO_MAX_PAGES));
		if (!bio) {
			ret = -ENOMEM;
			break;
		}

		bio->bi_sector = sector;
		bio->bi_bdev   = bdev;
		bio->bi_end_io = bio_batch_end_io;
		bio->bi_private = &bb;

		while (nr_sects != 0) {
			sz = min((sector_t) PAGE_SIZE >> 9 , nr_sects);
			ret = bio_add_page(bio, ZERO_PAGE(0), sz << 9, 0);
			nr_sects -= ret >> 9;
			sector += ret >> 9;
			if (ret < (sz << 9))
				break;
		}
		ret = 0;
		atomic_inc(&bb.done);
		submit_bio(WRITE, bio);
	}

	/* Wait for bios in-flight */
	if (!atomic_dec_and_test(&bb.done))
		wait_for_completion(&wait);

	if (!test_bit(BIO_UPTODATE, &bb.flags))
		/* One of bios in the batch was completed with error.*/
		ret = -EIO;

	return ret;
}
EXPORT_SYMBOL(blkdev_issue_zeroout);

