#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// define the dimensions of the ASCII art
#define WIDTH 80
#define HEIGHT 60

// define the maximum intensity value
#define MAX_INTENSITY 255

// define the ASCII characters used in the art
#define CHARACTERS " .:-=+*#%@"

// define the length of the characters string
#define CHARACTERS_LEN strlen(CHARACTERS)

// define a struct to hold the pixel values
typedef struct {
    int r;
    int g;
    int b;
} Pixel;

// define a function to read a PPM file and return the pixel array
Pixel* readPPM(char* filename, int* width, int* height) {
    FILE* fp;
    char format[3];
    int maxval;

    // open the PPM file for reading
    if ((fp = fopen(filename, "rb")) == NULL) {
        fprintf(stderr, "Error: cannot open file %s\n", filename);
        exit(1);
    }

    // read the PPM header
    fscanf(fp, "%s\n", format);
    if (strcmp(format, "P6") != 0) {
        fprintf(stderr, "Error: wrong file format %s\n", format);
        exit(1);
    }
    fscanf(fp, "%d %d\n", width, height);
    fscanf(fp, "%d\n", &maxval);
    if (maxval > MAX_INTENSITY) {
        fprintf(stderr, "Error: maximum intensity exceeds %d\n", MAX_INTENSITY);
        exit(1);
    }

    // allocate the pixel array
    Pixel* pixels = (Pixel*) malloc((*width) * (*height) * sizeof(Pixel));

    // read the pixel values
    int i;
    for (i = 0; i < (*width) * (*height); i++) {
        pixels[i].r = fgetc(fp);
        pixels[i].g = fgetc(fp);
        pixels[i].b = fgetc(fp);
    }

    // close the file
    fclose(fp);

    // return the pixel array
    return pixels;
}

// define a function to convert the pixel values to ASCII characters
void convertPixelsToAscii(Pixel* pixels, char* ascii, int width, int height) {
    int i, j, k;
    int index;
    int intensity;

    // loop over the pixels
    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            // calculate the index of the current pixel
            index = i * width + j;

            // calculate the intensity of the current pixel
            intensity = (pixels[index].r + pixels[index].g + pixels[index].b) / 3;

            // calculate the index of the ASCII character to use
            k = (int)((double)(intensity * CHARACTERS_LEN) / MAX_INTENSITY);

            // set the ASCII character in the output array
            ascii[index] = CHARACTERS[k];
        }
        ascii[(i+1)*width] = '\n'; // add a newline character at the end of each row
    }
    ascii[width*height] = '\0'; // add a null terminator at the end of the string
}

int main(int argc, char** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        exit(1);
    }

    char* filename = argv[1];
    int width, height;
    Pixel* pixels = readPPM(filename, &width, &height);

    char ascii[WIDTH * HEIGHT];
    convertPixelsToAscii(pixels, ascii, width, height);

    printf("%s", ascii);

    free(pixels);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BOARD_SIZE 8
#define MAX_DEPTH 3

typedef enum { EMPTY, PAWN, ROOK, KNIGHT, BISHOP, QUEEN, KING } Piece;
typedef enum { WHITE, BLACK } Color;

typedef struct {
    Piece piece;
    Color color;
} Square;

typedef struct {
    Square board[BOARD_SIZE][BOARD_SIZE];
} ChessBoard;

// Function prototypes
void initialize_board(ChessBoard *board);
void print_board(const ChessBoard *board);
int evaluate_board(const ChessBoard *board);
int minimax(ChessBoard *board, int depth, int isMaximizing);
void play_game();

int main() {
    play_game();
    return 0;
}

void initialize_board(ChessBoard *board) {
    memset(board, 0, sizeof(ChessBoard));

    // Set up pawns
    for (int i = 0; i < BOARD_SIZE; i++) {
        board->board[1][i].piece = PAWN;
        board->board[1][i].color = WHITE;
        board->board[6][i].piece = PAWN;
        board->board[6][i].color = BLACK;
    }

    // Set up rooks
    board->board[0][0].piece = ROOK;
    board->board[0][0].color = WHITE;
    board->board[0][7].piece = ROOK;
    board->board[0][7].color = WHITE;
    board->board[7][0].piece = ROOK;
    board->board[7][0].color = BLACK;
    board->board[7][7].piece = ROOK;
    board->board[7][7].color = BLACK;

    // Set up knights
    board->board[0][1].piece = KNIGHT;
    board->board[0][1].color = WHITE;
    board->board[0][6].piece = KNIGHT;
    board->board[0][6].color = WHITE;
    board->board[7][1].piece = KNIGHT;
    board->board[7][1].color = BLACK;
    board->board[7][6].piece = KNIGHT;
    board->board[7][6].color = BLACK;

    // Set up bishops
    board->board[0][2].piece = BISHOP;
    board->board[0][2].color = WHITE;
    board->board[0][5].piece = BISHOP;
    board->board[0][5].color = WHITE;
    board->board[7][2].piece = BISHOP;
    board->board[7][2].color = BLACK;
    board->board[7][5].piece = BISHOP;
    board->board[7][5].color = BLACK;

    // Set up queens and kings
    board->board[0][3].piece = QUEEN;
    board->board[0][3].color = WHITE;
    board->board[0][4].piece = KING;
    board->board[0][4].color = WHITE;
    board->board[7][3].piece = QUEEN;
    board->board[7][3].color = BLACK;
    board->board[7][4].piece = KING;
    board->board[7][4].color = BLACK;
}

void print_board(const ChessBoard *board) {
    const char *piece_symbols[] = { '.', 'P', 'R', 'N', 'B', 'Q', 'K' };
    for (int i = BOARD_SIZE - 1; i >= 0; i--) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board->board[i][j].piece == EMPTY) {
                printf("%c ", piece_symbols[0]);
            } else {
                char symbol = piece_symbols[board->board[i][j].piece];
                if (board->board[i][j].color == BLACK) {
                    symbol += ('a' - 'A');
                }
                printf("%c ", symbol);
            }
        }
        printf("\n");
    }
}

int evaluate_board(const ChessBoard *board) {
    int score = 0;
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board->board[i][j].piece != EMPTY) {
                int piece_value = board->board[i][j].piece == PAWN ? 1 :
                                  board->board[i][j].piece == KNIGHT ? 3 :
                                  board->board[i][j].piece == BISHOP ? 3 :
                                  board->board[i][j].piece == ROOK ? 5 :
                                  board->board[i][j].piece == QUEEN ? 9 : 0;
                score += (board->board[i][j].color == WHITE ? piece_value : -piece_value);
            }
        }
    }
    return score;
}

int minimax(ChessBoard *board, int depth, int isMaximizing) {
    if (depth == 0) {
        return evaluate_board(board);
    }

    if (isMaximizing) {
        int bestScore = -10000;
        // Example: This would be replaced with actual move generation.
        // for each possible move, apply move, call minimax on resulting board
        // and undo the move
        bestScore += 10; // This is a placeholder
        return bestScore;
    } else {
        int bestScore = 10000;
        // Similarly here for minimizing player
        bestScore -= 10; // This is a placeholder
        return bestScore;
    }
}

void play_game() {
    ChessBoard board;
    initialize_board(&board);
    print_board(&board);

    for (int turn = 0; turn < 10; turn++) { // Play 10 turns as a simple demo
        int bestScore = minimax(&board, MAX_DEPTH, 1);
        printf("Best score for white: %d\n", bestScore);
        // This should include the logic to make a move based on the minimax score
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define structures and constants
typedef struct {
    char name[50];
    float amount;
} Transaction;

#define MAX_TRANSACTIONS 100
#define MONTHS_IN_YEAR 12

// Global variables
Transaction transactions[MAX_TRANSACTIONS];
int current_transaction = 0;
float monthly_income = 0;
float monthly_expenses = 0;
float savings_goal = 0;
float current_savings = 0;
int month = 1;

// Function prototypes
void record_transaction(char* description, float amount);
void calculate_totals();
void display_totals();
void next_month();

int main() {
    char description[100];
    float income;

    printf("\nWelcome to thee Savvy Scribe, a humble financial planner!\n");
    printf("Enter thine monthly income:\n");
    scanf("%f", &income);
    monthly_income = income;

    while (month <= MONTHS_IN_YEAR) {
        printf("\nMonth %d:\n", month);
        printf("Enter a description for this month's income (leave blank for none):\n");
        scanf("%s", description);
        if (strcmp(description, "") != 0) {
            record_transaction(description, monthly_income);
        }

        printf("Enter monthly expenses (leave blank when done):\n");
        while (1) {
            printf("Description: ");
            scanf("%s", description);
            if (strcmp(description, "") == 0) {
                break;
            }
            printf("Amount: ");
            float expense;
            scanf("%f", &expense);
            record_transaction(description, -expense);
        }

        calculate_totals();
        display_totals();
        next_month();
    }

    printf("\nThy financial year hath come to an end!\n");
    printf("Total savings: %.2f\n", current_savings);

    return 0;
}

void record_transaction(char* description, float amount) {
    transactions[current_transaction].amount = amount;
    strcpy(transactions[current_transaction].name, description);
    current_transaction++;
}

void calculate_totals() {
    int i;
    for (i = 0; i < current_transaction; i++) {
        if (transactions[i].amount > 0) {
            monthly_income += transactions[i].amount;
        } else {
            monthly_expenses += transactions[i].amount;
        }
    }
}

void display_totals() {
    printf("Monthly income: %.2f\n", monthly_income);
    printf("Monthly expenses: %.2f\n", monthly_expenses);
    current_savings += monthly_income - monthly_expenses;
}

void next_month() {
    monthly_expenses = 0;
    month++;
}

