// Define the memory game structure
typedef struct MemoryGame
{
    int *cards;
    int size;
    int currentCard;
} MemoryGame;

// Function to initialize a memory game
MemoryGame *initializeMemoryGame(int size)
{
    MemoryGame *game = malloc(sizeof(MemoryGame));
    game->cards = malloc(size * sizeof(int));
    game->size = size;
    game->currentCard = 0;

    return game;
}

// Function to play a round of the memory game
void playRound(MemoryGame *game)
{
    // Get the card to be guessed
    int targetCard = game->cards[game->currentCard];

    // Show the card to the player
    printf("The card is: %d\n", targetCard);

    // Get the player's guess
    int guessCard;
    printf("Enter your guess: ");
    scanf("%d", &guessCard);

    // Check if the guess is correct
    if (guessCard == targetCard)
    {
        // Increment the current card
        game->currentCard++;

        // If the current card is the end of the game, end the game
        if (game->currentCard == game->size - 1)
        {
            printf("Congratulations! You won the game!\n");
            free(game->cards);
            free(game);
        }
        else
        {
            // Play the next round
            playRound(game);
        }
    }
    else
    {
        // Give the player feedback
        printf("Sorry, your guess is incorrect.\n");
    }
}

int main()
{
    // Initialize the memory game
    MemoryGame *game = initializeMemoryGame(5);

    // Play the game
    playRound(game);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

// Minimalist Metadata Extractor for JPEG Files

// JPEG Marker Segment Constants
#define SOF0  0xC0 // Start of Frame (Baseline)
#define DQT   0xDB // Define Quantization Table
#define DRI   0xDD // Define Restart Interval
#define DHT   0xC4 // Define Huffman Table
#define SOS   0xDA // Start of Scan

// Huffman Table Type Constants
#define DC_TABLE  0 // DC coefficients
#define AC_TABLE  1 // AC coefficients

// JPEG Quantization Table
typedef uint8_t JpegQuantTable[64];

// JPEG Huffman Table
typedef struct {
    uint8_t  codeLength[16];    // Code length for each code
    uint16_t codeValue[256];   // Code value for each code
} JpegHuffmanTable;

// JPEG Scan Header
typedef struct {
    uint8_t  componentCount;    // Number of components in the scan
    struct {
        uint8_t  componentId;     // Component identifier
        uint8_t  dcTable;        // DC Huffman table index
        uint8_t  acTable;        // AC Huffman table index
    } component[4];             // Max 4 components
} JpegScanHeader;

// Function to extract JPEG metadata
int extract_jpeg_metadata(const uint8_t *jpeg_data, size_t jpeg_size) {
    uint32_t marker;
    int marker_size;
    int offset = 0;

    // Check for JPEG SOI marker
    if (jpeg_data[offset++] != 0xFF || jpeg_data[offset++] != 0xD8) {
        printf("Invalid JPEG file: missing SOI marker\n");
        return -1;
    }

    // Loop through JPEG markers
    while (offset < jpeg_size) {
        // Read marker segment
        marker = (jpeg_data[offset++] << 8) | jpeg_data[offset++];
        marker_size = (jpeg_data[offset++] << 8) | jpeg_data[offset++];

        // Process marker segment based on its type
        switch (marker) {
            case SOF0:
                printf("SOF0: Baseline JPEG, %dx%d pixels\n",
                    jpeg_data[offset + 7], jpeg_data[offset + 8]);
                offset += marker_size - 2;
                break;

            case DQT:
                printf("DQT: Quantization table\n");
                offset += marker_size - 2;
                break;

            case DRI:
                printf("DRI: Restart interval %d\n",
                    (jpeg_data[offset + 4] << 8) | jpeg_data[offset + 5]);
                offset += marker_size - 2;
                break;

            case DHT:
                {
                    uint8_t type = jpeg_data[offset++];
                    uint8_t tableId = jpeg_data[offset++];
                    if (type == DC_TABLE) {
                        printf("DHT: DC Huffman table #%d\n", tableId);
                    } else if (type == AC_TABLE) {
                        printf("DHT: AC Huffman table #%d\n", tableId);
                    } else {
                        printf("Unknown DHT type %d\n", type);
                    }
                    offset += marker_size - 4;
                }
                break;

            case SOS:
                {
                    JpegScanHeader *scanHeader = (JpegScanHeader *) &jpeg_data[offset];
                    printf("SOS: Start of scan\n");
                    printf("  Component count: %d\n", scanHeader->componentCount);
                    for (int i = 0; i < scanHeader->componentCount; i++) {
                        printf("  Component %d:\n", i + 1);
                        printf("    Component ID:     %d\n", scanHeader->component[i].componentId);
                        printf("    DC Huffman table: %d\n", scanHeader->component[i].dcTable);
                        printf("    AC Huffman table: %d\n", scanHeader->component[i].acTable);
                    }
                    offset += marker_size - 2;
                }
                break;

            default:
                printf("Unknown JPEG marker 0x%04X\n", marker);
                offset += marker_size - 2;
                break;
        }
    }

    return 0;
}

// Main function to test the metadata extractor
int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <jpeg_file>\n", argv[0]);
        return 1;
    }

    // Read JPEG file
    FILE *fp = fopen(argv[1], "rb");
    if (!fp) {
        printf("Error opening file %s\n", argv[1]);
        return 1;
    }
    fseek(fp, 0, SEEK_END);
    size_t jpeg_size = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    uint8_t *jpeg_data = malloc(jpeg_size);
    if (!jpeg_data) {
        printf("Error allocating memory for JPEG data\n");
        return 1;
    }
    if (fread(jpeg_data, 1, jpeg_size, fp) != jpeg_size) {
        printf("Error reading JPEG data\n");
        free(jpeg_data);
        fclose(fp);
        return 1;
    }
    fclose(fp);

    // Extract JPEG metadata
    int ret = extract_jpeg_metadata(jpeg_data, jpeg_size);
    free(jpeg_data);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define HOTEL_NAME "Cosmic Dreams"
#define MAX_GUESTS 100
#define ROOMS 50
#define RATES (100 * 3)

typedef struct {
    char name[50];
    char email[50];
    int checkin;
    int checkout;
    int room_no;
    int status;
} guest_t;

typedef struct {
    char name[50];
    int num_guests;
    int capacity;
    int rate;
} room_t;

typedef struct {
    char name[50];
    int num_rooms;
    int total_guests;
    int total_revenue;
} hotel_t;

hotel_t hotel;
room_t rooms[ROOMS];
guest_t guests[MAX_GUESTS];

void init_hotel() {
    int i, j;

    for (i = 0; i < ROOMS; i++) {
        rooms[i].num_guests = 0;
        rooms[i].capacity = 5;
        rooms[i].rate = RATES;
    }

    for (i = 0; i < MAX_GUESTS; i++) {
        guests[i].name[0] = '\0';
        guests[i].email[0] = '\0';
        guests[i].checkin = 0;
        guests[i].checkout = 0;
        guests[i].room_no = 0;
        guests[i].status = 0;
    }

    hotel.num_rooms = ROOMS;
    hotel.total_guests = 0;
    hotel.total_revenue = 0;
}

void handle_reservation(int room_no, int num_guests) {
    int i;

    for (i = 0; i < num_guests; i++) {
        if (guests[i].name[0] == '\0') {
            strcpy(guests[i].name, "Unknown Guest");
        }
        guests[i].room_no = room_no;
        guests[i].checkin = time(NULL);
        guests[i].status = 1;
        hotel.total_guests++;
    }

    rooms[room_no].num_guests += num_guests;
    hotel.total_revenue += rooms[room_no].rate * num_guests;
}

void check_out(int room_no) {
    int i;

    for (i = 0; i < rooms[room_no].num_guests; i++) {
        guests[i].checkout = time(NULL);
        guests[i].status = 0;
    }

    rooms[room_no].num_guests -= rooms[room_no].num_guests;
    hotel.total_guests -= rooms[room_no].num_guests;
}

void display_hotel_info() {
    int i;

    printf("Hotel Name: %s\n", HOTEL_NAME);
    printf("Total Guests: %d\n", hotel.total_guests);
    printf("Total Revenue: %d\n", hotel.total_revenue);

    for (i = 0; i < ROOMS; i++) {
        printf("Room %d: Capacity %d, Occupancy %d, Rate %d\n",
            i, rooms[i].capacity, rooms[i].num_guests, rooms[i].rate);
    }

    for (i = 0; i < MAX_GUESTS; i++) {
        if (guests[i].name[0] != '\0') {
            printf("Guest %d: Name %s, Email %s, Checkin %d, Checkout %d\n",
                i, guests[i].name, guests[i].email, guests[i].checkin, guests[i].checkout);
        }
    }
}

int main() {
    init_hotel();

    while (1) {
        int room_no, num_guests;

        printf("Welcome to the Cosmic Dreams Hotel!\n");
        printf("Please enter the room number and number of guests: ");
        scanf("%d%d", &room_no, &num_guests);

        handle_reservation(room_no, num_guests);

        display_hotel_info();
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define KEY_SIZE 16  // Size of encryption key in bytes

// Custom encryption algorithm using a key
void encrypt(char *plaintext, char *key) {
    int key_len = strlen(key);
    int plaintext_len = strlen(plaintext);

    // Initialize a keystream using the provided key
    char keystream[plaintext_len];
    for (int i = 0; i < plaintext_len; i++) {
        keystream[i] = key[i % key_len];
    }

    // XOR plaintext with keystream for encryption
    for (int i = 0; i < plaintext_len; i++) {
        plaintext[i] ^= keystream[i];
    }
}

int main() {
    // Prompt for the message to encrypt
    char plaintext[100];
    printf("Enter the message to encrypt: ");
    gets(plaintext);

    // Prompt for the encryption key
    char key[KEY_SIZE];
    printf("Enter the encryption key (16 characters): ");
    gets(key);

    // Encrypt the plaintext using the provided key
    encrypt(plaintext, key);

    // Print the encrypted message
    printf("Encrypted message: %s\n", plaintext);

    // Allow user to decrypt the message
    char choice;
    printf("Would you like to decrypt the message? (y/n): ");
    scanf(" %c", &choice);

    if (choice == 'y' || choice == 'Y') {
        // Decrypt the message using the same key
        encrypt(plaintext, key);

        // Print the decrypted message
        printf("Decrypted message: %s\n", plaintext);
    }

    return 0;
}

