{

	initialize();

	char temp = 'y';

	while (temp == 'y') {

		board.clearBoard();

		players[0].resetNumTurns();

		players[1].resetNumTurns();

		clearConsole();

		for (size_t i = 0; i < (6 * 7)/2; i++) {

			cout << board;

