    draw_border();
    draw_pacman();
    draw_food();

    move_pacman();

    draw_border();
    draw_pacman();
    draw_food();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    int data;
    struct node* next;
} Node;

void append(Node** head, int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;

    if (*head == NULL) {
        *head = newNode;
        return;
    }

    Node* temp = *head;
    while (temp->next!= NULL) {
        temp = temp->next;
    }
    temp->next = newNode;
}

void prepend(Node** head, int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = *head;

    *head = newNode;
}

void printList(Node* head) {
    Node* temp = head;
    while (temp!= NULL) {
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("\n");
}

int main() {
    Node* head = NULL;

    append(&head, 10);
    append(&head, 20);
    prepend(&head, 5);
    prepend(&head, 2);
    prepend(&head, 1);

    printList(head);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LENGTH 100

// Function to sort an array of strings based on their length
void sort_strings(char *arr[], int len) {
  int i, j, min_idx;

  for (i = 0; i < len - 1; i++) {
    min_idx = i;
    for (j = i + 1; j < len; j++) {
      if (strlen(arr[j]) < strlen(arr[min_idx])) {
        min_idx = j;
      }
    }
    if (min_idx != i) {
      swap(arr[i], arr[min_idx]);
    }
  }
}

// Function to swap two strings
void swap(char *a, char *b) {
  char temp[2 * strlen(a)];
  strcpy(temp, a);
  strcpy(a, b);
  strcpy(b, temp);
}

int main() {
  char arr[5][MAX_LENGTH] = {
    "The quick brown fox",
    "A short and simple sentence",
    "The big black cat",
    "A long and winding road",
    "The tiny kitten"
  };
  int len = sizeof(arr) / sizeof(arr[0]);

  // Sort the array of strings based on their length
  sort_strings(arr, len);

  // Print the sorted array of strings
  for (int i = 0; i < len; i++) {
    printf("%s\n", arr[i]);
  }

  return 0;
}

