#define DRONE_SUCCESS 0
#define DRONE_FAIL -1

typedef struct {
    char *port;
    int baud;
    int fd;
} Drone;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("\nExiting Drone Control. Goodbye!\n");
        exit(0);
    }
}

int open_serial_port(Drone *drone) {
    drone->fd = open(drone->port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (drone->fd == -1) {
        perror("Failed to open the serial port");
        return DRONE_FAIL;
    }
    return DRONE_SUCCESS;
}

void configure_serial_port(Drone *drone) {
    struct termios options;
    tcgetattr(drone->fd, &options);
    cfsetispeed(&options, drone->baud);
    cfsetospeed(&options, drone->baud);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB; // No parity
    options.c_cflag &= ~CSTOPB; // 1 stop bit
    options.c_cflag &= ~CSIZE;   // Clear current char size
    options.c_cflag |= CS8;      // 8 data bits

    options.c_cc[VMIN] = 0;  // Non-blocking reads
    options.c_cc[VTIME] = 1; // 0.1 seconds read timeout

    tcsetattr(drone->fd, TCSANOW, &options);
}

void send_command(Drone *drone, const char *command) {
    write(drone->fd, command, strlen(command));
}

void read_response(Drone *drone) {
    char buffer[255];
    int n = read(drone->fd, buffer, sizeof(buffer));
    if (n > 0) {
        buffer[n] = '\0'; // Null terminate the string
        printf("Drone Response: %s\n", buffer);
    } else {
        printf("No response from drone.\n");
    }
}

void take_off(Drone *drone) {
    printf("Sending take-off command to drone...\n");
    send_command(drone, "TAKE_OFF\n");
    read_response(drone);
}

void land(Drone *drone) {
    printf("Sending land command to drone...\n");
    send_command(drone, "LAND\n");
    read_response(drone);
}

void move_forward(Drone *drone) {
    printf("Sending move forward command to drone...\n");
    send_command(drone, "MOVE_FORWARD\n");
    read_response(drone);
}

void move_backward(Drone *drone) {
    printf("Sending move backward command to drone...\n");
    send_command(drone, "MOVE_BACKWARD\n");
    read_response(drone);
}

void turn_left(Drone *drone) {
    printf("Sending turn left command to drone...\n");
    send_command(drone, "TURN_LEFT\n");
    read_response(drone);
}

void turn_right(Drone *drone) {
    printf("Sending turn right command to drone...\n");
    send_command(drone, "TURN_RIGHT\n");
    read_response(drone);
}

void display_menu() {
    printf("Drone Remote Control:\n");
    printf("1. Take Off\n");
    printf("2. Land\n");
    printf("3. Move Forward\n");
    printf("4. Move Backward\n");
    printf("5. Turn Left\n");
    printf("6. Turn Right\n");
    printf("7. Exit\n");
    printf("Choose an option: ");
}

int main() {
    signal(SIGINT, handle_signal);

    Drone myDrone;
    myDrone.port = "/dev/ttyS0"; // Change as necessary for your system
    myDrone.baud = B9600; // Baud rate for communication

    if (open_serial_port(&myDrone) == DRONE_FAIL) {
        return EXIT_FAILURE;
    }

    configure_serial_port(&myDrone);

    int choice;
    while (1) {
        display_menu();
        scanf("%d", &choice);

        switch (choice) {
            case 1: take_off(&myDrone); break;
            case 2: land(&myDrone); break;
            case 3: move_forward(&myDrone); break;
            case 4: move_backward(&myDrone); break;
            case 5: turn_left(&myDrone); break;
            case 6: turn_right(&myDrone); break;
            case 7: 
                printf("Exiting Drone Control.\n");
                close(myDrone.fd);
                return EXIT_SUCCESS;
            default: 
                printf("Invalid choice. Please try again.\n");
        }
    }

    close(myDrone.fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdint.h>
#include <string.h>

#define MAX_LEN 1024

// Compression function
void compress(char *input, int len, char *output) {
  int i, j, k;
  uint32_t hash = 0;
  char *ptr = input;

  // Step 1: Hashing
  for (i = 0; i < len; i++) {
    hash ^= (uint32_t)ptr[i] << (i % 4);
  }

  // Step 2: Frequency analysis
  for (i = 0; i < len; i++) {
    hash ^= (uint32_t)ptr[i] << (i % 4);
  }

  // Step 3: Huffman coding
  for (i = 0; i < len; i++) {
    if (hash & 1) {
      output[i] = '1';
    } else {
      output[i] = '0';
    }
    hash >>= 1;
  }
}

// Decompression function
void decompress(char *input, int len, char *output) {
  int i, j, k;
  uint32_t hash = 0;
  char *ptr = input;

  // Step 1: Huffman decoding
  for (i = 0; i < len; i++) {
    if (input[i] == '1') {
      hash ^= (uint32_t)ptr[i] << (i % 4);
    } else {
      hash >>= 1;
    }
  }

  // Step 2: Inverse Huffman decoding
  for (i = 0; i < len; i++) {
    if (hash & 1) {
      output[i] = '1';
    } else {
      output[i] = '0';
    }
    hash >>= 1;
  }

  // Step 3: Inverse frequency analysis
  for (i = 0; i < len; i++) {
    if (output[i] == '1') {
      hash ^= (uint32_t)ptr[i] << (i % 4);
    }
  }

  // Step 4: Inverse hashing
  for (i = 0; i < len; i++) {
    if (hash & 1) {
      output[i] = ptr[i];
    }
    hash >>= 1;
  }
}

int main() {
  char input[] = "Hello World!";
  char output[MAX_LEN];

  compress(input, strlen(input), output);
  printf("Compressed string: %s\n", output);

  decompress(output, strlen(output), input);
  printf("Original string: %s\n", input);

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LOG_ENTRY_LENGTH 1024
#define MAX_URL_LENGTH 256
#define MAX_STATUS_CODE_LENGTH 4
#define MAX_REQUESTS 10000

typedef struct {
    char url[MAX_URL_LENGTH];
    int count;
} UrlCount;

typedef struct {
    char statusCode[MAX_STATUS_CODE_LENGTH];
    int count;
} StatusCount;

// Function to read log entries from a file
int readLogFile(const char *filename, char logEntries[MAX_REQUESTS][LOG_ENTRY_LENGTH], int maxEntries) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Unable to open the log file");
        return -1;
    }

    int entryCount = 0;
    while (fgets(logEntries[entryCount], LOG_ENTRY_LENGTH, file) && entryCount < maxEntries) {
        entryCount++;
    }

    fclose(file);
    return entryCount;
}

// Function to analyze the log entries
void analyzeLogs(char logEntries[MAX_REQUESTS][LOG_ENTRY_LENGTH], int entryCount, UrlCount *urls, StatusCount *statuses) {
    int urlCount = 0;
    int statusCount = 0;

    for (int i = 0; i < entryCount; i++) {
        char *url_ptr = strtok(logEntries[i], " ");
        char *statusCode_ptr = strtok(NULL, " ");

        if (url_ptr && statusCode_ptr) {
            // Count url occurrences
            int found = 0;
            for (int j = 0; j < urlCount; j++) {
                if (strcmp(urls[j].url, url_ptr) == 0) {
                    urls[j].count++;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                strcpy(urls[urlCount].url, url_ptr);
                urls[urlCount].count = 1;
                urlCount++;
            }

            // Count status code occurrences
            found = 0;
            for (int j = 0; j < statusCount; j++) {
                if (strcmp(statuses[j].statusCode, statusCode_ptr) == 0) {
                    statuses[j].count++;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                strcpy(statuses[statusCount].statusCode, statusCode_ptr);
                statuses[statusCount].count = 1;
                statusCount++;
            }
        }
    }

    // Print the analysis results
    printf("\n--- Log Analysis Results ---\n");
    printf("Total Requests: %d\n\n", entryCount);
    printf("Most Accessed URLs:\n");
    for (int i = 0; i < urlCount; i++) {
        printf("URL: %s, Count: %d\n", urls[i].url, urls[i].count);
    }
    printf("\nHTTP Status Codes:\n");
    for (int i = 0; i < statusCount; i++) {
        printf("Status Code: %s, Count: %d\n", statuses[i].statusCode, statuses[i].count);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char logEntries[MAX_REQUESTS][LOG_ENTRY_LENGTH];
    UrlCount urls[MAX_REQUESTS];
    StatusCount statuses[MAX_REQUESTS];

    int entryCount = readLogFile(argv[1], logEntries, MAX_REQUESTS);
    if (entryCount < 0) {
        return EXIT_FAILURE;
    }

    analyzeLogs(logEntries, entryCount, urls, statuses);
    return EXIT_SUCCESS;
}

