    }
}

int is_valid_move(char piece, int src_row, int src_col, int dest_row, int dest_col) {
    // Very basic move validation (only checks if the destination is empty)
    return (piece != EMPTY && (piece == EMPTY || piece == piece));
}

void make_move(ChessGame *game, int src_row, int src_col, int dest_row, int dest_col) {
    game->board[dest_row][dest_col] = game->board[src_row][src_col];
    game->board[src_row][src_col] = EMPTY;
}

void ai_move(ChessGame *game) {
    int src_row, src_col, dest_row, dest_col;
    while (1) {
        src_row = rand() % SIZE;
        src_col = rand() % SIZE;
        dest_row = rand() % SIZE;
        dest_col = rand() % SIZE;
        char piece = game->board[src_row][src_col];
        if (is_valid_move(piece, src_row, src_col, dest_row, dest_col)) {
            make_move(game, src_row, src_col, dest_row, dest_col);
            break;
        }
    }
}

int main() {
    ChessGame game;
    init_game(&game);
    char input[5];
    int src_row, src_col, dest_row, dest_col;

    printf("Welcome to minimalist Chess AI!\n");
    while (1) {
        print_board(&game);
        printf("Enter your move (e.g., e2 e4): ");
        fgets(input, sizeof(input), stdin);
        if (sscanf(input, "%c%d %c%d", &input[0], &src_row, &input[2], &dest_row) != 4) {
            printf("Invalid input. Please try again.\n");
            continue;
        }
        src_row = SIZE - src_row;
        dest_row = SIZE - dest_row;
        src_col = input[0] - 'a';
        dest_col = input[2] - 'a';

        if (is_valid_move(game.board[src_row][src_col], src_row, src_col, dest_row, dest_col)) {
            make_move(&game, src_row, src_col, dest_row, dest_col);
            printf("AI is moving...\n");
            ai_move(&game);
        } else {
            printf("Invalid move! Try again.\n");
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define POP3_PORT 110

int main(int argc, char **argv) {
    if (argc != 2) {
        printf("Usage: %s <email_address>\n", argv[0]);
        return 1;
    }

    char *email_address = argv[1];

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(POP3_PORT);
    server_addr.sin_addr.s_addr = inet_addr("127.0.0.1");

    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket()");
        return 1;
    }

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect()");
        return 1;
    }

    char *request = "USER\n";
    if (send(sock, request, strlen(request), 0) < 0) {
        perror("send()");
        return 1;
    }

    char response[1024];
    if (recv(sock, response, sizeof(response), 0) < 0) {
        perror("recv()");
        return 1;
    }

    if (strncmp(response, "+OK", 3) != 0) {
        printf("Invalid response: %s\n", response);
        return 1;
    }

    request = "PASS\n";
    if (send(sock, request, strlen(request), 0) < 0) {
        perror("send()");
        return 1;
    }

    if (recv(sock, response, sizeof(response), 0) < 0) {
        perror("recv()");
        return 1;
    }

    if (strncmp(response, "+OK", 3) != 0) {
        printf("Invalid response: %s\n", response);
        return 1;
    }

    request = "STAT\n";
    if (send(sock, request, strlen(request), 0) < 0) {
        perror("send()");
        return 1;
    }

    if (recv(sock, response, sizeof(response), 0) < 0) {
        perror("recv()");
        return 1;
    }

    if (strncmp(response, "+OK", 3) != 0) {
        printf("Invalid response: %s\n", response);
        return 1;
    }

    char *token = strtok(response, " ");
    if (token == NULL) {
        printf("Invalid response: %s\n", response);
        return 1;
    }

    int num_messages = atoi(token);
    printf("Number of messages: %d\n", num_messages);

    for (int i = 0; i < num_messages; i++) {
        request = "RETR\n";
        if (send(sock, request, strlen(request), 0) < 0) {
            perror("send()");
            return 1;
        }

        if (recv(sock, response, sizeof(response), 0) < 0) {
            perror("recv()");
            return 1;
        }

        if (strncmp(response, "+OK", 3) != 0) {
            printf("Invalid response: %s\n", response);
            return 1;
        }

        char *message = strtok(response, "\r\n");
        while (message != NULL) {
            printf("%s\n", message);
            message = strtok(NULL, "\r\n");
        }
    }

    request = "QUIT\n";
    if (send(sock, request, strlen(request), 0) < 0) {
        perror("send()");
        return 1;
    }

    if (recv(sock, response, sizeof(response), 0) < 0) {
        perror("recv()");
        return 1;
    }

    if (strncmp(response, "+OK", 3) != 0) {
        printf("Invalid response: %s\n", response);
        return 1;
    }

    close(sock);
    return 0;
}

