HRESULT DInput::Init(HWND hWnd)

{

	HRESULT hr;

	DWORD dwCoopFlags;

	dwCoopFlags = DISCL_FOREGROUND | DISCL_NOWINKEY;



	// Create a DInput object

	if (FAILED(hr = DirectInput8Create(GetModuleHandle(NULL), DIRECTINPUT_VERSION,

					    IID_IDirectInput8, (VOID* *)&g_pDI, NULL)))

	{

		MessageBox(0, "Direct Input Create Failed", 0, MB_ICONERROR);

		return(hr);

	}



	if (FAILED(hr = g_pDI->CreateDevice(GUID_SysKeyboard, &g_pKeyboard, NULL)))

	{

		MessageBox(0, "Couldn't access keyboard", 0, MB_ICONERROR);

		Free();

		return(hr);

	}



	g_pKeyboard->SetDataFormat(&c_dfDIKeyboard);

	g_pKeyboard->SetCooperativeLevel(hWnd, dwCoopFlags);

	g_pKeyboard->Acquire();



	return(S_OK);

}



void DInput::Free()

{

	if (g_pKeyboard)

	{

		g_pKeyboard->Unacquire();

		g_pKeyboard->Release();

		g_pKeyboard = 0;

	}



	if (g_pDI)

	{

		g_pDI->Release();

		g_pDI = 0;

	}

}



// Desc: Read the input device's state when in immediate mode and display it.

HRESULT DInput::Read()

{

	HRESULT hr;



	if (NULL == g_pKeyboard)

	{

		return(S_OK);

	}



	// Get the input's device state, and put the state in dims

	ZeroMemory(diks, sizeof(diks));

	hr = g_pKeyboard->GetDeviceState(sizeof(diks), diks);



//	for (int i=0; i<256; i++)

//		if (diks[i]) MessageBox(0,"DSFJDKSF|",0,0);

	if (FAILED(hr))

	{

		// DirectInput may be telling us that the input stream has been

		// interrupted.  We aren't tracking any state between polls, so

		// we don't have any special reset that needs to be done.

		// We just re-acquire and try again.



		// If input is lost then acquire and keep trying

		hr = g_pKeyboard->Acquire();



		while (hr == DIERR_INPUTLOST)

		{

			hr = g_pKeyboard->Acquire();

		}



		// hr may be DIERR_OTHERAPPHASPRIO or other errors.  This

		// may occur when the app is minimized or in the process of

		// switching, so just try again later

		return(S_OK);

	}



	return(S_OK);

}

// Linked List Operations Example Program
#include <stdio.h>
#include <stdlib.h>

// Linked list node structure
struct Node {
  int data;
  struct Node* next;
};

// Prototypes
void insertNode(struct Node** head, int data);
void deleteNode(struct Node** head, int data);
void printList(struct Node* head);

int main() {
  // Create a linked list
  struct Node* head = NULL;
  insertNode(&head, 1);
  insertNode(&head, 2);
  insertNode(&head, 3);
  insertNode(&head, 4);

  // Delete a node
  deleteNode(&head, 2);

  // Print the list
  printList(head);

  // Free the list
  freeList(head);

  return 0;
}

// Insert a node at the beginning of the list
void insertNode(struct Node** head, int data) {
  struct Node* newNode = (struct Node*) malloc(sizeof(struct Node));
  newNode->data = data;
  newNode->next = *head;
  *head = newNode;
}

// Delete a node from the list
void deleteNode(struct Node** head, int data) {
  struct Node* temp = *head;
  struct Node* prev = NULL;

  while (temp != NULL && temp->data != data) {
    prev = temp;
    temp = temp->next;
  }

  if (temp == NULL) {
    return;
  }

  if (prev == NULL) {
    *head = temp->next;
  } else {
    prev->next = temp->next;
  }

  free(temp);
}

// Print the list
void printList(struct Node* head) {
  struct Node* temp = head;
  while (temp != NULL) {
    printf("%d ", temp->data);
    temp = temp->next;
  }
  printf("\n");
}

// Free the list
void freeList(struct Node* head) {
  struct Node* temp = head;
  while (temp != NULL) {
    struct Node* next = temp->next;
    free(temp);
    temp = next;
  }
}

