#include <iostream>
# include <stdio.h>
#include <IntermediateTreePrinter.h>
#include <Tree.h>
#include <assert.h>

using namespace std;

std::string ident( "" );

void IntermediateTreeVisitor::Visit( const Tree::CONST& p )
{
	cout << "CONST(" << p.getInt() << ")";
}

void IntermediateTreeVisitor::Visit( const Tree::NAME& p )
{
	cout << "NAME(" << p.getLabel()->getLabelName() << ")";
}

void IntermediateTreeVisitor::Visit( const Tree::TEMP& p )
{
	cout << "TEMP(" << p.getTemp()->getId() << ")";
}

void IntermediateTreeVisitor::Visit( const Tree::BINOP& p )
{
	cout << "BINOP(";

	if( p.getBinOp() == Tree::BINOP::PLUS ) {
		cout << " + ";
	} else if( p.getBinOp() == Tree::BINOP::MINUS ) {
		cout << " - ";
	} else if( p.getBinOp() == Tree::BINOP::MUL ) {
		cout << " * ";
	} else if( p.getBinOp() == Tree::BINOP::DIV ) {
		cout << " / ";
	} else if( p.getBinOp() == Tree::BINOP::AND ) {
		cout << " AND ";
	} else if( p.getBinOp() == Tree::BINOP::OR ) {
		cout << " OR ";
	} else if( p.getBinOp() == Tree::BINOP::LSHIFT ) {
		cout << " LSHIFT ";
	} else if( p.getBinOp() == Tree::BINOP::RSHIFT ) {
		cout << " RSHIFT ";
	} else if( p.getBinOp() == Tree::BINOP::ARSHIFT ) {
		cout << " ARSHIFT ";
	} else if( p.getBinOp() == Tree::BINOP::XOR ) {
		cout << " XOR ";
	} else {
		assert( false );
	}

	cout << ", ";
	p.getLeftExp()->Accept( this );
	ident += "    ";
	cout << ", " << endl << ident;
	p.getRightExp()->Accept( this );
	cout << ")";
	ident = ident.substr( 0, ident.length() - 4 );
}

void IntermediateTreeVisitor::Visit( const Tree::MEM& p )
{
	cout << "MEM(";
	p.getExp()->Accept( this );
	cout << ")";
}

void IntermediateTreeVisitor::Visit( const Tree::CALL& p )
{
	cout << "CALL(";
	p.getFuncExp()->Accept( this );
	ident += "    ";
	cout << ", " << endl << ident;

	p.getArgsExpList()->Accept( this );
	cout << ")";
	ident = ident.substr( 0, ident.length() - 4 );
}

void IntermediateTreeVisitor::Visit( const Tree::ESEQ& p )
{
	cout << "ESEQ(";
	p.getStm()->Accept( this );
	ident += "    ";
	cout << ", " << endl << ident;
	p.getExp()->Accept( this );
	cout << ")";
	ident = ident.substr( 0, ident.length() - 4 );
}

void IntermediateTreeVisitor::Visit( const Tree::MOVE& p )
{
	cout << "MOVE(";
	p.getDst()->Accept( this );
	ident += "    ";
	cout << ", " << endl << ident;
	p.getSrc()->Accept( this );
	cout << ")";
	ident = ident.substr( 0, ident.length() - 4 );
}

void IntermediateTreeVisitor::Visit( const Tree::EXP& p )
{
	cout << "EXP(";
	p.getExp()->Accept( this );
	cout << ")";
}

void IntermediateTreeVisitor::Visit( const Tree::JUMP& p )
{
	cout << "JUMP(";
	const Temp::CLabelList* pwh( p.getTgList() );
	ident += "    ";
	while( pwh ) {
		cout << pwh->getTop()->getLabelName() << ", " << endl << ident;
		pwh = pwh->getTail();
	}
	//cout << p.getTarget()->getLabelName() << ")";
	cout << ")";
	ident = ident.substr( 0, ident.length() - 4 );
}

void IntermediateTreeVisitor::Visit( const Tree::CJUMP& p )
{
	cout << "CJUMP(";
	switch( p.getRelOp() ) {
		case Tree::CJUMP::EQ:
			cout << " == ";
			break;
		case Tree::CJUMP::NE:
			cout << " != ";
			break;
		case Tree::CJUMP::LT:
			cout << " < ";
			break;
		case Tree::CJUMP::GT:
			cout << " > ";
			break;
		case Tree::CJUMP::LE:
			cout << " <= ";
			break;
		case Tree::CJUMP::GE:
			cout << " >= ";
			break;
		case Tree::CJUMP::ULT:
			cout << " ULT ";
			break;
		case Tree::CJUMP::ULE:
			cout << " ULE ";
			break;
		case Tree::CJUMP::UGT:
			cout << " UGT ";
			break;
		case Tree::CJUMP::UGE:
			cout << " UGE ";
			break;
	}
	cout << ", ";
	p.getLeftExp()->Accept( this );
	ident += "    ";
	cout << ", " << endl << ident;
	p.getRightExp()->Accept( this );
	cout << ", " << endl << ident;
	cout << p.getTrueLabel()->getLabelName() << ", " << endl << ident
		<< p.getFalseLabel()->getLabelName() << ")";
	ident = ident.substr( 0, ident.length() - 4 );
}

void IntermediateTreeVisitor::Visit( const Tree::SEQ& p )
{
	cout << "SEQ(";
	p.getLeftStm()->Accept( this );
	ident += "    ";
	cout << ", " << endl << ident;
	p.getRightStm()->Accept( this );
	cout << ")";
	ident = ident.substr( 0, ident.length() - 4 );
}

void IntermediateTreeVisitor::Visit( const Tree::LABEL& p )
{
	cout << " " << p.getLabel()->getLabelName();
}

void IntermediateTreeVisitor::Visit( const Tree::ExpList& p )
{
	p.getTop()->Accept( this );
	if( p.getTail() != 0 ) {
		p.getTail()->Accept( this );
	}
}

void IntermediateTreeVisitor::Visit( const Tree::StmList& p )
{
	p.getTop()->Accept( this );
	if( p.getTail() != 0 ) {
		p.getTail()->Accept( this );
	}
}

#include<stdio.h>
#include<time.h>

/* This program performs benchmarking of matrix multiplication using three different algorithms:
simple, Strassen and recursive Strassen algorithm. */

#define MAX 1000      // Define maximum size of matrices
#define CUTOFF 100    // Cutoff size for recursive Strassen algorithm

double A[MAX][MAX], B[MAX][MAX], C[MAX][MAX];  // Matrices to be multiplied

// Simple matrix multiplication algorithm
void simpleMultiply(int n) 
{
    int i, j, k;
    for(i = 0; i < n; i++) 
    {
        for(j = 0; j < n; j++) 
        {
            C[i][j] = 0;
            for(k = 0; k < n; k++)
                C[i][j] += A[i][k] * B[k][j];
        }
    }
}

// Shift matrix by half in row and half in column
void shift(int n, double A[][MAX], double B[][MAX])
{
    int i, j;
    for(i = 0; i < n/2; i++)
        for(j = 0; j < n/2; j++)
            B[i][j] = A[i][j];
    for(i = 0; i < n/2; i++)
        for(j = 0; j < n/2; j++)
            B[i][j+n/2] = A[i][j+n/2];
    for(i = 0; i < n/2; i++)
        for(j = 0; j < n/2; j++)
            B[i+n/2][j] = A[i+n/2][j];
    for(i = 0; i < n/2; i++)
        for(j = 0; j < n/2; j++)
            B[i+n/2][j+n/2] = A[i+n/2][j+n/2];
}

// Strassen's matrix multiplication algorithm
void strassenMultiply(int n) 
{
    double A11[MAX][MAX], A12[MAX][MAX], A21[MAX][MAX], A22[MAX][MAX];
    double B11[MAX][MAX], B12[MAX][MAX], B21[MAX][MAX], B22[MAX][MAX];
    double C11[MAX][MAX], C12[MAX][MAX], C21[MAX][MAX], C22[MAX][MAX];
    double P1[MAX][MAX], P2[MAX][MAX], P3[MAX][MAX], P4[MAX][MAX], P5[MAX][MAX], P6[MAX][MAX], P7[MAX][MAX];
    double temp1[MAX][MAX], temp2[MAX][MAX];
    int i, j, size = n/2;

    // Base case
    if(n <= CUTOFF) 
    {
        simpleMultiply(n);
        return;
    }

    // Divide matrices into submatrices
    for(i = 0; i < size; i++) 
    {
        for(j = 0; j < size; j++) 
        {
            A11[i][j] = A[i][j];
            A12[i][j] = A[i][j + size];
            A21[i][j] = A[i + size][j];
            A22[i][j] = A[i + size][j + size];

            B11[i][j] = B[i][j];
            B12[i][j] = B[i][j + size];
            B21[i][j] = B[i + size][j];
            B22[i][j] = B[i + size][j + size];
        }
    }

    // Recursive calls to StrassenMultiply
    shift(size, A11, temp1);
    shift(size, B12, temp2);
    strassenMultiply(size);
    simpleMultiply(size);
    for(i = 0; i < size; i++)
        for(j = 0; j < size; j++)
            C12[i][j] = C[i][j];

    simpleMultiply(size);
    shift(size, B21, temp2);
    for(i = 0; i < size; i++)
        for(j = 0; j < size; j++)
            C21[i][j] = C[i][j];

    shift(size, A22, temp1);
    strassenMultiply(size);

    for(i = 0; i < size; i++)
        for(j = 0; j < size; j++)
            C22[i][j] = C[i][j];

    shift(size, A21, temp1);
    strassenMultiply(size);

    for(i = 0; i < size; i++)
        for(j = 0; j < size; j++) 
        {
            C21[i][j] += C[i][j];
            C22[i][j] += C[i][j];
        }

    shift(size, B11, temp2);
    strassenMultiply(size);

    for(i = 0; i < size; i++)
        for(j = 0; j < size; j++)
            C11[i][j] = C[i][j];

    shift(size, A12, temp1);
    strassenMultiply(size);

    for(i = 0; i < size; i++)
        for(j = 0; j < size; j++)
        {
            C11[i][j] += C[i][j];
            C12[i][j] -= C[i][j];
        }

    // Combine submatrices into result matrix
    for(i = 0; i < size; i++) 
    {
        for(j = 0; j < size; j++) 
        {
            C[i][j] = C11[i][j];
            C[i][j + size] = C12[i][j];
            C[i + size][j] = C21[i][j];
            C[i + size][j + size] = C22[i][j];
        }
    }
}

// Recursive Strassen's matrix multiplication algorithm
void recursiveStrassenMultiply(int n)
{
    double A11[MAX][MAX], A12[MAX][MAX], A21[MAX][MAX], A22[MAX][MAX];
    double B11[MAX][MAX], B12[MAX][MAX], B21[MAX][MAX], B22[MAX][MAX];
    double C11[MAX][MAX], C12[MAX][MAX], C21[MAX][MAX], C22[MAX][MAX];
    double P1[MAX][MAX], P2[MAX][MAX], P3[MAX][MAX], P4[MAX][MAX], P5[MAX][MAX], P6[MAX][MAX], P7[MAX][MAX];
    double temp1[MAX][MAX], temp2[MAX][MAX];
    int i, j, size = n/2;

    // Base case
    if(n <= CUTOFF)
    {
        simpleMultiply(n);
        return;
    }

    // Divide matrices into submatrices
    for(i = 0; i < size; i++)
    {
        for(j = 0; j < size; j++)
        {
            A11[i][j] = A[i][j];
            A12[i][j] = A[i][j + size];
            A21[i][j] = A[i + size][j];
            A22[i][j] = A[i + size][j + size];

            B11[i][j] = B[i][j];
            B12[i][j] = B[i][j + size];
            B21[i][j] = B[i + size][j];
            B22[i][j] = B[i + size][j + size];
        }
    }

    // Compute intermediate matrices
    for(i = 0; i < size; i++)
    {
        for(j = 0; j < size; j++)
        {
            temp1[i][j] = A11[i][j] + A22[i][j];
            temp2[i][j] = B11[i][j] + B22[i][j];
        }
    }
    recursiveStrassenMultiply(size);
    for(i = 0; i < size; i++)
        for(j = 0; j < size; j++)
            C11[i][j] = C[i][j];

    for(i = 0; i < size; i++)
    {
        for(j = 0; j < size; j++)
        {
            temp1[i][j] = A21[i][j] + A22[i][j];
        }
    }
    recursiveStrassenMultiply(size);
    for(i = 0; i < size; i++)
        for(j = 0; j < size; j++)
            C21[i][j] = C[i][j];

    for(i = 0; i < size; i++)
    {
        for(j = 0; j < size; j++)
        {
            temp2[i][j] = B12[i][j] - B22[i][j];
        }
    }
    recursiveStrassenMultiply(size);
    for(i = 0; i < size; i++)
        for(j = 0; j < size; j++)
            C12[i][j] = C[i][j];

    for(i = 0; i < size; i++)
    {
        for(j = 0; j < size; j++)
        {
            temp2[i][j] = B21[i][j] - B11[i][j];
        }
    }
    recursiveStrassenMultiply(size);
    for(i = 0; i < size; i++)
        for(j = 0; j < size; j++)
            C22[i][j] = C[i][j];

    for(i = 0; i < size; i++)
    {
        for(j = 0; j < size; j++)
        {
            temp1[i][j] = A11[i][j] + A12[i][j];
        }
    }
    recursiveStrassenMultiply(size);
    for(i = 0; i < size; i++)
        for(j = 0; j < size; j++)
        {
            C11[i][j] = C[i][j] + C12[i][j];
            C22[i][j] += C[i][j];
        }

    for(i = 0; i < size; i++)
    {
        for(j = 0; j < size; j++)
        {
            temp1[i][j] = A21[i][j] - A11[i][j];
            temp2[i][j] = B11[i][j] + B12[i][j];
        }
    }
    recursiveStrassenMultiply(size);
    for(i = 0; i < size; i++)
        for(j = 0; j < size; j++)
        {
            C21[i][j] += C[i][j];
            C22[i][j] += C[i][j];
        }

    for(i = 0; i < size; i++)
    {
        for(j = 0; j < size; j++)
        {
            temp1[i][j] = A12[i][j] - A22[i][j];
            temp2[i][j] = B21[i][j] + B22[i][j];
        }
    }
    recursiveStrassenMultiply(size);
    for(i = 0; i < size; i++)
        for(j = 0; j < size; j++)
        {
            C11[i][j] += C[i][j];
        }

    for(i = 0; i < size; i++)
    {
        for(j = 0; j < size; j++)
        {
            temp1[i][j] = A11[i][j] - A21[i][j];
            temp2[i][j] = B11[i][j] + B22[i][j];
        }
    }
    recursiveStrassenMultiply(size);
    for(i = 0; i < size; i++)
        for(j = 0; j < size; j++)
        {
            C12[i][j] += C[i][j];
        }

    // Combine submatrices into result matrix
    for(i = 0; i < size; i++)
    {
        for(j = 0; j < size; j++)
        {
            C[i][j] = C11[i][j];
            C[i][j + size] = C12[i][j];
            C[i + size][j] = C21[i][j];
            C[i + size][j + size] = C22[i][j];
        }
    }
}

int main()
{
    int n, i, j;
    clock_t start, end;
    double time;

    printf("Enter size of matrices (maximum %d): ", MAX);  // User input
    scanf("%d", &n);

    if(n < 1 || n > MAX)  // Error handling
    {
        printf("Invalid input.\n");
        return 0;
    }

    // Initialize matrices with random numbers
    for(i = 0; i < n; i++) 
    {
        for(j = 0; j < n; j++) 
        {
            A[i][j] = rand() % 10;
            B[i][j] = rand() % 10;
        }
    }

    // Benchmarking simple multiplication algorithm
    printf("Performing benchmarking of simple multiplication algorithm...\n");
    start = clock();
    simpleMultiply(n);
    end = clock();
    time = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time taken: %lf seconds.\n", time);

    // Benchmarking Strassen's multiplication algorithm
    printf("\nPerforming benchmarking of Strassen multiplication algorithm...\n");
    start = clock();
    strassenMultiply(n);
    end = clock();
    time = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time taken: %lf seconds.\n", time);

    // Benchmarking recursive Strassen's multiplication algorithm
    printf("\nPerforming benchmarking of recursive Strassen multiplication algorithm...\n");
    start = clock();
    recursiveStrassenMultiply(n);
    end = clock();
    time = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time taken: %lf seconds.\n", time);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>

#define PORT 8888

int main() {
    int sockfd, n;
    struct sockaddr_in serv_addr, cli_addr;

    if ( (sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0 ) {
        perror("ERROR opening socket");
        exit(1);
    }

    bzero((char *)&serv_addr, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    if ( bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0 ) {
        perror("ERROR on binding");
        exit(1);
    }

    listen(sockfd, 5);

    while (1) {
        if ( (n = accept(sockfd, (struct sockaddr *)&cli_addr, (socklen_t *)&serv_addr)) < 0 ) {
            perror("ERROR on accept");
            exit(1);
        }
        printf("Client connected: %s\n", inet_ntoa(cli_addr.sin_addr));
        char buf[1024];
        bzero(buf, 1024);
        while (1) {
            if ( (n = recv(sockfd, buf, 1024, 0)) < 0 ) {
                perror("ERROR receiving data");
                break;
            }
            if ( n == 0 ) {
                printf("Client disconnected\n");
                break;
            }
            printf("Received: %s\n", buf);
            send(sockfd, buf, n, 0);
        }
        close(sockfd);
        break;
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_BUDGET_ITEMS 100

typedef struct {
    char name[50];
    float amount;
} budget_item_t;

budget_item_t budget[MAX_BUDGET_ITEMS];
int num_budget_items = 0;

void add_budget_item() {
    if (num_budget_items >= MAX_BUDGET_ITEMS) {
        printf("Error: Maximum number of budget items reached.\n");
        return;
    }

    printf("Enter budget item name: ");
    scanf("%s", budget[num_budget_items].name);

    printf("Enter budget item amount: ");
    scanf("%f", &budget[num_budget_items].amount);

    num_budget_items++;
}

void display_budget() {
    printf("\nBudget:\n");
    printf("----------------------------------------------------\n");
    printf("Name       | Amount\n");
    printf("----------------------------------------------------\n");

    for (int i = 0; i < num_budget_items; i++) {
        printf("%-40s $%.2f\n", budget[i].name, budget[i].amount);
    }

    printf("----------------------------------------------------\n");
}

void main() {
    int choice;

    do {
        printf("\nPersonal Finance Planner\n");
        printf("1. Add budget item\n");
        printf("2. Display budget\n");
        printf("3. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
        case 1:
            add_budget_item();
            break;
        case 2:
            display_budget();
            break;
        case 3:
            printf("Exiting program...\n");
            break;
        default:
            printf("Invalid choice. Please try again.\n");
        }
    } while (choice!= 3);

    return 0;
}

