    Adenine = 0,
    Thymine,
    Guanine,
    Cytosine
} base_t;

void generate_sequence(base_t *seq, size_t length) {
    size_t i;
    srand(time(NULL));

    for (i = 0; i < length; i++) {
        seq[i] = (base_t)(rand() % NUM_BASES);
    }
}

void print_sequence(const base_t *seq, size_t length) {
    size_t i;

    for (i = 0; i < length; i++) {
        switch (seq[i]) {
            case Adenine:
                printf("A");
                break;
            case Thymine:
                printf("T");
                break;
            case Guanine:
                printf("G");
                break;
            case Cytosine:
                printf("C");
                break;
        }
    }

    printf("\n");
}

