#undef G_LOG_DOMAIN
#define G_LOG_DOMAIN "pcm_volume"

static void
pcm_volume_change_8(int8_t *buffer, const int8_t *end, int volume)
{
	while (buffer < end) {
		int32_t sample = *buffer;

		sample = (sample * volume + pcm_volume_dither() +
			  PCM_VOLUME_1 / 2)
			/ PCM_VOLUME_1;

		*buffer++ = pcm_range(sample, 8);
	}
}

static void
pcm_volume_change_16(int16_t *buffer, const int16_t *end, int volume)
{
	while (buffer < end) {
		int32_t sample = *buffer;

		sample = (sample * volume + pcm_volume_dither() +
			  PCM_VOLUME_1 / 2)
			/ PCM_VOLUME_1;

		*buffer++ = pcm_range(sample, 16);
	}
}

#ifdef __i386__
/**
 * Optimized volume function for i386.  Use the EDX:EAX 2*32 bit
 * multiplication result instead of emulating 64 bit multiplication.
 */
static inline int32_t
pcm_volume_sample_24(int32_t sample, int32_t volume, G_GNUC_UNUSED int32_t dither)
{
	int32_t result;

	asm(/* edx:eax = sample * volume */
	    "imul %2\n"

	    /* "add %3, %1\n"  dithering disabled for now, because we
	       have no overflow check - is dithering really important
	       here? */

	    /* eax = edx:eax / PCM_VOLUME_1 */
	    "sal $22, %%edx\n"
	    "shr $10, %1\n"
	    "or %%edx, %1\n"

	    : "=a"(result)
	    : "0"(sample), "r"(volume) /* , "r"(dither) */
	    : "edx"
	    );

	return result;
}
#endif

static void
pcm_volume_change_24(int32_t *buffer, const int32_t *end, int volume)
{
	while (buffer < end) {
#ifdef __i386__
		/* assembly version for i386 */
		int32_t sample = *buffer;

		sample = pcm_volume_sample_24(sample, volume,
					      pcm_volume_dither());
#else
		/* portable version */
		int64_t sample = *buffer;

		sample = (sample * volume + pcm_volume_dither() +
			  PCM_VOLUME_1 / 2)
			/ PCM_VOLUME_1;
#endif
		*buffer++ = pcm_range(sample, 24);
	}
}

static void
pcm_volume_change_32(int32_t *buffer, const int32_t *end, int volume)
{
	while (buffer < end) {
#ifdef __i386__
		/* assembly version for i386 */
		int32_t sample = *buffer;

		*buffer++ = pcm_volume_sample_24(sample, volume, 0);
#else
		/* portable version */
		int64_t sample = *buffer;

		sample = (sample * volume + pcm_volume_dither() +
			  PCM_VOLUME_1 / 2)
			/ PCM_VOLUME_1;
		*buffer++ = pcm_range_64(sample, 32);
#endif
	}
}

static void
pcm_volume_change_float(float *buffer, const float *end, float volume)
{
	while (buffer < end) {
		float sample = *buffer;
		sample *= volume;
		*buffer++ = sample;
	}
}

bool
pcm_volume(void *buffer, size_t length,
	   enum sample_format format,
	   int volume)
{
	if (volume == PCM_VOLUME_1)
		return true;

	if (volume <= 0) {
		memset(buffer, 0, length);
		return true;
	}

	const void *end = pcm_end_pointer(buffer, length);
	switch (format) {
	case SAMPLE_FORMAT_UNDEFINED:
	case SAMPLE_FORMAT_S24:
	case SAMPLE_FORMAT_DSD:
	case SAMPLE_FORMAT_DSD_LSBFIRST:
		/* not implemented */
		return false;

	case SAMPLE_FORMAT_S8:
		pcm_volume_change_8(buffer, end, volume);
		return true;

	case SAMPLE_FORMAT_S16:
		pcm_volume_change_16(buffer, end, volume);
		return true;

	case SAMPLE_FORMAT_S24_P32:
		pcm_volume_change_24(buffer, end, volume);
		return true;

	case SAMPLE_FORMAT_S32:
		pcm_volume_change_32(buffer, end, volume);
		return true;

	case SAMPLE_FORMAT_FLOAT:
		pcm_volume_change_float(buffer, end,
					pcm_volume_to_float(volume));
		return true;
	}

	/* unreachable */
	assert(false);
	return false;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_WORDS 10000
#define WORD_LENGTH 50
#define DICTIONARY_SIZE 5000

typedef struct {
    char word[WORD_LENGTH];
} Word;

void load_dictionary(Word dictionary[DICTIONARY_SIZE]) {
    FILE *fp;
    int i = 0;

    fp = fopen("dictionary.txt", "r");

    if (fp == NULL) {
        printf("Error: Could not open dictionary file.\n");
        exit(1);
    }

    while (fscanf(fp, "%s", dictionary[i].word) != EOF) {
        i++;
    }

    fclose(fp);
}

int check_word(char *word, Word dictionary[DICTIONARY_SIZE]) {
    int i;

    for (i = 0; i < DICTIONARY_SIZE; i++) {
        if (strcasecmp(word, dictionary[i].word) == 0) {
            return 1;
        }
    }

    return 0;
}

void process_line(char line[1024], Word dictionary[DICTIONARY_SIZE]) {
    char word[WORD_LENGTH];
    char *token;
    int i, found;

    token = strtok(line, " .,\n");

    while (token != NULL) {
        strcpy(word, token);

        for (i = 0; i < strlen(word); i++) {
            word[i] = tolower(word[i]);
        }

        found = check_word(word, dictionary);

        if (!found) {
            printf("Error: %s is not a valid word.\n", word);
        }

        token = strtok(NULL, " .,\n");
    }
}

int main(int argc, char *argv[]) {
    Word dictionary[DICTIONARY_SIZE];
    char line[1024];

    if (argc != 2) {
        printf("Usage: %s <text_file>\n", argv[0]);
        return 1;
    }

    load_dictionary(dictionary);

    FILE *fp;

    fp = fopen(argv[1], "r");

    if (fp == NULL) {
        printf("Error: Could not open text file.\n");
        return 1;
    }

    while (fgets(line, sizeof(line), fp) != NULL) {
        process_line(line, dictionary);
    }

    fclose(fp);

    printf("Spelling check completed.\n");

    return 0;
}

