// Function to add room in the rooms array
void addRoom(struct Room rooms[], int *numberOfRooms) {
  printf("\nEnter room details:\n");
  printf("Name: ");
  scanf("%s", rooms[*numberOfRooms].name);
  printf("Floor: ");
  scanf("%d", &rooms[*numberOfRooms].floor);
  printf("Room Number: ");
  scanf("%d", &rooms[*numberOfRooms].roomNumber);
  printf("Beds: ");
  scanf("%d", &rooms[*numberOfRooms].beds);
  printf("Price per Day: ");
  scanf("%lf", &rooms[*numberOfRooms].price);
  printf("Availability(Yes/No): ");
  scanf("%s", rooms[*numberOfRooms].available);

  (*numberOfRooms)++;
}

// Function to remove room from the rooms array
void removeRoom(struct Room rooms[], int *numberOfRooms) {
  int roomNumber;
  printf("\nEnter the room number to be removed: ");
  scanf("%d", &roomNumber);

  for(int i = 0; i < *numberOfRooms; i++) {
    if(rooms[i].roomNumber == roomNumber) {
      for(int j = i; j < *numberOfRooms-1; j++) {
        rooms[j] = rooms[j+1];
      }
      (*numberOfRooms)--;
      printf("\nRoom with Room Number %d removed successfully.\n", roomNumber);
      return;
    }
  }

  printf("\nRoom with Room Number %d not found.\n", roomNumber);
}

// Function to display all the rooms in the rooms array
void displayRooms(struct Room rooms[], int *numberOfRooms) {
  printf("\nAll Rooms:\n");
  printf("S.No.\tRoom Name\tFloor\tRoom Number\tBeds\tPrice per Day\tAvailability\n");
  for(int i = 0; i < *numberOfRooms; i++) {
    printf("%d\t%s\t\t%d\t%d\t\t%d\t$%.2lf\t\t%s\n", i+1, rooms[i].name, rooms[i].floor, rooms[i].roomNumber, rooms[i].beds, rooms[i].price, rooms[i].available);
  }
}

// Function to search rooms based on availability
void searchRooms(struct Room rooms[], int *numberOfRooms, char *available) {
  int count = 0;
  printf("\nSearch Results:\n");
  printf("S.No.\tRoom Name\tFloor\tRoom Number\tBeds\tPrice per Day\tAvailability\n");
  for(int i = 0; i < *numberOfRooms; i++) {
    if(strcmp(rooms[i].available, available) == 0) {
      printf("%d\t%s\t\t%d\t%d\t\t%d\t$%.2lf\t\t%s\n", count+1, rooms[i].name, rooms[i].floor, rooms[i].roomNumber, rooms[i].beds, rooms[i].price, rooms[i].available);
      count++;
    }
  }
  if(count == 0) {
    printf("\nNo %s rooms available.\n", available);
  } else {
    printf("\n%d %s rooms available.\n", count, available);
  }
}

// Function to book a room
void bookRoom(struct Room rooms[], int *numberOfRooms) {
  int roomNumber;
  printf("\nEnter the room number to be booked: ");
  scanf("%d", &roomNumber);

  for(int i = 0; i < *numberOfRooms; i++) {
    if(rooms[i].roomNumber == roomNumber) {
      if(strcmp(rooms[i].available, "Yes") == 0) {
        strcpy(rooms[i].available, "No");
        printf("\nRoom with Room Number %d booked successfully.\n", roomNumber);
        return;
      } else {
        printf("\nRoom with Room Number %d is already booked.\n", roomNumber);
        return;
      }
    }
  }

  printf("\nRoom with Room Number %d not found.\n", roomNumber);
}

// Function to checkout a room
void checkoutRoom(struct Room rooms[], int *numberOfRooms) {
  int roomNumber;
  printf("\nEnter the room number to be checked out: ");
  scanf("%d", &roomNumber);

  for(int i = 0; i < *numberOfRooms; i++) {
    if(rooms[i].roomNumber == roomNumber) {
      if(strcmp(rooms[i].available, "No") == 0) {
        strcpy(rooms[i].available, "Yes");
        printf("\nRoom with Room Number %d checked out successfully.\n", roomNumber);
        return;
      } else {
        printf("\nRoom with Room Number %d is already available.\n", roomNumber);
        return;
      }
    }
  }

  printf("\nRoom with Room Number %d not found.\n", roomNumber);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char filename[50];
    char* data;
    int size;
    int ref_count;
} File;

File* open_file(const char* filename) {
    File* file = (File*)malloc(sizeof(File));
    if (file == NULL) {
        return NULL;
    }
    strncpy(file->filename, filename, sizeof(file->filename));
    file->data = NULL;
    file->size = 0;
    file->ref_count = 1;
    return file;
}

int close_file(File* file) {
    if (file == NULL) {
        return -1;
    }
    if (--file->ref_count == 0) {
        free(file->data);
        free(file);
        return 0;
    }
    return 0;
}

int write_file(File* file, const char* data, int size) {
    if (file == NULL || data == NULL) {
        return -1;
    }
    if (file->size + size > 1024 * 1024) {
        return -2;
    }
    if (file->data == NULL) {
        file->data = (char*)malloc(size);
        if (file->data == NULL) {
            return -3;
        }
    }
    strncpy(file->data + file->size, data, size);
    file->size += size;
    return 0;
}

int read_file(File* file, char* data, int size) {
    if (file == NULL || data == NULL) {
        return -1;
    }
    if (file->size < size) {
        return -2;
    }
    if (file->data == NULL) {
        return -3;
    }
    strncpy(data, file->data, size);
    return 0;
}

int main() {
    File* file1 = open_file("file1.txt");
    if (file1 == NULL) {
        printf("Error opening file1.txt\n");
        return 1;
    }
    write_file(file1, "Hello, world!", 13);
    close_file(file1);

    File* file2 = open_file("file2.txt");
    if (file2 == NULL) {
        printf("Error opening file2.txt\n");
        return 1;
    }
    read_file(file2, "data", 13);
    close_file(file2);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define ROW 3
#define COL 3

char board[ROW][COL];
int row,col;

void displayBoard(){
    printf("\n");
    for(int i=0; i<ROW; i++){
        for(int j=0; j<COL; j++){
            printf(" %c ", board[i][j]);   
            if(j < COL-1) printf("|");
        }
        printf("\n");
        if(i < ROW-1) printf("---|---|---\n");
    }
}

int checkWin(){
    for(int i=0; i<COL; i++){
        if(board[0][i] == board[1][i] && board[0][i] == board[2][i]) return 1;
    }
    for(int i=0; i<ROW; i++){
        if(board[i][0] == board[i][1] && board[i][0] == board[i][2]) return 1;
    }
    if(board[0][0] == board[1][1] && board[0][0] == board[2][2]) return 1;
    if(board[0][2] == board[1][1] && board[0][2] == board[2][0]) return 1;
    return 0;
}

int checkDraw(){
    for(int i=0; i<ROW; i++){
        for(int j=0; j<COL; j++){
            if(board[i][j] == ' ') return 0;   
        }
    }
    return 1;
}

void playerTurn(){
    int x,y,validInput;
    do{
        validInput = 1;
        printf("Enter row and col number to play (eg: 1 2) : ");
        scanf("%d %d", &x, &y);
        if(x < 1 || x > 3 || y < 1 || y > 3 || board[x-1][y-1] != ' ') {
            printf("Invalid input!\n");
            validInput = 0;
        } else {
            board[x-1][y-1] = 'X';
        }
    }while(validInput == 0);
}

void computerTurn(){
    int r,c;
    do{
        r = rand() % 3;
        c = rand() % 3;
    }while(board[r][c] != ' ');
    board[r][c] = 'O';
}

void startGame(){
    int currentPlayer, gameOver = 0;
    memset(board, ' ', sizeof(board));
    do{
        displayBoard();
        currentPlayer = currentPlayer == 0 ? 1 : 0;
        if(currentPlayer == 0) playerTurn();
        else computerTurn();
        if(checkWin()){
            displayBoard();
            printf("Player %d wins!\n", currentPlayer+1);
            gameOver = 1;
        } else if(checkDraw()){
            displayBoard();
            printf("Game draw!\n");
            gameOver = 1;
        }
    }while(gameOver == 0);
}

int main(){
    char choice;
    do{
        printf("Press any key to start the game...\n");
        scanf(" %c", &choice);
        startGame();
        printf("Play Again? (Y/N) : ");
        scanf(" %c", &choice);
    }while(choice == 'y' || choice == 'Y');
    return 0;
}

