#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define WIDTH  10
#define HEIGHT 10

typedef struct {
    int x, y;
} Point;

bool grid[HEIGHT][WIDTH];
const int DIRECTIONS[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

bool site_is_empty(int x, int y) {
    return grid[y][x] == false;
}

void print_grid() {
    for (int i = 0; i < HEIGHT; ++i) {
        for (int j = 0; j < WIDTH; ++j) {
            if (grid[i][j]) printf("Site %d,%d is occupied\n", j, i);
            else printf("Site %d,%d is empty\n", j, i);
        }
        printf("\n");
    }
}

bool percolate(Point origin) {
    grid[origin.y][origin.x] = true;
    int num_neighbors = 0;

    for (int i = 0; i < 4; ++i) {
        int new_x = origin.x + DIRECTIONS[i][0];
        int new_y = origin.y + DIRECTIONS[i][1];

        if (new_x >= 0 && new_x < WIDTH && new_y >= 0 && new_y < HEIGHT && site_is_empty(new_x, new_y)) {
            if (percolate((Point){new_x, new_y})) return true;
            num_neighbors++;
        }
    }

    return num_neighbors >= 1;
}

int main() {
    srand(time(NULL));

    for (int i = 0; i < HEIGHT; ++i) {
        for (int j = 0; j < WIDTH; ++j) {
            grid[i][j] = site_is_empty(j, i) ? rand() % 2 : false;
        }
    }

    Point origin = {rand() % WIDTH, rand() % HEIGHT};

    if (percolate(origin)) {
        printf("Percolation occurred at site %d,%d\n", origin.x, origin.y);
    } else {
        printf("Percolation did NOT occur at site %d,%d\n", origin.x, origin.y);
    }

    print_grid();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <ctype.h>

int main() {
    printf("Welcome to the Typing Speed Test. In this test, you need to type out a Sherlock Holmes story as fast as you can without making any errors.\n");
    printf("\nThe story you need to type is:\n\n");

    //Sherlock Holmes story
    char sherlock[] = "It was in the year ‘95 that a combination of events, into which I need not enter, caused Mr. Sherlock Holmes and myself to spend some weeks in one of our great university towns, and it was during this time that the small but instructive adventure which I am about to relate befell us. It will be obvious that any details which would help the reader to exactly identify the college or the criminal would be injudicious and offensive. So painful a scandal may well be allowed to die out. With due discretion, however, it might be communicated to the proper authorities, and smoked out, so to speak, for the benefit of the world.";

    printf("%s\n", sherlock); //print the story for the user to read

    printf("\nWhen you are ready, start typing the story in the box below. Please make sure that you do not make any errors.\n\n"); 

    //set up variables
    int wrong = 0;
    int correct = 0;
    int i = 0;
    char player_input[1024];

    //start timer
    double time_spent = 0.0;
    clock_t begin = clock();

    //get player input
    fgets(player_input, 1024, stdin);

    //remove newline from input
    player_input[strcspn(player_input, "\n")] = 0;

    //loop through each character of input and compare to story
    while (player_input[i] != '\0') {
        if (player_input[i] == sherlock[i]) {
            correct++;
        } else {
            wrong++;
        }
        i++;
    }

    //calculate accuracy
    double accuracy = (double)correct / (double)(correct+wrong) * 100;

    //stop timer and calculate time taken
    clock_t end = clock();
    time_spent += (double)(end - begin) / CLOCKS_PER_SEC;

    //print results
    printf("\nYou took %.2lf seconds to type the story.\n", time_spent);
    printf("You made %d errors.\n", wrong);
    printf("Your accuracy was %.2lf%%.\n", accuracy);

    //determine WPM
    double wpm = (double)(strlen(player_input) / 5) / (time_spent / 60);
    printf("Your typing speed was %.2lf words per minute.\n", wpm);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CLIENT_CONNECTIONS 10
#define BUFFER_SIZE 1024

int main(int argc, char *argv[]) {
  int sock_fd, client_fd;
  struct sockaddr_in server, client;
  socklen_t client_len = sizeof(client);
  char buffer[BUFFER_SIZE];
  int num_clients = 0;

  // Create a server socket
  sock_fd = socket(AF_INET, SOCK_STREAM, 0);
  if (sock_fd == -1) {
    perror("socket creation failed");
    exit(EXIT_FAILURE);
  }

  // Set address and port number for the server
  server.sin_family = AF_INET;
  server.sin_addr.s_addr = INADDR_ANY;
  server.sin_port = htons(8080);

  // Bind the server socket to the address and port
  if (bind(sock_fd, (struct sockaddr *)&server, sizeof(server)) < 0) {
    perror("binding failed");
    exit(EXIT_FAILURE);
  }

  // Listen for incoming connections
  if (listen(sock_fd, MAX_CLIENT_CONNECTIONS) < 0) {
    perror("listening failed");
    exit(EXIT_FAILURE);
  }

  printf("Server listening on port %d...\n", server.sin_port);

  while (1) {
    // Accept an incoming connection
    if ((client_fd = accept(sock_fd, (struct sockaddr *)&client, &client_len)) < 0) {
      perror("accept failed");
      continue;
    }

    // Print the client address and port
    printf("Client connected from %s port %d...\n",
           inet_ntoa(client.sin_addr), ntohs(client.sin_port));

    // Read data from the client
    read(client_fd, buffer, BUFFER_SIZE);
    printf("Received message from client: %s\n", buffer);

    // Send a response back to the client
    char *message = "Hello, client!";
    send(client_fd, message, strlen(message), 0);

    // Close the client socket
    close(client_fd);

    num_clients++;
    if (num_clients >= MAX_CLIENT_CONNECTIONS) {
      break;
    }
  }

  // Close the server socket
  close(sock_fd);

  return 0;
}

