}

#include <stdio.h>

// Function to display the bits of a number
void displayBits(unsigned int n) {
    for (int i = sizeof(n) * 8 - 1; i >= 0; i--) {
        printf("%d", (n >> i) & 1);
        if (i % 4 == 0) printf(" "); // Adding space for better readability
    }
    printf("\n");
}

// Function to perform and display bitwise operations
void bitwiseOperations(unsigned int a, unsigned int b) {
    printf("Let's express our gratitude through bitwise operations!\n");
    printf("First number (a): %u\n", a);
    printf("Second number (b): %u\n", b);

    printf("\nBinary representation:\n");
    printf("a in binary: ");
    displayBits(a);
    printf("b in binary: ");
    displayBits(b);

    // Bitwise AND
    unsigned int andResult = a & b;
    printf("\nBitwise AND (a & b): %u\n", andResult);
    printf("Binary result: ");
    displayBits(andResult);

    // Bitwise OR
    unsigned int orResult = a | b;
    printf("\nBitwise OR (a | b): %u\n", orResult);
    printf("Binary result: ");
    displayBits(orResult);

    // Bitwise XOR
    unsigned int xorResult = a ^ b;
    printf("\nBitwise XOR (a ^ b): %u\n", xorResult);
    printf("Binary result: ");
    displayBits(xorResult);

    // Bitwise NOT on a
    unsigned int notResultA = ~a;
    printf("\nBitwise NOT (~a): %u\n", notResultA);
    printf("Binary result: ");
    displayBits(notResultA);

    // Bitwise NOT on b
    unsigned int notResultB = ~b;
    printf("\nBitwise NOT (~b): %u\n", notResultB);
    printf("Binary result: ");
    displayBits(notResultB);

    // Left shift
    unsigned int leftShiftA = a << 1;
    printf("\nLeft shift a (a << 1): %u\n", leftShiftA);
    printf("Binary result: ");
    displayBits(leftShiftA);

    // Right shift
    unsigned int rightShiftA = a >> 1;
    printf("\nRight shift a (a >> 1): %u\n", rightShiftA);
    printf("Binary result: ");
    displayBits(rightShiftA);

    // Grateful message
    printf("\nThank You for exploring the world of bitwise operations with us!\n");
    printf("Your willingness to learn brings joy to this endeavor.\n");
    printf("May your coding adventures be fruitful and fulfilling!\n");
}

int main() {
    unsigned int num1 = 29; // 0001 1101 in binary
    unsigned int num2 = 15; // 0000 1111 in binary

    bitwiseOperations(num1, num2);

    return 0;
}

