    printf("Choose the type of unit:\n");
    printf("%d. Length\n", LENGTH);
    printf("%d. Weight\n", WEIGHT);
    printf("%d. Temperature\n", TEMPERATURE);

    scanf("%d", &choice);

    switch(choice)
    {
        case LENGTH:
            printf("Choose the input unit:\n");
            printf("%d. Inch\n", INCH);
            printf("%d. Foot\n", FOOT);
            printf("%d. Yard\n", YARD);
            printf("%d. Mile\n", MILE);

            scanf("%d", &input_unit);

            printf("Choose the output unit:\n");
            printf("%d. Inch\n", INCH);
            printf("%d. Foot\n", FOOT);
            printf("%d. Yard\n", YARD);
            printf("%d. Mile\n", MILE);

            scanf("%d", &output_unit);

            printf("Enter the value to be converted:\n");
            scanf("%f", &value);

            result = convert_length(input_unit, output_unit, value);

            printf("%.2f %s = %.2f %s\n", value,
                   (input_unit == INCH) ? "inches" :
                   (input_unit == FOOT) ? "feet" :
                   (input_unit == YARD) ? "yards" :
                   "miles",
                   result,
                   (output_unit == INCH) ? "inches" :
                   (output_unit == FOOT) ? "feet" :
                   (output_unit == YARD) ? "yards" :
                   "miles");
            break;

        case WEIGHT:
            printf("Choose the input unit:\n");
            printf("%d. Ounce\n", OUNCE);
            printf("%d. Pound\n", POUND);
            printf("%d. Tonne\n", TONNE);

            scanf("%d", &input_unit);

            printf("Choose the output unit:\n");
            printf("%d. Ounce\n", OUNCE);
            printf("%d. Pound\n", POUND);
            printf("%d. Tonne\n", TONNE);

            scanf("%d", &output_unit);

            printf("Enter the value to be converted:\n");
            scanf("%f", &value);

            result = convert_weight(input_unit, output_unit, value);

            printf("%.2f %s = %.2f %s\n", value,
                   (input_unit == OUNCE) ? "ounces" :
                   (input_unit == POUND) ? "pounds" :
                   "tonnes",
                   result,
                   (output_unit == OUNCE) ? "ounces" :
                   (output_unit == POUND) ? "pounds" :
                   "tonnes");
            break;

        case TEMPERATURE:
            printf("Choose the input unit:\n");
            printf("%d. Fahrenheit\n", FAHRENHEIT);
            printf("%d. Celsius\n", CELSIUS);

            scanf("%d", &input_unit);

            printf("Choose the output unit:\n");
            printf("%d. Fahrenheit\n", FAHRENHEIT);
            printf("%d. Celsius\n", CELSIUS);

            scanf("%d", &output_unit);

            printf("Enter the value to be converted:\n");
            scanf("%f", &value);

            result = convert_temperature(input_unit, output_unit, value);

            printf("%.2f %s = %.2f %s\n", value,
                   (input_unit == FAHRENHEIT) ? "Fahrenheit" :
                   "Celsius",
                   result,
                   (output_unit == FAHRENHEIT) ? "Fahrenheit" :
                   "Celsius");
            break;

        default:
            printf("Invalid choice\n");
            break;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

void print_board(char board[3][3]) {
    for(int i = 0; i < 3; i++) {
        for(int j = 0; j < 3; j++) {
            printf(" %c ", board[i][j]);
        }
        printf("\n");
    }
}

int check_winner(char board[3][3]) {
    for(int i = 0; i < 3; i++) {
        if(board[i][0] == board[i][1] && board[i][1] == board[i][2]) {
            return 1;
        }
        if(board[0][i] == board[1][i] && board[1][i] == board[2][i]) {
            return 1;
        }
    }
    if(board[0][0] == board[1][1] && board[1][1] == board[2][2]) {
        return 1;
    }
    if(board[0][2] == board[1][1] && board[1][1] == board[2][0]) {
        return 1;
    }
    return 0;
}

int main() {
    srand(time(NULL));
    char board[3][3] = {{'1', '2', '3'}, {'4', '5', '6'}, {'7', '8', '9'}};
    int player = 1;
    int choice;
    while(1) {
        system("clear");
        print_board(board);
        printf("\nPlayer %d's turn\n", player);
        printf("Enter your choice: ");
        scanf("%d", &choice);
        if(choice < 1 || choice > 9) {
            printf("Invalid choice. Skipping turn.\n");
            continue;
        }
        int row = (choice-1)/3;
        int col = (choice-1)%3;
        if(board[row][col]!= 'X' && board[row][col]!= 'O') {
            board[row][col] = (player == 1)? 'X' : 'O';
            player = (player == 1)? 2 : 1;
        } else {
            printf("Invalid choice. Skipping turn.\n");
        }
        if(check_winner(board)) {
            printf("\nPlayer %d wins!\n", player);
            break;
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <stdint.h>

typedef uint8_t byte;

void DecimalToHex(byte *input, size_t length) {
    char output[32];
    int index = 0;

    for (size_t i = 0; i < length; ++i) {
        input[i] = toupper((byte)input[i]);

        if (index > 27) {
            printf("Error: Output buffer is too small.\n");
            exit(EXIT_FAILURE);
        }

        if (input[i] < 10) {
            output[index++] = '0' + input[i];
            continue;
        }

        output[index++] = 'A' + (input[i] - 10);
    }

    output[index] = '\0';
    printf("%s\n", output);
}

void HexToDecimal(byte *input, size_t length) {
    int decimal = 0;
    size_t index = 0;

    for (; length > 0; --length) {
        if (isdigit(input[length])) {
            decimal += (input[length] - '0') * (int)pow(16, index);
        } else if (isalpha(input[length])) {
            decimal += (input[length] - 'A' + 10) * (int)pow(16, index);
        } else {
            printf("Error: Invalid character found in hexadecimal string.\n");
            exit(EXIT_FAILURE);
        }

        ++index;
    }

    printf("%d\n", decimal);
}

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("Usage: %s [convert] [number]\n"
               "       convert: d for decimal to hex, h for hex to decimal\n", argv[0]);
        return EXIT_FAILURE;
    }

    byte mode = argv[1][0];
    byte *number_str = argv[2];
    size_t number_length = strlen(number_str);

    byte *number = malloc(number_length + 1);

    if (mode == 'd') {
        for (size_t i = 0; i < number_length; ++i) {
            number[i] = number_str[i];
        }

        DecimalToHex(number, number_length);
    } else if (mode == 'h') {
        for (size_t i = 0; i < number_length; ++i) {
            number[i] = toupper((byte)number_str[i]);
        }

        HexToDecimal(number, number_length);

        free(number);
    } else {
        printf("Error: Invalid conversion mode.\n");
        return EXIT_FAILURE;
    }

    free(number);
    return EXIT_SUCCESS;
}

