#include "it/mat.h"
#include "it/io.h"
#include "it/distance.h"
#include <stdio.h>
#include <math.h>

/* X = x + d with proper bound checking and mirroring */
#define mirror_add(X, x, d, min, max) do {	\
    (X) = (x) + (d);				\
    if((X) < (min) || (X) >= (max))		\
      (X) = (x) - (d);				\
} while(0)

/* split an image into two laplacian pyramid bands */
void laplacian_pyramid_split(mat image, /* input band                 */
			     mat low,   /* low-frequency band         */
			     mat high,  /* high-frequency band        */
			     vec H0,    /* symmetric analysis  filter */
			     vec G0)    /* symmetric synthesis filter */
{
  int x, y;
  int w, h;
  idx_t dx, dy;
  idx_t wf, hf;
  idx_t wl, hl;
  int px, py;
  int X, Y;

  w = mat_width(image);
  h = mat_height(image);
  wl = (w + 1) / 2;
  hl = (h + 1) / 2;

  assert(mat_width(high)  == w);
  assert(mat_height(high) == h);
  assert(mat_width(low)  == wl);
  assert(mat_height(low) == hl);

  wf = hf = vec_length(H0);
  px = wf / 2;
  py = hf / 2;

  for(x = 0; x < wl; x++) {
    for(y = 0; y < hl; y++) {

      /* filter around position x,y */
      low[y][x] = 0;
      for(dx = -px; dx < wf-px; dx++) {
	for(dy = -py; dy < hf-py; dy++) {
	  /* compute the input sample location */
	  mirror_add(X, 2*x, dx, 0, w);
	  mirror_add(Y, 2*y, dy, 0, h);

	  low[y][x] += H0[dy+py] * H0[dx+px] * image[Y][X];
	}
      }

    }
  }

  wf = hf = vec_length(G0);
  px = wf / 2;
  py = hf / 2;

  for(x = 0; x < w; x++) {
    for(y = 0; y < h; y++) {

      /* filter around position x,y */
      high[y][x] = image[y][x];
      for(dx = -px; dx < wf-px; dx++) {
	for(dy = -py; dy < hf-py; dy++) {
	  /* compute the input sample location */
	  mirror_add(X, x, dx, 0, w);
	  mirror_add(Y, y, dy, 0, h);

	  if(!(X & 1) && !(Y & 1))
	    high[y][x] -= G0[dy+py] * G0[dx+px] * low[Y/2][X/2];
	}
      }

    }
  }
}


/* merge two laplacian pyramid bands into an image */
void laplacian_pyramid_merge(mat image, /* output band                */
			     mat low,   /* low-frequency band         */
			     mat high,  /* high-frequency band        */
			     vec H0,    /* symmetric analysis  filter */
			     vec G0)    /* symmetric synthesis filter */
{
  int x, y;
  int w, h;
  idx_t dx, dy;
  idx_t wf, hf;
  idx_t wl, hl;
  int px, py;
  int X, Y;

  w = mat_width(image);
  h = mat_height(image);
  wl = (w + 1) / 2;
  hl = (h + 1) / 2;

  assert(mat_width(high)  == w);
  assert(mat_height(high) == h);
  assert(mat_width(low)  == wl);
  assert(mat_height(low) == hl);

/* use pseudo inverse reconstruction */
/* this assumes the filters are orthogonal */
/* the 9/7 are close enough to orthogonality for this to work quite well */
#define DUAL
#ifdef DUAL
  wf = hf = vec_length(H0);
  px = wf / 2;
  py = hf / 2;

  for(x = 0; x < wl; x++) {
    for(y = 0; y < hl; y++) {

      /* filter around position x,y */
      for(dx = -px; dx < wf-px; dx++) {
	for(dy = -py; dy < hf-py; dy++) {
	  /* compute the input sample location */
	  mirror_add(X, 2*x, dx, 0, w);
	  mirror_add(Y, 2*y, dy, 0, h);

	  low[y][x] -= H0[dy+py] * H0[dx+px] * high[Y][X];
	}
      }

    }
  }
#endif

  wf = hf = vec_length(G0);
  px = wf / 2;
  py = hf / 2;

  for(x = 0; x < w; x++) {
    for(y = 0; y < h; y++) {

      /* filter around position x,y */
      image[y][x] = high[y][x];
      for(dx = -px; dx < wf-px; dx++) {
	for(dy = -py; dy < hf-py; dy++) {
	  /* compute the input sample location */
	  mirror_add(X, x, dx, 0, w);
	  mirror_add(Y, y, dy, 0, h);

	  if(!(X & 1) && !(Y & 1))
	    image[y][x] += G0[dy+py] * G0[dx+px] * low[Y/2][X/2];
	}
      }

    }
  }
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_DEPTH 5
#define MIN_TEMP 0
#define MAX_TEMP 50

struct weather {
    int temp;
    int humidity;
    int pressure;
    struct weather *next;
};

void weather_simulate(struct weather *root) {
    // Simulate one day
    for (int i = 0; i < 24; i++) {
        // Update temperature
        root->temp += (rand() % 5) - 2;
        if (root->temp < MIN_TEMP) {
            root->temp = MIN_TEMP;
        } else if (root->temp > MAX_TEMP) {
            root->temp = MAX_TEMP;
        }

        // Update humidity
        root->humidity += (rand() % 5) - 2;
        if (root->humidity < 0) {
            root->humidity = 0;
        } else if (root->humidity > 100) {
            root->humidity = 100;
        }

        // Update pressure
        root->pressure += (rand() % 5) - 2;
        if (root->pressure < 0) {
            root->pressure = 0;
        } else if (root->pressure > 1000) {
            root->pressure = 1000;
        }

        // Recursively simulate child nodes
        if (root->next != NULL) {
            weather_simulate(root->next);
        }
    }
}

int main() {
    struct weather *root = NULL;

    // Create the root node
    root = malloc(sizeof(struct weather));
    root->temp = 20;
    root->humidity = 50;
    root->pressure = 500;
    root->next = NULL;

    // Create child nodes
    struct weather *child1 = malloc(sizeof(struct weather));
    child1->temp = 15;
    child1->humidity = 70;
    child1->pressure = 400;
    child1->next = NULL;

    struct weather *child2 = malloc(sizeof(struct weather));
    child2->temp = 25;
    child2->humidity = 30;
    child2->pressure = 600;
    child2->next = NULL;

    // Simulate the weather
    weather_simulate(root);

    // Print the final weather conditions
    printf("Final weather conditions:\n");
    printf("Temperature: %d\n", root->temp);
    printf("Humidity: %d\n", root->humidity);
    printf("Pressure: %d\n", root->pressure);

    return 0;
}

