#include "TextSearch.h"
#include "StringUtils.h"

CTextSearch::CTextSearch(const std::string &strSearchTerms, bool bCaseSensitive /* = false */, TextSearchDefault defaultSearchMode /* = SEARCH_DEFAULT_OR */)
{
  m_bCaseSensitive = bCaseSensitive;
  ExtractSearchTerms(strSearchTerms, defaultSearchMode);
}

bool CTextSearch::IsValid(void) const
{
  return m_AND.size() > 0 || m_OR.size() > 0 || m_NOT.size() > 0;
}

bool CTextSearch::Search(const std::string &strHaystack) const
{
  if (strHaystack.empty() || !IsValid())
    return false;

  std::string strSearch(strHaystack);
  if (!m_bCaseSensitive)
    StringUtils::ToLower(strSearch);

  /* check whether any of the NOT terms matches and return false if there's a match */
  for (unsigned int iNotPtr = 0; iNotPtr < m_NOT.size(); iNotPtr++)
  {
    if (strSearch.find(m_NOT.at(iNotPtr)) != std::string::npos)
      return false;
  }

  /* check whether at least one of the OR terms matches and return false if there's no match found */
  bool bFound(m_OR.empty());
  for (unsigned int iOrPtr = 0; iOrPtr < m_OR.size(); iOrPtr++)
  {
    if (strSearch.find(m_OR.at(iOrPtr)) != std::string::npos)
    {
      bFound = true;
      break;
    }
  }
  if (!bFound)
    return false;

  /* check whether all of the AND terms match and return false if one of them wasn't found */
  for (unsigned int iAndPtr = 0; iAndPtr < m_AND.size(); iAndPtr++)
  {
    if (strSearch.find(m_AND[iAndPtr]) == std::string::npos)
      return false;
  }

  /* all ok, return true */
  return true;
}

void CTextSearch::GetAndCutNextTerm(std::string &strSearchTerm, std::string &strNextTerm)
{
  std::string strFindNext(" ");

  if (StringUtils::EndsWith(strSearchTerm, "\""))
  {
    strSearchTerm.erase(0, 1);
    strFindNext = "\"";
  }

  size_t iNextPos = strSearchTerm.find(strFindNext);
  if (iNextPos != std::string::npos)
  {
    strNextTerm = strSearchTerm.substr(0, iNextPos);
    strSearchTerm.erase(0, iNextPos + 1);
  }
  else
  {
    strNextTerm = strSearchTerm;
    strSearchTerm.clear();
  }
}

void CTextSearch::ExtractSearchTerms(const std::string &strSearchTerm, TextSearchDefault defaultSearchMode)
{
  std::string strParsedSearchTerm(strSearchTerm);
  StringUtils::Trim(strParsedSearchTerm);

  if (!m_bCaseSensitive)
    StringUtils::ToLower(strParsedSearchTerm);

  bool bNextAND(defaultSearchMode == SEARCH_DEFAULT_AND);
  bool bNextOR(defaultSearchMode == SEARCH_DEFAULT_OR);
  bool bNextNOT(defaultSearchMode == SEARCH_DEFAULT_NOT);

  while (strParsedSearchTerm.length() > 0)
  {
    StringUtils::TrimLeft(strParsedSearchTerm);

    if (StringUtils::StartsWith(strParsedSearchTerm, "!") || StringUtils::StartsWithNoCase(strParsedSearchTerm, "not"))
    {
      std::string strDummy;
      GetAndCutNextTerm(strParsedSearchTerm, strDummy);
      bNextNOT = true;
    }
    else if (StringUtils::StartsWith(strParsedSearchTerm, "+") || StringUtils::StartsWithNoCase(strParsedSearchTerm, "and"))
    {
      std::string strDummy;
      GetAndCutNextTerm(strParsedSearchTerm, strDummy);
      bNextAND = true;
    }
    else if (StringUtils::StartsWith(strParsedSearchTerm, "|") || StringUtils::StartsWithNoCase(strParsedSearchTerm, "or"))
    {
      std::string strDummy;
      GetAndCutNextTerm(strParsedSearchTerm, strDummy);
      bNextOR = true;
    }
    else
    {
      std::string strTerm;
      GetAndCutNextTerm(strParsedSearchTerm, strTerm);
      if (strTerm.length() > 0)
      {
        if (bNextAND)
          m_AND.push_back(strTerm);
        else if (bNextOR)
          m_OR.push_back(strTerm);
        else if (bNextNOT)
          m_NOT.push_back(strTerm);
      }
      else
      {
        break;
      }

      bNextAND = (defaultSearchMode == SEARCH_DEFAULT_AND);
      bNextOR  = (defaultSearchMode == SEARCH_DEFAULT_OR);
      bNextNOT = (defaultSearchMode == SEARCH_DEFAULT_NOT);
    }

    StringUtils::TrimLeft(strParsedSearchTerm);
  }
}

/* C Digital Auction System */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

/* Struct for items being auctioned */
typedef struct {
    char name[50];
    float starting_bid;
    float current_bid;
    int bidder_id;
} Item;

/* Struct for bidders */
typedef struct {
    char name[50];
    float balance;
    int id;
} Bidder;

/* Function to display list of items being auctioned */
void display_items(Item* items, int num_items) {
    printf("\nCurrent Items for Auction:\n");
    for (int i=0; i<num_items; i++) {
        printf("%d. %s (Starting Bid: $%.2f)\n", i+1, items[i].name, items[i].starting_bid);
    }
}

/* Function to add new item to auction */
void add_item(Item* items, int* num_items) {
    printf("\nEnter Name of Item to Add: ");
    char name[50];
    scanf("%s", name);
    printf("Enter Starting Bid Price: $");
    float starting_bid;
    scanf("%f", &starting_bid);
    Item new_item = { .starting_bid=starting_bid, .current_bid=starting_bid };
    strcpy(new_item.name, name);
    items[*num_items] = new_item;
    (*num_items)++;
    printf("\nItem Added to Auction!\n");
}

/* Function to display information about a particular item */
void display_item_info(Item item) {
    printf("\nItem Name: %s\n", item.name);
    printf("Starting Bid: $%.2f\n", item.starting_bid);
    printf("Current Bid: $%.2f\n", item.current_bid);
    printf("Bidder ID: %d\n", item.bidder_id);
}

/* Function to start bidding on an item */
void start_bidding(Item* item, Bidder* bidders, int num_bidders) {
    printf("\nStarting bidding for: %s (Starting Bid: $%.2f)", item->name, item->starting_bid);
    int bidder_id = -1;
    float current_bid = item->starting_bid;

    // Loop through all bidders to accept bids
    while (1) {
        for (int i=0; i<num_bidders; i++) {
            printf("\n\nCurrent Bid: $%.2f\n", current_bid);
            printf("Current Highest Bidder: %s (%d)\n", bidders[bidder_id-1].name, bidder_id);
            printf("%s, enter your bid (enter -1 to exit): $", bidders[i].name);
            float bid;
            scanf("%f", &bid);

            // Check if bidder wants to exit bidding
            if (bid == -1) {
                printf("\nExiting Bidding for %s\n", item->name);
                return;
            }

            // Check if bid is highest so far, and if bidder has enough balance
            if (bid > current_bid && bid <= bidders[i].balance) {
                current_bid = bid;
                bidder_id = bidders[i].id;
                printf("New Bid: $%.2f (Bidder %s)\n", current_bid, bidders[i].name);
            }
            else if (bid > current_bid && bid > bidders[i].balance) {
                printf("\nBid not accepted. %s, you do not have a sufficient balance.", bidders[i].name);
            }
        }
    }
}

/* Main function */
int main() {
    printf("Welcome to the C Digital Auction System!\n");

    // Add example items and bidders
    Item items[5] = {
        { .name="iPhone 12 Pro Max", .starting_bid=1100.00, .current_bid=1100.00, .bidder_id=-1 },
        { .name="Samsung Galaxy S20", .starting_bid=900.00, .current_bid=900.00, .bidder_id=-1 },
        { .name="Sony PlayStation 5", .starting_bid=500.00, .current_bid=500.00, .bidder_id=-1 },
        { .name="LG 65-inch OLED TV", .starting_bid=2000.00, .current_bid=2000.00, .bidder_id=-1 },
        { .name="MacBook Pro 16-inch", .starting_bid=2500.00, .current_bid=2500.00, .bidder_id=-1 }
    };
    int num_items = 5;

    Bidder bidders[3] = {
        { .name="John", .balance=3000.00, .id=1 },
        { .name="Jane", .balance=2500.00, .id=2 },
        { .name="Bob", .balance=5000.00, .id=3 }
    };
    int num_bidders = 3;

    // Display menu options
    int choice = 0;
    while (1) {
        printf("\n\nChoose an Option:\n");
        printf("1. Display Items for Auction\n");
        printf("2. Add Item to Auction\n");
        printf("3. Display Item Information\n");
        printf("4. Start Bidding on Item\n");
        printf("5. Exit Program\n");
        scanf("%d", &choice);

        // Evaluate user's choice and perform appropriate action
        switch (choice) {
            case 1:
                display_items(items, num_items);
                break;
            case 2:
                add_item(items, &num_items);
                break;
            case 3:
                printf("\nEnter Item Number to View: ");
                int item_num;
                scanf("%d", &item_num);
                display_item_info(items[item_num-1]);
                break;
            case 4:
                printf("\nEnter Item Number to Bid On: ");
                int bid_item_num;
                scanf("%d", &bid_item_num);
                start_bidding(&items[bid_item_num-1], bidders, num_bidders);
                break;
            case 5:
                printf("\nGoodbye!\n");
                return 0;
            default:
                printf("\nInvalid Choice. Please Try Again.\n");
                break;
        }
    }
}

