// Struct to store website information
typedef struct {
  char* name;
  char* url;
  int status;
  int downtime;
} Website;

// Function to check the website status
int check_website(Website* website) {
  // Create a socket
  int sock = socket(AF_INET, SOCK_STREAM, 0);
  if (sock < 0) {
    perror("socket failed");
    return 1;
  }

  // Set up the address structure
  struct sockaddr_in address;
  memset(&address, 0, sizeof(address));
  address.sin_family = AF_INET;
  address.sin_port = htons(80);

  // Resolve the domain name
  struct hostent* server = gethostbyname(website->url);
  if (server == NULL) {
    fprintf(stderr, "Could not resolve domain name: %s\n", website->url);
    return 1;
  }

  // Set up the address structure
  memcpy((char*)&address.sin_addr.s_addr, server->h_addr_list[0], server->h_length);

  // Connect to the server
  if (connect(sock, (struct sockaddr*)&address, sizeof(address)) < 0) {
    perror("connect failed");
    return 1;
  }

  // Send a request to the server
  char request[] = "GET / HTTP/1.1\r\nHost: ";
  strcat(request, website->url);
  strcat(request, "\r\n\r\n");
  send(sock, request, strlen(request), 0);

  // Read the response from the server
  char response[1024];
  int response_len = recv(sock, response, 1024, 0);
  if (response_len < 0) {
    perror("recv failed");
    return 1;
  }

  // Check the status code
  char* status_code = strtok(response, " ");
  if (status_code == NULL || strcmp(status_code, "200") != 0) {
    website->status = 0;
    return 0;
  }

  // Check the downtime
  website->downtime = 0;
  return 1;
}

// Function to print the website information
void print_website(Website* website) {
  printf("Website: %s\n", website->name);
  printf("URL: %s\n", website->url);
  printf("Status: %s\n", website->status ? "Up" : "Down");
  printf("Downtime: %d\n", website->downtime);
}

int main(void) {
  // Create an array of websites to monitor
  Website websites[] = {
    {"Google", "www.google.com", 1, 0},
    {"Facebook", "www.facebook.com", 1, 0},
    {"Twitter", "www.twitter.com", 1, 0},
  };

  // Loop through the websites and check their status
  for (int i = 0; i < sizeof(websites) / sizeof(Website); i++) {
    if (!check_website(&websites[i])) {
      websites[i].downtime++;
    }
  }

  // Print the website information
  for (int i = 0; i < sizeof(websites) / sizeof(Website); i++) {
    print_website(&websites[i]);
  }

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_NODES 10

int adjMat[MAX_NODES][MAX_NODES];
int numNodes;

void printHeader()
{
    printf("\n");
    printf("**********************************************\n");
    printf("          NETWORK TOPOLOGY MAPPER\n");
    printf("**********************************************\n\n");
}

void printMenu()
{
    printf("COMMAND MENU\n\n");
    printf("1. Add node\n");
    printf("2. Remove node\n");
    printf("3. Add connection\n");
    printf("4. Remove connection\n");
    printf("5. Display topology\n");
    printf("6. Exit\n\n");
}

void addNode()
{
    if (numNodes == MAX_NODES)
    {
        printf("Sorry, maximum number of nodes (%d) have already been added.\n", MAX_NODES);
    }
    else
    {
        char nodeName;
        printf("Enter node name: ");
        scanf(" %c", &nodeName);
        adjMat[numNodes][numNodes] = 1;
        printf("Node %c has been added.\n", nodeName);
        numNodes++;
    }
}

void removeNode()
{
    if (numNodes == 0)
    {
        printf("Sorry, there are no nodes to remove.\n");
    }
    else
    {
        int index;
        printf("Enter index of node to remove: ");
        scanf("%d", &index);
        if (index < 0 || index >= numNodes)
        {
            printf("Invalid index. Please try again.\n");
        }
        else
        {
            char nodeName = 'A' + index;
            for (int i = index; i < numNodes - 1; i++)
            {
                for (int j = 0; j < numNodes; j++)
                {
                    adjMat[i][j] = adjMat[i+1][j];
                }
            }
            for (int i = index; i < numNodes - 1; i++)
            {
                for (int j = 0; j < numNodes; j++)
                {
                    adjMat[j][i] = adjMat[j][i+1];
                }
            }
            for (int i = 0; i < numNodes; i++)
            {
                adjMat[numNodes-1][i] = 0;
                adjMat[i][numNodes-1] = 0;
            }
            numNodes--;
            printf("Node %c has been removed.\n", nodeName);
        }
    }
}

void addConnection()
{
    if (numNodes < 2)
    {
        printf("Sorry, you need at least 2 nodes to add a connection.\n");
    }
    else
    {
        int index1, index2;
        printf("Enter index of first node: ");
        scanf("%d", &index1);
        printf("Enter index of second node: ");
        scanf("%d", &index2);
        if (index1 < 0 || index1 >= numNodes || index2 < 0 || index2 >= numNodes || index1 == index2)
        {
            printf("Invalid indices. Please try again.\n");
        }
        else
        {
            adjMat[index1][index2] = 1;
            adjMat[index2][index1] = 1;
            printf("Connection between nodes %c and %c has been added.\n", 'A' + index1, 'A' + index2);
        }
    }
}

void removeConnection()
{
    if (numNodes < 2)
    {
        printf("Sorry, you need at least 2 nodes to remove a connection.\n");
    }
    else
    {
        int index1, index2;
        printf("Enter index of first node: ");
        scanf("%d", &index1);
        printf("Enter index of second node: ");
        scanf("%d", &index2);
        if (index1 < 0 || index1 >= numNodes || index2 < 0 || index2 >= numNodes || index1 == index2)
        {
            printf("Invalid indices. Please try again.\n");
        }
        else if (adjMat[index1][index2] == 0)
        {
            printf("There is no connection between nodes %c and %c.\n", 'A' + index1, 'A' + index2);
        }
        else
        {
            adjMat[index1][index2] = 0;
            adjMat[index2][index1] = 0;
            printf("Connection between nodes %c and %c has been removed.\n", 'A' + index1, 'A' + index2);
        }
    }
}

void displayTopology()
{
    printf("TOPOLOGY\n\n");
    printf("   ");
    for (int i = 0; i < numNodes; i++)
    {
        printf("%c ", 'A' + i);
    }
    printf("\n");
    for (int i = 0; i < numNodes; i++)
    {
        printf("%c  ", 'A' + i);
        for (int j = 0; j < numNodes; j++)
        {
            if (adjMat[i][j] == 1)
            {
                printf("X ");
            }
            else
            {
                printf("  ");
            }
        }
        printf("\n");
    }
}

int main()
{
    printHeader();
    numNodes = 0;
    int choice;
    do
    {
        printMenu();
        printf("Enter command number: ");
        scanf("%d", &choice);
        switch (choice)
        {
            case 1:
                addNode();
                break;
            case 2:
                removeNode();
                break;
            case 3:
                addConnection();
                break;
            case 4:
                removeConnection();
                break;
            case 5:
                displayTopology();
                break;
            case 6:
                printf("Exiting the program...\n");
                break;
            default:
                printf("Invalid command number. Please try again.\n");
                break;
        }
    } while (choice != 6);
    return 0;
}

#include "injected.h"
#include <mach-o/dyld_images.h>
#include <mach-o/loader.h>
#include <mach-o/nlist.h>
#include <string.h>
#include <dlfcn.h>

/* These values are overwritten on a per-injection basis by the injector. */
/* Must not be defined as consts, or the compiler will optimize them. */
struct dyld_all_image_infos *dyld_info = (typeof(dyld_info)) DYLD_MAGIC_32;

char argument[ARGUMENT_MAX_LENGTH] = ARGUMENT_MAGIC_STR;

/* The interrupt calling convention does not save the flags register, so we use
   these ASM functions to save and restore it outselves. They must be called as
   early and as late as possible, respectively, so instructions that modify flags
   won't destory the state. */

uint32_t get_flags(void);
/* Use fastcall for set_flags, parameters on registers are easier to work with. */
__attribute__((fastcall)) void set_flags(uint32_t);

__asm__ (
         "_get_flags: \n"
         "    pushfd \n"
         "    pop %eax \n"
         "    ret \n"

         "_set_flags: \n"
         "    push %ecx \n"
         "    popfd \n"
         "    ret \n"
         );

static const struct mach_header *get_header_by_path(const char *name)
{
    for (unsigned i = 0; i < dyld_info->infoArrayCount; i++) {
        if (strcmp(dyld_info->infoArray[i].imageFilePath, name) == 0) {
            return (const struct mach_header *) dyld_info->infoArray[i].imageLoadAddress;
        }
    }
    return NULL;
}

static const void *get_symbol_from_header(const struct mach_header *header, const char *symbol)
{
    if (!header) {
        return NULL;
    }

    /* Get the required commands */

    const struct symtab_command *symtab = NULL;
    const struct segment_command *first = NULL;
    const struct segment_command *linkedit = NULL;
    const struct load_command *cmd = (typeof(cmd))(header + 1);

    for (unsigned i = 0; i < header->ncmds; i++, cmd = (typeof(cmd)) ((char*) cmd + cmd->cmdsize)) {
        if (cmd->cmd == LC_SEGMENT) {
            if (!first && ((typeof(first))cmd)->filesize ) {
                first = (typeof(first)) cmd;
            }
            if (strcmp(((typeof(linkedit)) cmd)->segname, "__LINKEDIT") == 0) {
                linkedit = (typeof(linkedit)) cmd;
            }
        }
        else if (cmd->cmd == LC_SYMTAB) {
            symtab = (typeof (symtab)) cmd;
        }
        if (symtab && linkedit) break;
    }

    if (!symtab || !linkedit) return NULL;

    const char *string_table =
        ((const char *) header + symtab->stroff - linkedit->fileoff + linkedit->vmaddr - first->vmaddr);
    const struct nlist *symbols = (typeof (symbols))
        ((const char *) header + symtab->symoff - linkedit->fileoff + linkedit->vmaddr - first->vmaddr);

    for (unsigned i = 0; i < symtab->nsyms; i++) {
        if (strcmp(string_table + symbols[i].n_un.n_strx, symbol) == 0) {
            return (char *)header + symbols[i].n_value - first->vmaddr;
        }
    }

    return NULL;
}


void _entry()
{
    uint32_t flags = get_flags();

    typeof(dlopen) *$dlopen = NULL;

    /* We can't call dyld`dlopen when dyld3 is being used, so we must find libdyld`dlopen and call that instead */
    $dlopen = get_symbol_from_header(get_header_by_path("/usr/lib/system/libdyld.dylib"), "_dlopen");

    if ($dlopen) {
        $dlopen(argument, RTLD_NOW);
    }

    set_flags(flags);
}

/* Clang on x86-32 does not support the preserve_all convention. Instead, we use
 * the interrupt attribute. The Makefile takes care of replacing iret with ret.
   Additionally, Clang sometimes stores xmm7 on an unaligned address and crashes,
   and since LLVM's bug tracker has been down for ages, the Makefile fixes that
   as well. -_- */
void __attribute__((interrupt)) entry(void * __attribute__((unused)) unused)
{
    _entry();
}

/* Taken from Apple's libc */

int 
strcmp(s1, s2)
const char *s1, *s2;
{
    while (*s1 == *s2++)
        if (*s1++ == 0)
            return (0);
    return (*(const unsigned char *)s1 - *(const unsigned char *)(s2 - 1));
}

