UA_Boolean running = true;
static void stopHandler(int sig) {
    running = false;
}

int main(void) {
    signal(SIGINT,  stopHandler);
    signal(SIGTERM, stopHandler);

    UA_ServerConfig config = UA_ServerConfig_standard;
    UA_ServerNetworkLayer nl = UA_ServerNetworkLayerTCP(UA_ConnectionConfig_standard, 16664);
    config.networkLayers = &nl;
    config.networkLayersSize = 1;
    UA_Server *server = UA_Server_new(config);

    /* Create a rudimentary objectType
     * 
     * BaseObjectType
     * |
     * +- (OT) MamalType
     *    + (V) Age
     *    + (OT) DogType
     *      |
     *      + (V) Name
     */ 
    UA_StatusCode retval;
    UA_ObjectTypeAttributes otAttr;
    UA_ObjectTypeAttributes_init(&otAttr);

    otAttr.description = UA_LOCALIZEDTEXT("en_US", "A mamal");
    otAttr.displayName = UA_LOCALIZEDTEXT("en_US", "MamalType");
    UA_Server_addObjectTypeNode(server, UA_NODEID_NUMERIC(1, 10000), 
                                UA_NODEID_NUMERIC(0, UA_NS0ID_BASEOBJECTTYPE), UA_NODEID_NUMERIC(0, UA_NS0ID_HASSUBTYPE),
                                UA_QUALIFIEDNAME(1, "MamalType"), otAttr, NULL, NULL);

    UA_VariableAttributes   vAttr;
    UA_VariableAttributes_init(&vAttr);
    vAttr.description =  UA_LOCALIZEDTEXT("en_US", "This mamals Age in months");
    vAttr.displayName =  UA_LOCALIZEDTEXT("en_US", "Age");
    UA_UInt32 ageVar = 0;
    UA_Variant_setScalarCopy(&vAttr.value, &ageVar, &UA_TYPES[UA_TYPES_UINT32]);
    UA_Server_addVariableNode(server, UA_NODEID_NUMERIC(1, 10001), 
                              UA_NODEID_NUMERIC(1, 10000), UA_NODEID_NUMERIC(0, UA_NS0ID_HASPROPERTY),
                              UA_QUALIFIEDNAME(1, "Age"), UA_NODEID_NULL, vAttr, NULL, NULL);

    UA_ObjectTypeAttributes_init(&otAttr);
    otAttr.description = UA_LOCALIZEDTEXT("en_US", "A dog, subtype of mamal");
    otAttr.displayName = UA_LOCALIZEDTEXT("en_US", "DogType");
    UA_Server_addObjectTypeNode(server, UA_NODEID_NUMERIC(1, 10002), 
                                UA_NODEID_NUMERIC(1, 10000), UA_NODEID_NUMERIC(0, UA_NS0ID_HASSUBTYPE),
                                UA_QUALIFIEDNAME(1, "DogType"), otAttr, NULL, NULL);

    UA_VariableAttributes_init(&vAttr);
    vAttr.description =  UA_LOCALIZEDTEXT("en_US", "This mamals Age in months");
    vAttr.displayName =  UA_LOCALIZEDTEXT("en_US", "Name");
    UA_String defaultName = UA_STRING("unnamed dog");
    UA_Variant_setScalarCopy(&vAttr.value, &defaultName, &UA_TYPES[UA_TYPES_STRING]);
    UA_Server_addVariableNode(server, UA_NODEID_NUMERIC(1, 10003), 
                              UA_NODEID_NUMERIC(1, 10002), UA_NODEID_NUMERIC(0, UA_NS0ID_HASPROPERTY),
                              UA_QUALIFIEDNAME(1, "Name"), UA_NODEID_NULL, vAttr, NULL, NULL);

    /* Instatiate a dog named bello:
     * (O) Objects
     *   + O Bello <DogType>
     *     + Age 
     *     + Name
     */

    UA_ObjectAttributes oAttr;
    UA_ObjectAttributes_init(&oAttr);
    oAttr.description = UA_LOCALIZEDTEXT("en_US", "A dog named Bello");
    oAttr.displayName = UA_LOCALIZEDTEXT("en_US", "Bello");
    UA_Server_addObjectNode(server, UA_NODEID_NUMERIC(1, 0), 
                            UA_NODEID_NUMERIC(0, UA_NS0ID_OBJECTSFOLDER), UA_NODEID_NUMERIC(0, UA_NS0ID_HASCOMPONENT),
                            UA_QUALIFIEDNAME(1, "Bello"), UA_NODEID_NUMERIC(1, 10002), oAttr, NULL, NULL);

    retval = UA_Server_run(server, &running);
    UA_Server_delete(server);
    nl.deleteMembers(&nl);
    return (int)retval;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define INPUT_SIZE 784
#define OUTPUT_SIZE 10
#define CONV_SIZE 3
#define POOL_SIZE 2
#define NUM_FILTERS 32
#define HIDDEN_SIZE 128
#define BATCH_SIZE 64
#define LEARNING_RATE 0.001
#define NUM_EPOCHS 10

typedef struct {
    double data[INPUT_SIZE];
    int label;
} image_t;

typedef struct {
    double data[OUTPUT_SIZE];
} output_t;

typedef struct {
    double weights[CONV_SIZE][CONV_SIZE][NUM_FILTERS];
    double bias;
} conv_layer_t;

typedef struct {
    double weights[HIDDEN_SIZE][OUTPUT_SIZE];
    double bias[HIDDEN_SIZE];
} hidden_layer_t;

typedef struct {
    double weights[OUTPUT_SIZE][HIDDEN_SIZE];
    double bias[OUTPUT_SIZE];
} output_layer_t;

int main() {
    // Load MNIST dataset
    image_t* train_images = (image_t*)malloc(60000 * sizeof(image_t));
    output_t* train_labels = (output_t*)malloc(60000 * sizeof(output_t));
    image_t* test_images = (image_t*)malloc(10000 * sizeof(image_t));
    output_t* test_labels = (output_t*)malloc(10000 * sizeof(output_t));
    // Code for loading images and labels from files goes here...

    // Initialize CNN layers
    conv_layer_t conv_layer;
    hidden_layer_t hidden_layer;
    output_layer_t output_layer;
    for (int i = 0; i < CONV_SIZE; i++) {
        for (int j = 0; j < CONV_SIZE; j++) {
            for (int k = 0; k < NUM_FILTERS; k++) {
                conv_layer.weights[i][j][k] = ((double)(rand() % 1000) / 500.0) - 1.0;
            }
        }
    }
    conv_layer.bias = ((double)(rand() % 1000) / 500.0) - 1.0;
    for (int i = 0; i < HIDDEN_SIZE; i++) {
        for (int j = 0; j < OUTPUT_SIZE; j++) {
            hidden_layer.weights[i][j] = ((double)(rand() % 1000) / 500.0) - 1.0;
        }
        hidden_layer.bias[i] = ((double)(rand() % 1000) / 500.0) - 1.0;
    }
    for (int i = 0; i < OUTPUT_SIZE; i++) {
        for (int j = 0; j < HIDDEN_SIZE; j++) {
            output_layer.weights[i][j] = ((double)(rand() % 1000) / 500.0) - 1.0;
        }
        output_layer.bias[i] = ((double)(rand() % 1000) / 500.0) - 1.0;
    }

    // Train CNN
    for (int epoch = 0; epoch < NUM_EPOCHS; epoch++) {
        printf("Epoch %d\n", epoch+1);
        for (int batch_start = 0; batch_start < 60000; batch_start += BATCH_SIZE) {
            // Forward pass
            for (int i = 0; i < BATCH_SIZE; i++) {
                double conv_output[28][28][NUM_FILTERS];
                for (int j = 0; j < 28; j++) {
                    for (int k = 0; k < 28; k++) {
                        for (int l = 0; l < NUM_FILTERS; l++) {
                            double sum = 0.0;
                            for (int m = 0; m < CONV_SIZE; m++) {
                                for (int n = 0; n < CONV_SIZE; n++) {
                                    if (j+m-1 >= 0 && j+m-1 < 28 && k+n-1 >= 0 && k+n-1 < 28) {
                                        sum += train_images[batch_start+i].data[(j+m-1)*28+(k+n-1)] * conv_layer.weights[m][n][l];
                                    }
                                }
                            }
                            conv_output[j][k][l] = fmax(0.0, sum + conv_layer.bias);
                        }
                    }
                }
                double pool_output[14][14][NUM_FILTERS];
                for (int j = 0; j < 14; j++) {
                    for (int k = 0; k < 14; k++) {
                        for (int l = 0; l < NUM_FILTERS; l++) {
                            double max = 0.0;
                            for (int m = 0; m < POOL_SIZE; m++) {
                                for (int n = 0; n < POOL_SIZE; n++) {
                                    double val = conv_output[j*2+m][k*2+n][l];
                                    if (val > max) {
                                        max = val;
                                    }
                                }
                            }
                            pool_output[j][k][l] = max;
                        }
                    }
                }
                double hidden_output[HIDDEN_SIZE];
                for (int j = 0; j < HIDDEN_SIZE; j++) {
                    double sum = 0.0;
                    for (int k = 0; k < 14; k++) {
                        for (int l = 0; l < 14; l++) {
                            for (int m = 0; m < NUM_FILTERS; m++) {
                                sum += pool_output[k][l][m] * hidden_layer.weights[j][m];
                            }
                        }
                    }
                    hidden_output[j] = fmax(0.0, sum + hidden_layer.bias[j]);
                }
                double output_output[OUTPUT_SIZE];
                for (int j = 0; j < OUTPUT_SIZE; j++) {
                    double sum = 0.0;
                    for (int k = 0; k < HIDDEN_SIZE; k++) {
                        sum += hidden_output[k] * output_layer.weights[j][k];
                    }
                    output_output[j] = sum + output_layer.bias[j];
                }
                double output_exp[OUTPUT_SIZE];
                double output_softmax[OUTPUT_SIZE];
                double output_error[OUTPUT_SIZE];
                double label_onehot[OUTPUT_SIZE];
                for (int j = 0; j < OUTPUT_SIZE; j++) {
                    output_exp[j] = exp(output_output[j]);
                    label_onehot[j] = 0.0;
                    if (j == train_images[batch_start+i].label) {
                        label_onehot[j] = 1.0;
                    }
                }
                double output_exp_sum = 0.0;
                for (int j = 0; j < OUTPUT_SIZE; j++) {
                    output_exp_sum += output_exp[j];
                }
                for (int j = 0; j < OUTPUT_SIZE; j++) {
                    output_softmax[j] = output_exp[j] / output_exp_sum;
                    output_error[j] = output_softmax[j] - label_onehot[j];
                }

                // Backward pass
                for (int j = 0; j < OUTPUT_SIZE; j++) {
                    output_layer.bias[j] -= LEARNING_RATE * output_error[j];
                    for (int k = 0; k < HIDDEN_SIZE; k++) {
                        output_layer.weights[j][k] -= LEARNING_RATE * output_error[j] * hidden_output[k];
                    }
                }
                double hidden_error[HIDDEN_SIZE];
                for (int j = 0; j < HIDDEN_SIZE; j++) {
                    double sum = 0.0;
                    for (int k = 0; k < OUTPUT_SIZE; k++) {
                        sum += output_error[k] * output_layer.weights[k][j];
                    }
                    if (hidden_output[j] > 0.0) {
                        hidden_error[j] = sum;
                    } else {
                        hidden_error[j] = 0.0;
                    }
                    hidden_layer.bias[j] -= LEARNING_RATE * hidden_error[j];
                    for (int k = 0; k < 14; k++) {
                        for (int l = 0; l < 14; l++) {
                            for (int m = 0; m < NUM_FILTERS; m++) {
                                hidden_layer.weights[j][m] -= LEARNING_RATE * hidden_error[j] * pool_output[k][l][m];
                            }
                        }
                    }
                }
                double pool_error[14][14][NUM_FILTERS];
                for (int j = 0; j < 14; j++) {
                    for (int k = 0; k < 14; k++) {
                        for (int l = 0; l < NUM_FILTERS; l++) {
                            double max = 0.0;
                            int max_index = -1;
                            for (int m = 0; m < POOL_SIZE; m++) {
                                for (int n = 0; n < POOL_SIZE; n++) {
                                    double val = conv_output[j*2+m][k*2+n][l];
                                    if (val > max) {
                                        max = val;
                                        max_index = m*POOL_SIZE+n;
                                    }
                                }
                            }
                            for (int m = 0; m < POOL_SIZE; m++) {
                                for (int n = 0; n < POOL_SIZE; n++) {
                                    if (max_index == m*POOL_SIZE+n) {
                                        pool_error[j*2+m][k*2+n][l] = hidden_error[0];
                                    } else {
                                        pool_error[j*2+m][k*2+n][l] = 0.0;
                                    }
                                }
                            }
                        }
                    }
                }
                double conv_error[28][28][NUM_FILTERS];
                for (int j = 0; j < 28; j++) {
                    for (int k = 0; k < 28; k++) {
                        for (int l = 0; l < NUM_FILTERS; l++) {
                            double sum = 0.0;
                            for (int m = 0; m < POOL_SIZE; m++) {
                                for (int n = 0; n < POOL_SIZE; n++) {
                                    for (int o = 0; o < NUM_FILTERS; o++) {
                                        if (j-m+1 >= 0 && j-m+1 < 14 && k-n+1 >= 0 && k-n+1 < 14) {
                                            sum += pool_error[j-m+1][k-n+1][o] * conv_layer.weights[m][n][o];
                                        }
                                    }
                                }
                            }
                            if (conv_output[j][k][l] > 0.0) {
                                conv_error[j][k][l] = sum;
                            } else {
                                conv_error[j][k][l] = 0.0;
                            }
                            conv_layer.bias -= LEARNING_RATE * conv_error[j][k][l];
                            for (int m = 0; m < CONV_SIZE; m++) {
                                for (int n = 0; n < CONV_SIZE; n++) {
                                    if (j-m+1 >= 0 && j-m+1 < 28 && k-n+1 >= 0 && k-n+1 < 28) {
                                        conv_layer.weights[m][n][l] -= LEARNING_RATE * conv_error[j][k][l] * train_images[batch_start+i].data[(j-m+1)*28+(k-n+1)];
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // Evaluate CNN on test set
    int num_correct = 0;
    for (int i = 0; i < 10000; i++) {
        double conv_output[28][28][NUM_FILTERS];
        for (int j = 0; j < 28; j++) {
            for (int k = 0; k < 28; k++) {
                for (int l = 0; l < NUM_FILTERS; l++) {
                    double sum = 0.0;
                    for (int m = 0; m < CONV_SIZE; m++) {
                        for (int n = 0; n < CONV_SIZE; n++) {
                            if (j+m-1 >= 0 && j+m-1 < 28 && k+n-1 >= 0 && k+n-1 < 28) {
                                sum += test_images[i].data[(j+m-1)*28+(k+n-1)] * conv_layer.weights[m][n][l];
                            }
                        }
                    }
                    conv_output[j][k][l] = fmax(0.0, sum + conv_layer.bias);
                }
            }
        }
        double pool_output[14][14][NUM_FILTERS];
        for (int j = 0; j < 14; j++) {
            for (int k = 0; k < 14; k++) {
                for (int l = 0; l < NUM_FILTERS; l++) {
                    double max = 0.0;
                    for (int m = 0; m < POOL_SIZE; m++) {
                        for (int n = 0; n < POOL_SIZE; n++) {
                            double val = conv_output[j*2+m][k*2+n][l];
                            if (val > max) {
                                max = val;
                            }
                        }
                    }
                    pool_output[j][k][l] = max;
                }
            }
        }
        double hidden_output[HIDDEN_SIZE];
        for (int j = 0; j < HIDDEN_SIZE; j++) {
            double sum = 0.0;
            for (int k = 0; k < 14; k++) {
                for (int l = 0; l < 14; l++) {
                    for (int m = 0; m < NUM_FILTERS; m++) {
                        sum += pool_output[k][l][m] * hidden_layer.weights[j][m];
                    }
                }
            }
            hidden_output[j] = fmax(0.0, sum + hidden_layer.bias[j]);
        }
        double output_output[OUTPUT_SIZE];
        for (int j = 0; j < OUTPUT_SIZE; j++) {
            double sum = 0.0;
            for (int k = 0; k < HIDDEN_SIZE; k++) {
                sum += hidden_output[k] * output_layer.weights[j][k];
            }
            output_output[j] = sum + output_layer.bias[j];
        }
        int predicted_label = 0;
        double max_output = 0.0;
        for (int j = 0; j < OUTPUT_SIZE; j++) {
            if (output_output[j] > max_output) {
                predicted_label = j;
                max_output = output_output[j];
            }
        }
        if (predicted_label == test_labels[i].data) {
            num_correct++;
        }
    }
    printf("Test accuracy: %f\n", (double)num_correct / 10000.0);

    // Clean up
    free(train_images);
    free(train_labels);
    free(test_images);
    free(test_labels);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_BLOCK_SIZE 1024
#define MAX_ALLOC_SIZE 1024 * 1024 * 10

typedef struct block {
    size_t size;
    int free;
    struct block *next;
} Block;

Block *freeList = (void *)0;

void init() {
    Block *block = (void *)malloc(MAX_BLOCK_SIZE);
    freeList = block;
    block->size = MAX_BLOCK_SIZE - sizeof(Block);
    block->free = 1;
    block->next = (void *)0;
}

void *myMalloc(size_t numBytes) {
    Block *current = freeList;
    while (current!= (void *)0 && current->size < numBytes)
        current = current->next;

    if (current == (void *)0) {
        Block *block = (void *)malloc(MAX_BLOCK_SIZE);
        if (block == (void *)0)
            return (void *)0;
        block->size = MAX_BLOCK_SIZE - sizeof(Block);
        block->free = 0;
        block->next = (void *)0;
        current = block;
    }

    void *result = (char *)current + sizeof(Block);
    current->size -= numBytes;
    current->free = 0;

    return result;
}

void myFree(void *ptr) {
    if (ptr == (void *)0)
        return;

    Block *block = (void *)ptr - sizeof(Block);
    block->free = 1;

    Block *current = freeList;
    while (current->next!= (void *)0 && current->next->size < block->size)
        current = current->next;

    block->next = current->next;
    current->next = block;
}

int main() {
    init();

    void *ptr1 = myMalloc(100);
    void *ptr2 = myMalloc(200);
    void *ptr3 = myMalloc(300);

    printf("Allocated %d bytes at %p\n", 100, ptr1);
    printf("Allocated %d bytes at %p\n", 200, ptr2);
    printf("Allocated %d bytes at %p\n", 300, ptr3);

    myFree(ptr1);
    myFree(ptr3);

    printf("Freed %d bytes at %p\n", 100, ptr1);
    printf("Freed %d bytes at %p\n", 300, ptr3);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX 10

void initialize_board(int **board, int size)
{
    board = (int *)malloc(size * sizeof(int *));
    for (int i = 0; i < size; i++)
    {
        board[i] = (int *)malloc(size * sizeof(int));
        for (int j = 0; j < size; j++)
        {
            board[i][j] = 0;
        }
    }
}

void print_board(int **board, int size)
{
    for (int i = 0; i < size; i++)
    {
        for (int j = 0; j < size; j++)
        {
            printf("%d ", board[i][j]);
        }
        printf("\n");
    }
}

int count_alive(int **board, int x, int y)
{
    int alive_neighbors = 0;
    int size = board[0][0];

    // Check the neighbors to the left
    if (x - 1 >= 0)
    {
        alive_neighbors++;
    }

    // Check the neighbors above
    if (y - 1 >= 0)
    {
        alive_neighbors++;
    }

    // Check the neighbors to the right
    if (x + 1 < size)
    {
        alive_neighbors++;
    }

    // Check the neighbors below
    if (y + 1 < size)
    {
        alive_neighbors++;
    }

    return alive_neighbors;
}

void update_board(int **board, int size)
{
    for (int i = 0; i < size; i++)
    {
        for (int j = 0; j < size; j++)
        {
            int alive_neighbors = count_alive(board, i, j);

            if (alive_neighbors < 2)
            {
                board[i][j] = 0;
            }
            else if (alive_neighbors == 2)
            {
                board[i][j] = 1;
            }
            else if (alive_neighbors > 3)
            {
                board[i][j] = 0;
            }
        }
    }
}

int main()
{
    int size = MAX;
    int **board = NULL;

    initialize_board(&board, size);

    // Initial board setup
    board[0][0] = 1;
    board[1][0] = 1;
    board[2][0] = 1;
    board[3][0] = 1;
    board[0][1] = 1;
    board[1][1] = 1;
    board[2][1] = 1;

    print_board(board, size);

    update_board(board, size);

    print_board(board, size);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// Defining the Custom Data Type 
typedef struct {
    char title[100];
    char author[100];
    char publisher[100];
    int year;
    long int ISBN;
    float price;
} Book;

// Function to Read a Book from the File 
void read_book(Book * b, FILE * fp) {
    fscanf(fp, "%[^,],%[^,],%[^,],%d,%ld,%f", b->title, b->author, b->publisher, &b->year, &b->ISBN, &b->price);
}

// Function to Print a Book 
void print_book(Book b) {
    printf("Title: %s\n", b.title);
    printf("Author: %s\n", b.author);
    printf("Publisher: %s\n", b.publisher);
    printf("Year: %d\n", b.year);
    printf("ISBN: %ld\n", b.ISBN);
    printf("Price: %f\n", b.price);
}

// Function to Display the Menu 
int display_menu() {
    int choice;
    printf("\n------------------------\n");
    printf("1. Display Book(s)\n");
    printf("2. Add Book\n");
    printf("3. Remove Book\n");
    printf("4. Update Book\n");
    printf("5. Exit\n");
    printf("------------------------\n");
    printf("Enter Choice: ");
    scanf("%d", &choice);
    return choice;
}

// Function to Display All Books 
void display_all_books(Book * books, int num_books) {
    printf("\nAll Books:\n");
    for (int i = 0; i < num_books; i++) {
        printf("Book %d:\n", i + 1);
        print_book(books[i]);
    }
}

// Function to Add a Book 
Book add_book() {
    Book b;
    printf("\nEnter Details:\n");
    printf("Title: ");
    scanf(" %[^\n]s", b.title);
    printf("Author: ");
    scanf(" %[^\n]s", b.author);
    printf("Publisher: ");
    scanf(" %[^\n]s", b.publisher);
    printf("Year: ");
    scanf(" %d", &b.year);
    printf("ISBN: ");
    scanf(" %ld", &b.ISBN);
    printf("Price: ");
    scanf(" %f", &b.price);
    return b;
}

// Function to Remove a Book 
void remove_book(Book * books, int * num_books) {
    long int ISBN;
    printf("\nEnter ISBN of the Book to Remove: ");
    scanf("%ld", &ISBN);

    int index = -1;
    for (int i = 0; i < *num_books; i++) {
        if (books[i].ISBN == ISBN) {
            index = i;
            break;
        }
    }

    if (index == -1) {
        printf("\nBook with ISBN %ld not found.\n", ISBN);
        return;
    }

    for (int i = index; i < *num_books - 1; i++) {
        books[i] = books[i + 1];
    }

    (*num_books)--;
    printf("\nBook with ISBN %ld removed successfully.\n", ISBN);
}

// Function to Update a Book 
void update_book(Book * books, int num_books) {
    long int ISBN;
    printf("\nEnter ISBN of the Book to Update: ");
    scanf("%ld", &ISBN);

    int index = -1;
    for (int i = 0; i < num_books; i++) {
        if (books[i].ISBN == ISBN) {
            index = i;
            break;
        }
    }

    if (index == -1) {
        printf("\nBook with ISBN %ld not found.\n", ISBN);
        return;
    }

    printf("\nUpdate Details:\n");
    printf("Title (old: %s): ", books[index].title);
    scanf(" %[^\n]s", books[index].title);
    printf("Author (old: %s): ", books[index].author);
    scanf(" %[^\n]s", books[index].author);
    printf("Publisher (old: %s): ", books[index].publisher);
    scanf(" %[^\n]s", books[index].publisher);
    printf("Year (old: %d): ", books[index].year);
    scanf(" %d", &books[index].year);
    printf("Price (old: %f): ", books[index].price);
    scanf(" %f", &books[index].price);

    printf("\nBook with ISBN %ld updated successfully.\n", ISBN);
}

int main() {
    FILE * fp = fopen("books.txt", "r");
    if (fp == NULL) {
        printf("Error: Could not open file.\n");
        exit(1);
    }

    int num_books = 0;
    Book books[50];

    while (!feof(fp)) {
        read_book(&books[num_books], fp);
        num_books++;
    }

    fclose(fp);

    while (1) {
        int choice = display_menu();

        switch (choice) {
            case 1:
                display_all_books(books, num_books);
                break;
            case 2:
                if (num_books == 50) {
                    printf("\nCannot add more books. Maximum limit reached.\n");
                    break;
                }
                Book b = add_book();
                books[num_books] = b;
                num_books++;
                printf("\nBook added successfully.\n");
                break;
            case 3:
                if (num_books == 0) {
                    printf("\nNo books are available to remove.\n");
                    break;
                }
                remove_book(books, &num_books);
                break;
            case 4:
                if (num_books == 0) {
                    printf("\nNo books are available to update.\n");
                    break;
                }
                update_book(books, num_books);
                break;
            case 5:
                fp = fopen("books.txt", "w");
                if (fp == NULL) {
                    printf("Error: Could not open file.\n");
                    exit(1);
                }

                for (int i = 0; i < num_books; i++) {
                    fprintf(fp, "%s,%s,%s,%d,%ld,%f\n", books[i].title, books[i].author, books[i].publisher, books[i].year, books[i].ISBN, books[i].price);
                }

                fclose(fp);
                printf("\nExiting...\n");
                exit(0);
            default:
                printf("\nInvalid choice. Please try again.\n");
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_VOTERS 100
#define MAX_CANDIDATES 10

typedef struct {
    char name[50];
    int votes;
} candidate_t;

typedef struct {
    char name[50];
    char id[10];
    int voted;
} voter_t;

// Global variables
voter_t voters[MAX_VOTERS];
candidate_t candidates[MAX_CANDIDATES];
int num_voters;
int num_candidates;

// Function prototypes
void add_voter(char *name, char *id);
void add_candidate(char *name);
void vote(char *id, char *candidate_name);
void print_results();

int main() {
    // Initialize the system
    num_voters = 0;
    num_candidates = 0;

    // Add some sample voters and candidates
    add_voter("John Doe", "12345");
    add_voter("Jane Smith", "67890");
    add_candidate("Candidate 1");
    add_candidate("Candidate 2");
    add_candidate("Candidate 3");

    // Run the voting process
    while (1) {
        // Get the voter's ID
        char id[10];
        printf("Enter your ID: ");
        scanf("%s", id);

        // Check if the voter is registered
        int voter_index = -1;
        for (int i = 0; i < num_voters; i++) {
            if (strcmp(voters[i].id, id) == 0) {
                voter_index = i;
                break;
            }
        }

        if (voter_index == -1) {
            printf("Invalid ID. Please try again.\n");
            continue;
        }

        // Check if the voter has already voted
        if (voters[voter_index].voted) {
            printf("You have already voted. Thank you for your participation.\n");
            continue;
        }

        // Get the candidate's name
        char candidate_name[50];
        printf("Enter the name of the candidate you want to vote for: ");
        scanf(" %s", candidate_name);

        // Check if the candidate is valid
        int candidate_index = -1;
        for (int i = 0; i < num_candidates; i++) {
            if (strcmp(candidates[i].name, candidate_name) == 0) {
                candidate_index = i;
                break;
            }
        }

        if (candidate_index == -1) {
            printf("Invalid candidate name. Please try again.\n");
            continue;
        }

        // Cast the vote
        vote(id, candidate_name);

        // Print the results
        print_results();
    }

    return 0;
}

void add_voter(char *name, char *id) {
    strcpy(voters[num_voters].name, name);
    strcpy(voters[num_voters].id, id);
    voters[num_voters].voted = 0;
    num_voters++;
}

void add_candidate(char *name) {
    strcpy(candidates[num_candidates].name, name);
    candidates[num_candidates].votes = 0;
    num_candidates++;
}

void vote(char *id, char *candidate_name) {
    // Find the voter's index
    int voter_index = -1;
    for (int i = 0; i < num_voters; i++) {
        if (strcmp(voters[i].id, id) == 0) {
            voter_index = i;
            break;
        }
    }

    // Find the candidate's index
    int candidate_index = -1;
    for (int i = 0; i < num_candidates; i++) {
        if (strcmp(candidates[i].name, candidate_name) == 0) {
            candidate_index = i;
            break;
        }
    }

    // Increment the candidate's vote count
    candidates[candidate_index].votes++;

    // Mark the voter as having voted
    voters[voter_index].voted = 1;
}

void print_results() {
    printf("\nElection Results:\n");
    for (int i = 0; i < num_candidates; i++) {
        printf("%s: %d votes\n", candidates[i].name, candidates[i].votes);
    }
    printf("\n");
}

