  bool is_rtl;
};

static const LanguageInfo kAcceptLanguageList[] = {
  {"am", false},     // Amharic
  {"ar", true},     // Arabic
  {"bn", false},     // Bengali
  {"el", false},     // Greek
  {"en", false},     // English
  {"fa", true},     // Persian
