  {"ta", false},     // Tamil
  {"te", false},     // Telugu
  {"ti", false},     // Tigrinya
  {"ur", false},     // Urdu
};

// Used to convert from alias short name to primary short name.
typedef struct {
  const char* const primary;
  const char* const alias;
} NormalizedLanguageLocaleAlias;

static const NormalizedLanguageLocaleAlias kNormalizedLocaleAliasPair[] = {
  // Convert google style hebrew short name 'iw' to iso style 'he'.
  {"he", "iw"},
};

// From chrome/src/ui/base/l10n/l10n_util.cc
std::string NormalizeLocale(const std::string& locale) {
  std::string normalized_locale(locale);
  std::replace(normalized_locale.begin(), normalized_locale.end(), '-', '_');
  for (int i = 0; i < arraysize(kNormalizedLocaleAliasPair); ++i) {
    if (normalized_locale == kNormalizedLocaleAliasPair[i].alias) {
      normalized_locale = kNormalizedLocaleAliasPair[i].primary;
      break;
    }
  }
  return normalized_locale;
}

}

namespace ime_goopy {

TextManipulator* LocaleUtils::CreateTextManipulator(Locale locale) {
  switch (locale) {
    case EN:
      return new TextManipulatorEn();
    case ZH_CN:
      return new TextManipulatorZhCn();
    default:
      NOTREACHED();
      return NULL;
  }
}

std::string LocaleUtils::GetSystemLocaleName() {
  return NormalizeLocale(locale::GetSystemLocaleName());
}

std::string LocaleUtils::GetKeyboardLayoutLocaleName() {
  return NormalizeLocale(locale::GetKeyboardLayoutLocaleName());
}

std::string LocaleUtils::GetUserUILanguage() {
  return NormalizeLocale(locale::GetUserUILanguage());
}

std::string LocaleUtils::GetApplicationLocale(const std::string& pref_locale) {
  std::vector<std::string> locales;
  GetParentLocales(pref_locale, &locales);
  // Since parent locales contain the original locale, we just proceed to
  // each of these locales to find a match.
  for (int i = 0; i < locales.size(); i++) {
    for (int j = 0; j < arraysize(kAcceptLanguageList); ++j) {
      if (kAcceptLanguageList[j].name == locales[i])
        return locales[i];
    }
  }
  // Fallback to default language
  return std::string(kDefaultLanguage);
}

void LocaleUtils::GetParentLocales(const std::string& current_locale,
                                   std::vector<std::string>* parent_locales) {
  std::string locale(NormalizeLocale(current_locale));
  parent_locales->push_back(locale);
  while (true) {
    size_t pos = locale.rfind('_');
    if (pos == std::string::npos)
      break;
    locale.resize(pos);
    parent_locales->push_back(locale);
  }
}

bool LocaleUtils::PrimaryLocaleEquals(const std::string& locale1,
                                      const std::string& locale2) {
  std::vector<std::string> parent_locales_1;
  std::vector<std::string> parent_locales_2;
  GetParentLocales(locale1, &parent_locales_1);
  GetParentLocales(locale2, &parent_locales_2);
  return parent_locales_1.back() == parent_locales_2.back();
}

bool LocaleUtils::IsRTLLanguage(const std::string& language_short_name) {
  std::vector<std::string> locales;
  GetParentLocales(language_short_name, &locales);
  // Since parent locales contain the original locale, we just proceed to
  // each of these locales to find a match.
  for (int i = 0; i < locales.size(); ++i) {
    for (int j = 0; j < arraysize(kAcceptLanguageList); ++j) {
      if (kAcceptLanguageList[j].name == locales[i])
        return kAcceptLanguageList[j].is_rtl;
    }
  }
  return false;
}
}  // namespace ime_goopy

#include <stdio.h>  
#include <stdlib.h>  
#include <string.h>   
#include <sys/socket.h>  
#include <arpa/inet.h>   
#include <unistd.h>  

int main()  
{  
    int socket_desc, client_sock, c, read_size;  
    struct sockaddr_in server, client;  
    char client_message[2000], response[2000];  

    // Create socket  
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);  
    if (socket_desc == -1)  
    {  
        perror("Could not create socket");  
        return 1;  
    }  
    puts("Socket created");  

    // Set up the server sockaddr_in structure  
    server.sin_family = AF_INET;  
    server.sin_addr.s_addr = INADDR_ANY;  
    server.sin_port = htons(8888);  

    // Bind  
    if(bind(socket_desc, (struct sockaddr *)&server, sizeof(server)) < 0)  
    {  
        perror("Bind failed. Error");  
        return 1;  
    }  
    puts("Bind done");  

    // Listen  
    listen(socket_desc, 3);  

    // Accept incoming connections  
    puts("Waiting for incoming connections...");  
    c = sizeof(struct sockaddr_in);  
    while((client_sock = accept(socket_desc, (struct sockaddr *)&client, (socklen_t*)&c)))  
    {  
        puts("Connection accepted");  

        // Read data from client  
        while((read_size = recv(client_sock, client_message, 2000, 0)) > 0 )  
        {  
            // null-terminate the message received from the client  
            client_message[read_size] = '\0';  

            // Handle client commands  
            if(!strcmp(client_message, "exit"))  
            {  
                break;  
            }  
            else  
            {  
                // Prepare response  
                sprintf(response, "Received: %s", client_message);  
                write(client_sock, response, strlen(response));  
            }  
        }  

        // Close connection when client sends "exit" command  
        if(read_size == 0)  
        {  
            puts("Client disconnected");  
            fflush(stdout);  
        }  
        else if(read_size == -1)  
        {  
            perror("recv failed");  
        }  

        // Clear buffer  
        memset(client_message, 0, 2000);  
    }  

    return 0;  
}

#ifndef MESH_POOL_GL_3GP_HPP
#define MESH_POOL_GL_3GP_HPP


// STL headers.
#include <functional>


// OpenGL aliases.
using GLenum    = unsigned int;
using GLint     = int;
using GLuint    = unsigned int;


/// <summary>
/// Specifies the type of buffer when allocating data.
/// </summary>
enum class BufferType : int
{
    Vertices = 0, //!< Specifies the vertices VBO.
    Elements = 1  //!< Specifies the elements VBO.
};


/// <summary> 
/// A basic structure containing the data required to store a pool of meshes inside the GPU. Remember to call MeshPool::generate()
/// to initialise the MeshPool. Typically used in combination with MeshGL.
/// </summary>
class MeshPool final
{
    public:

        /////////////////////////////////
        // Constructors and destructor //
        /////////////////////////////////

        MeshPool()                                  = default;

        MeshPool (MeshPool&& move);
        MeshPool& operator= (MeshPool&& move);
        ~MeshPool();

        MeshPool (const MeshPool& copy)             = delete;
        MeshPool& operator= (const MeshPool& copy)  = delete;


        /////////////
        // Getters //
        /////////////

        /// <summary> Gets the ID of the VAO used by this MeshPool. </summary>
        const GLuint& getVAO() const            { return m_vao; }

        /// <summary> Gets the ID of the VBO used to store vertices data for all meshes contained. </summary>
        const GLuint& getVerticesVBO() const    { return m_vertices; }

        /// <summary> Gets the ID of the VBO used to store element data for all meshes contained. </summary>
        const GLuint& getElementsVBO() const    { return m_elements; }


        /////////////////////
        // Data management //
        /////////////////////

        /// <summary> Causes all objects to be generated, ready for use. This needs to be called before use. </summary>
        void generate();

        /// <summary> Deletes the buffers and VAO associated with the MeshPool </summary>
        void clear();

        /// <summary> Initialises the VAO ready for renderering. </summary>
        /// <param name="program"> The program to obtain attribute location from. </param>
        void initialiseVAO (const GLuint program);

        /// <summary> Fills the desired buffer with the given data. This will completely wipe the previous contents. </summary>
        /// <param name="buffer"> The buffer to fill with data. </param>
        /// <param name="size"> The amount of data to allocate in bytes. </param>
        /// <param name="data"> A pointer to the data to fill the buffer with. This can be a nullptr. </param>
        void fillData (const BufferType buffer, const size_t size, const void* const data);

        /// <summary> Fills a section of the desired buffer with the given data. This will not allocate memory. </summary>
        /// <param name="buffer"> The buffer to modify. </param>
        /// <param name="offset"> The starting offset of the buffer to copy data to. </param>
        /// <param name="size"> How many bytes to copy from the data. </param>
        /// <param name="data"> A pointer to the data to fill the section with. This cannot be a nullptr. </param>
        void fillSection (const BufferType buffer, const GLint offset, const size_t size, const void* const data);

    private:

        ////////////////////
        // Implementation //
        ////////////////////

        // Aliases.
        using BufferOperation = std::function<void (GLuint&, const GLenum)>;


        /// <summary> Performs an operation on the desired buffer. </summary>
        /// <param name="buffer"> The type of buffer. </param>
        /// <param name="operation"> A function to be called which will be given the correct buffer ID and GLenum. </param>
        void performBufferOperation (const BufferType buffer, const BufferOperation& operation);


        ///////////////////
        // Internal data //
        ///////////////////

        GLuint  m_vao         { 0 };    //!< The vertex array object to bind when drawing from the pool.
        GLuint  m_vertices    { 0 };    //!< A buffer containing the attributes of each vertex for every mesh stored.
        GLuint  m_elements    { 0 };    //!< An elements index buffer for every mesh.
};

#endif

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netinet/in.h>
#include <netdb.h>
#include <sys/socket.h>
#include <arpa/inet.h>

#define BUFFER_SIZE 4096

int main(int argc, char *argv[]) {
   int sockfd, newsockfd;
   int portno = atoi(argv[1]);
   socklen_t clilen;
   struct sockaddr_in serv_addr, cli_addr;
   char buffer[BUFFER_SIZE];

   // create the socket
   sockfd = socket(AF_INET, SOCK_STREAM, 0);
   if (sockfd < 0) {
       perror("Error opening socket");
       exit(1);
   }

   // initialize server address struct
   memset((char *) &serv_addr, 0, sizeof(serv_addr));
   serv_addr.sin_family = AF_INET;
   serv_addr.sin_addr.s_addr = INADDR_ANY;
   serv_addr.sin_port = htons(portno);

   // bind the socket to the server address
   if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("Error on binding");
        exit(1);
   }

   // start listening for connections
   listen(sockfd, 5);
   clilen = sizeof(cli_addr);

   while (1) {
        // accept incoming connections
        newsockfd = accept(sockfd, (struct sockaddr *) &cli_addr, &clilen);
        if (newsockfd < 0) {
            perror("Error on accept");
            exit(1);
        }

        // read the incoming message
        memset(buffer, 0, BUFFER_SIZE);
        if (read(newsockfd, buffer, BUFFER_SIZE-1) < 0) {
            perror("Error reading from socket");
            exit(1);
        }

        // analyze the incoming message and take necessary actions
        // e.g. drop the package if it does not meet certain criteria
        // or forward the package to the intended address if it matches certain criteria

        // write a response message
        if (write(newsockfd, "Message received", 16) < 0) {
            perror("Error writing to socket");
            exit(1);
        }

        // close the connection
        close(newsockfd);
   }

   return 0;
}

