void CAppParamParser::EnableDebugMode()
{
  g_advancedSettings.m_logLevel     = LOG_LEVEL_DEBUG;
  g_advancedSettings.m_logLevelHint = LOG_LEVEL_DEBUG;
  CLog::SetLogLevel(g_advancedSettings.m_logLevel);
}

void CAppParamParser::ParseArg(const std::string &arg)
{
  if (arg == "-fs" || arg == "--fullscreen")
    g_advancedSettings.m_startFullScreen = true;
  else if (arg == "-h" || arg == "--help")
    DisplayHelp();
  else if (arg == "-v" || arg == "--version")
    DisplayVersion();
  else if (arg == "--standalone")
    g_application.SetStandAlone(true);
  else if (arg == "-p" || arg  == "--portable")
    g_application.EnablePlatformDirectories(false);
  else if (arg == "--debug")
    EnableDebugMode();
  else if (arg == "--legacy-res")
    g_application.SetEnableLegacyRes(true);
  else if (arg == "--test")
    m_testmode = true;
  else if (arg.substr(0, 11) == "--settings=")
    g_advancedSettings.AddSettingsFile(arg.substr(11));
  else if (arg.length() != 0 && arg[0] != '-')
  {
    if (m_testmode)
      g_application.SetEnableTestMode(true);

    CFileItemPtr pItem(new CFileItem(arg));
    pItem->SetPath(arg);

    m_playlist.Add(pItem);
  }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MIN_X 0
#define MAX_X 10
#define MIN_Y 0
#define MAX_Y 10

#define SURVIVAL_RATE 0.5
#define HUNGER_RATE 0.2
#define THIRST_RATE 0.3

struct player {
    int x;
    int y;
    int health;
    int hunger;
    int thirst;
};

void update_player(struct player *player) {
    int hunger_change = player->hunger * HUNGER_RATE;
    int thirst_change = player->thirst * THIRST_RATE;

    player->hunger += hunger_change;
    player->thirst += thirst_change;

    if (player->hunger < 0) {
        player->hunger = 0;
    }

    if (player->thirst < 0) {
        player->thirst = 0;
    }

    player->health -= player->hunger * 0.1;
    player->health -= player->thirst * 0.1;
}

void render_game(struct player *player) {
    printf("---------------------------------\n");
    printf("Statistics Survival Game\n");
    printf("---------------------------------\n");
    printf("Health: %d\n", player->health);
    printf("Hunger: %d\n", player->hunger);
    printf("Thirst: %d\n", player->thirst);
    printf("X: %d\n", player->x);
    printf("Y: %d\n", player->y);
    printf("\n");
}

void handle_input(struct player *player, char input) {
    switch (input) {
        case 'w':
            player->y--;
            break;
        case 's':
            player->y++;
            break;
        case 'a':
            player->x--;
            break;
        case 'd':
            player->x++;
            break;
        case 'q':
            exit(0);
            break;
    }
}

int main() {
    srand(time(NULL));

    struct player player;
    player.x = (rand() % (MAX_X - MIN_X)) + MIN_X;
    player.y = (rand() % (MAX_Y - MIN_Y)) + MIN_Y;
    player.health = 100;
    player.hunger = 50;
    player.thirst = 50;

    while (1) {
        update_player(&player);
        render_game(&player);

        char input = getchar();
        handle_input(&player, input);
    }

    return 0;
}

