            printf("Begin the game!\n");

            // Guess the numbers
            printf("%s, guess the number of %s: ", b, c);
            scanf("%d", &n);

            if (n == d)
            {
                printf("%s won!\n", b);
            }
            else
            {
                printf("%s lost.\n", b);
            }

            break;

        default:
            printf("Invalid number of players.\n");
    }

    return 0;
}

