#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
  int room_number;
  char *room_type;
  double price;
} Room;

typedef struct {
  char *first_name;
  char *last_name;
  char *email;
  char *phone_number;
} Guest;

typedef struct {
  Room *room;
  Guest *guest;
  int check_in_date;
  int check_out_date;
} Reservation;

typedef struct {
  Reservation *reservations;
  int num_reservations;
} Hotel;

void create_hotel(Hotel *hotel) {
  hotel->reservations = malloc(sizeof(Reservation) * 100);
  hotel->num_reservations = 0;
}

void add_room(Hotel *hotel, Room *room) {
  hotel->reservations[hotel->num_reservations].room = room;
  hotel->num_reservations++;
}

void add_guest(Hotel *hotel, Guest *guest) {
  hotel->reservations[hotel->num_reservations].guest = guest;
  hotel->num_reservations++;
}

void add_reservation(Hotel *hotel, Reservation *reservation) {
  hotel->reservations[hotel->num_reservations] = *reservation;
  hotel->num_reservations++;
}

void print_hotel(Hotel *hotel) {
  for (int i = 0; i < hotel->num_reservations; i++) {
    printf("Reservation %d\n", i + 1);
    printf("Room: %s\n", hotel->reservations[i].room->room_type);
    printf("Guest: %s %s\n", hotel->reservations[i].guest->first_name, hotel->reservations[i].guest->last_name);
    printf("Check-in date: %d\n", hotel->reservations[i].check_in_date);
    printf("Check-out date: %d\n\n", hotel->reservations[i].check_out_date);
  }
}

int main() {
  Hotel hotel;
  create_hotel(&hotel);

  Room room1;
  room1.room_number = 101;
  room1.room_type = "Standard";
  room1.price = 100.0;

  Guest guest1;
  guest1.first_name = "John";
  guest1.last_name = "Doe";
  guest1.email = "john.doe@example.com";
  guest1.phone_number = "555-123-4567";

  Reservation reservation1;
  reservation1.room = &room1;
  reservation1.guest = &guest1;
  reservation1.check_in_date = 20230301;
  reservation1.check_out_date = 20230303;

  add_reservation(&hotel, &reservation1);

  print_hotel(&hotel);

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Appointment {
    char name[50];
    char date[10];
    char time[10];
    struct Appointment* next;
} Appointment;

void schedule_appointment(Appointment* head) {
    // Allocate memory for a new appointment
    Appointment* new_app = (Appointment*)malloc(sizeof(Appointment));

    // Get the user's name, date, and time
    printf("Enter your name: ");
    scanf("%s", new_app->name);

    printf("Enter the date of your appointment (MM/DD/YY): ");
    scanf("%s", new_app->date);

    printf("Enter the time of your appointment (HH:MM): ");
    scanf("%s", new_app->time);

    // Link the new appointment to the head of the list
    if (head == NULL) {
        head = new_app;
    } else {
        new_app->next = head;
        head = new_app;
    }
}

void print_appointments(Appointment* head) {
    // Traverse the list of appointments
    while (head) {
        // Print the appointment details
        printf("Name: %s\n", head->name);
        printf("Date: %s\n", head->date);
        printf("Time: %s\n", head->time);
        printf("\n");
        head = head->next;
    }
}

int main() {
    // Create a head of the appointment list
    Appointment* head = NULL;

    // Schedule an appointment
    schedule_appointment(head);

    // Print the appointments
    print_appointments(head);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_CITIES 10
#define MAX_DAYS 7

struct City {
    char name[30];
    int temperature[MAX_DAYS];
};

struct City cities[MAX_CITIES];

void generateRandomWeather(int cityIndex) {
    srand(time(NULL));
    for (int i = 0; i < MAX_DAYS; i++) {
        cities[cityIndex].temperature[i] = rand() % 41 - 20;
    }
}

void printCityWeather(int cityIndex) {
    printf("City: %s\n", cities[cityIndex].name);
    for (int i = 0; i < MAX_DAYS; i++) {
        printf("Day %d: %dC\n", i + 1, cities[cityIndex].temperature[i]);
    }
}

int main() {
    int numCities;
    printf("Enter the number of cities: ");
    scanf("%d", &numCities);

    for (int i = 0; i < numCities; i++) {
        printf("Enter city name: ");
        scanf("%s", cities[i].name);
        generateRandomWeather(i);
    }

    int numDays;
    printf("Enter the number of days to simulate: ");
    scanf("%d", &numDays);

    for (int i = 0; i < numDays; i++) {
        for (int j = 0; j < numCities; j++) {
            printCityWeather(j);
        }
    }

    return 0;
}

#include <stdio.h>
#include <string.h>

typedef struct {
    char name[100];
    int account_no;
    float balance;
} Account;

int main() {
    Account accounts[100];
    int i, j, num_accounts;
    float deposit, withdrawal;

    printf("Enter number of accounts: ");
    scanf("%d", &num_accounts);
    for (i = 0; i < num_accounts; i++) {
        printf("Enter account details for account %d:\n", i+1);
        printf("Name: ");
        fgets(accounts[i].name, sizeof(accounts[i].name), stdin);
        accounts[i].account_no = i+1;
        printf("Balance: ");
        scanf("%f", &accounts[i].balance);
        printf("\n");
    }

    printf("Select operation: \n1. Deposit\n2. Withdrawal\n3. Show balance\n4. Exit\n");
    scanf("%d", &j);
    switch (j) {
        case 1:
            printf("Enter deposit amount: ");
            scanf("%f", &deposit);
            for (i = 0; i < num_accounts; i++) {
                accounts[i].balance += deposit;
            }
            break;
        case 2:
            printf("Enter withdrawal amount: ");
            scanf("%f", &withdrawal);
            for (i = 0; i < num_accounts; i++) {
                if (accounts[i].balance >= withdrawal) {
                    accounts[i].balance -= withdrawal;
                    printf("Withdrawal successful.\n");
                } else {
                    printf("Insufficient funds.\n");
                }
            }
            break;
        case 3:
            for (i = 0; i < num_accounts; i++) {
                printf("%d. Account %s has balance of %.2f.\n", i+1, accounts[i].name, accounts[i].balance);
            }
            break;
        case 4:
            printf("Exiting program.\n");
            break;
        default:
            printf("Invalid option. Please select a valid option.\n");
            break;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PROCESSES 5

typedef struct Process {
    int process_id;
    char status;
    int burst_time;
    int waiting_time;
    int turnaround_time;
} Process;

void schedule(Process *processes, int num_processes) {
    processes[0].status = 'R';
    time_t start_time = time(NULL);
    while (processes[0].burst_time > 0) {
        processes[0].burst_time--;
        time_t end_time = time(NULL);
        processes[0].waiting_time++;
        printf("Process %d is running...\n", processes[0].process_id);
        sleep(1);
    }
    processes[0].status = 'C';
    processes[0].turnaround_time = processes[0].waiting_time + 1;
    for (int i = 1; i < num_processes; i++) {
        processes[i].status = 'R';
        processes[i].burst_time--;
        time_t end_time = time(NULL);
        processes[i].waiting_time++;
        printf("Process %d is running...\n", processes[i].process_id);
        sleep(1);
    }
    for (int i = 0; i < num_processes; i++) {
        printf("Process %d waiting time: %d\n", processes[i].process_id, processes[i].waiting_time);
        printf("Process %d turnaround time: %d\n", processes[i].process_id, processes[i].turnaround_time);
    }
}

int main() {
    Process processes[MAX_PROCESSES];
    for (int i = 0; i < MAX_PROCESSES; i++) {
        processes[i].process_id = i + 1;
        processes[i].burst_time = rand() % 5 + 1;
    }

    schedule(processes, MAX_PROCESSES);

    return 0;
}

