#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define BOARD_SIZE 10
#define NUM_INVADERS 5

typedef struct invader {
  int x;
  int y;
  int direction;
  int speed;
} Invader;

Invader invaders[NUM_INVADERS];

void initialize_invaders() {
  for (int i = 0; i < NUM_INVADERS; i++) {
    invaders[i].x = i;
    invaders[i].y = 0;
    invaders[i].direction = 1;
    invaders[i].speed = 1;
  }
}

void move_invaders() {
  for (int i = 0; i < NUM_INVADERS; i++) {
    switch (invaders[i].direction) {
      case 1:
        invaders[i].x++;
        break;
      case 2:
        invaders[i].x--;
        break;
      case 3:
        invaders[i].y++;
        break;
      case 4:
        invaders[i].y--;
        break;
    }

    if (invaders[i].x >= BOARD_SIZE - 1) {
      invaders[i].direction = 2;
    } else if (invaders[i].x <= 0) {
      invaders[i].direction = 1;
    }

    if (invaders[i].y >= BOARD_SIZE - 1) {
      invaders[i].direction = 4;
    } else if (invaders[i].y <= 0) {
      invaders[i].direction = 3;
    }
  }
}

int main() {
  initialize_invaders();

  for (int i = 0; i < 100; i++) {
    move_invaders();
  }

  return 0;
}

// TestValues.cpp : Test XML encoding and decoding of XmlRpcValues.

#include <stdlib.h>

#include "XmlRpcValue.h"


#include <assert.h>
#include <iostream>


using namespace XmlRpc;


void testBoolean()
{
  XmlRpcValue booleanFalse(false);
  XmlRpcValue booleanTrue(true);
  int offset = 0;
  XmlRpcValue booleanFalseXml("<value><boolean>0</boolean></value>", &offset);
  offset = 0;
  XmlRpcValue booleanTrueXml("<value><boolean>1</boolean></value>", &offset);
  assert(booleanFalse != booleanTrue);
  assert(booleanFalse == booleanFalseXml);
  assert(booleanFalse != booleanTrueXml);

  if (bool(booleanFalse))
    assert(false);

  if ( ! bool(booleanTrue))
    assert(false);
}

// Int
void testInt()
{
  XmlRpcValue int0(0);
  XmlRpcValue int1(1);
  XmlRpcValue int10(10);
  XmlRpcValue int_1(-1);
  int offset = 0;
  XmlRpcValue int0Xml("<value><int>0</int></value>", &offset);
  offset = 0;
  XmlRpcValue int9Xml("<value><i4>9</i4></value>", &offset);
  assert(int0 == int0Xml);
  assert(int(int10) - int(int1) == int(int9Xml));
  assert(9 == int(int9Xml));
  assert(int(int10) + int(int_1) == int(int9Xml));
}

void testDouble()
{
  // Double
  XmlRpcValue d(43.7);
  int offset = 0;
  XmlRpcValue dXml("<value><double>56.3</double></value>", &offset);
  assert(double(d) + double(dXml) == 100.0);  // questionable practice...
}

void testString()
{
  // String
  XmlRpcValue s("Now is the time <&");
  char csxml[] = "<value><string>Now is the time &lt;&amp;</string></value>";
  std::string ssxml = csxml;
  int offset = 0;
  XmlRpcValue vscXml(csxml, &offset);
  offset = 0;
  XmlRpcValue vssXml(ssxml, &offset);
  assert(s == vscXml);
  assert(s == vssXml);
  offset = 0;
  XmlRpcValue fromXml(vssXml.toXml(), &offset);
  assert(s == fromXml);

  // Empty or blank strings with no <string> tags
  std::string emptyStringXml("<value></value>");
  offset = 0;
  XmlRpcValue emptyStringVal1(emptyStringXml, &offset);
  XmlRpcValue emptyStringVal2("");
  assert(emptyStringVal1 == emptyStringVal2);

  emptyStringXml = "<value>  </value>";
  offset = 0;
  XmlRpcValue blankStringVal(emptyStringXml, &offset);
  assert(std::string(blankStringVal) == "  ");
}


void testDateTime()
{
  // DateTime
  int offset = 0;
  XmlRpcValue dateTime("<value><dateTime.iso8601>19040101T03:12:35</dateTime.iso8601></value>", &offset);
  struct tm &t = dateTime;
  assert(t.tm_year == 1904 && t.tm_min == 12);
}


void testArray(XmlRpcValue const& d)
{
  // Array
  XmlRpcValue a;
  a.setSize(4);
  a[0] = 1;
  a[1] = std::string("two");
  a[2] = 43.7;
  a[3] = "four";
  assert(int(a[0]) == 1);
  assert(a[2] == d);

  char csaXml[] =
    "<value><array>\n"
    "  <data>\n"
    "    <value><i4>1</i4></value> \n"
    "    <value> <string>two</string></value>\n"
    "    <value><double>43.7</double></value>\n"
    "    <value>four</value>\n"
    "  </data>\n"
    "</array></value>";

  int offset = 0;
  XmlRpcValue aXml(csaXml, &offset);
  assert(a == aXml);
}

void testStruct()
{
  // Struct
  XmlRpcValue struct1;
  struct1["i4"] = 1;
  struct1["str"] = "two";
  struct1["d"] = 43.7;

  XmlRpcValue a;
  a.setSize(4);
  a[0] = 1;
  a[1] = std::string("two");
  a[2] = 43.7;
  a[3] = "four";

  assert(struct1["d"] == a[2]);

  char csStructXml[] =
    "<value><struct>\n"
    "  <member>\n"
    "    <name>i4</name> \n"
    "    <value><i4>1</i4></value> \n"
    "  </member>\n"
    "  <member>\n"
    "    <name>d</name> \n"
    "    <value><double>43.7</double></value>\n"
    "  </member>\n"
    "  <member>\n"
    "    <name>str</name> \n"
    "    <value> <string>two</string></value>\n"
    "  </member>\n"
    "</struct></value>";

  int offset = 0;
  XmlRpcValue structXml(csStructXml, &offset);
  assert(struct1 == structXml);

  XmlRpcValue astruct;
  astruct["array"] = a;
  assert(astruct["array"][2] == struct1["d"]);

  for (int i=0; i<10; i++) {
    XmlRpcValue Event;
    Event["Name"] = "string";

    Event.clear();

    const int NELMTS = 100;
    int ii;

    for (ii=0; ii< NELMTS; ++ii) {
      char buf[40];
      sprintf(buf,"%d", ii);
      Event[std::string(buf)] = buf;
    }

    Event.clear();

    for (ii=0; ii< NELMTS; ++ii) {
      char buf[40];
      sprintf(buf,"%d", ii);
      if (ii != NELMTS/2)
        Event[std::string(buf)] = ii;
      else
        for (int jj=0; jj< NELMTS; ++jj) {
          char bufj[40];
          sprintf(bufj,"%d", jj);
          Event[std::string(buf)][std::string(bufj)] = bufj;
        }
    }

    for (ii=0; ii< NELMTS; ++ii) {
      char buf[40];
      sprintf(buf,"%d", ii);
      if (ii != NELMTS/2)
        assert(Event[std::string(buf)] == XmlRpcValue(ii));
      else
        assert(Event[std::string(buf)].size() == NELMTS);
    }
  }
}



int main(int argc, char* argv[])
{
  testBoolean();

  testInt();


  testDouble();


  testString();


  testDateTime();


  testArray(43.7);


  testStruct();

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

struct Credential {
    char *service;
    char *username;
    char *password;
};

struct CredentialManager {
    struct Credential *credentials;
    int num_credentials;
    int capacity;
};

struct CredentialManager *create_manager(int initial_capacity) {
    struct CredentialManager *manager = malloc(sizeof(struct CredentialManager));
    manager->credentials = malloc(initial_capacity * sizeof(struct Credential));
    manager->num_credentials = 0;
    manager->capacity = initial_capacity;
    return manager;
}

void destroy_manager(struct CredentialManager *manager) {
    for (int i = 0; i < manager->num_credentials; i++) {
        free(manager->credentials[i].service);
        free(manager->credentials[i].username);
        free(manager->credentials[i].password);
    }
    free(manager->credentials);
    free(manager);
}

void add_credential(struct CredentialManager *manager, char *service, char *username, char *password) {
    if (manager->num_credentials == manager->capacity) {
        manager->capacity *= 2;
        manager->credentials = realloc(manager->credentials, manager->capacity * sizeof(struct Credential));
    }
    manager->credentials[manager->num_credentials].service = strdup(service);
    manager->credentials[manager->num_credentials].username = strdup(username);
    manager->credentials[manager->num_credentials].password = strdup(password);
    manager->num_credentials++;
}

struct Credential *find_credential(struct CredentialManager *manager, char *service) {
    for (int i = 0; i < manager->num_credentials; i++) {
        if (strcmp(manager->credentials[i].service, service) == 0) {
            return &manager->credentials[i];
        }
    }
    return NULL;
}

void print_credentials(struct CredentialManager *manager) {
    for (int i = 0; i < manager->num_credentials; i++) {
        printf("%s: %s/%s\n", manager->credentials[i].service, manager->credentials[i].username, manager->credentials[i].password);
    }
}

int main() {
    struct CredentialManager *manager = create_manager(10);
    add_credential(manager, "Facebook", "johndoe", "password123");
    add_credential(manager, "Google", "janedoe", "password456");
    add_credential(manager, "Amazon", "johndoe", "password789");

    struct Credential *credential = find_credential(manager, "Facebook");
    if (credential != NULL) {
        printf("Found credential for Facebook: %s/%s\n", credential->username, credential->password);
    } else {
        printf("No credential found for Facebook\n");
    }

    print_credentials(manager);

    destroy_manager(manager);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>

#define MAX_SERVICES 50
#define CMD_LENGTH 256

typedef struct {
    char name[50];
    int priority;
    int delay; // in seconds
} Service;

Service services[MAX_SERVICES];
int serviceCount = 0;

void addService(const char* name, int priority, int delay) {
    if (serviceCount < MAX_SERVICES) {
        strncpy(services[serviceCount].name, name, sizeof(services[serviceCount].name));
        services[serviceCount].priority = priority;
        services[serviceCount].delay = delay;
        serviceCount++;
    } else {
        printf("Cannot add more services, max limit reached!\n");
    }
}

void sortServices() {
    for (int i = 0; i < serviceCount - 1; i++) {
        for (int j = 0; j < serviceCount - i - 1; j++) {
            if (services[j].priority > services[j + 1].priority) {
                Service temp = services[j];
                services[j] = services[j + 1];
                services[j + 1] = temp;
            }
        }
    }
}

void optimizeBootSequence() {
    sortServices();
    printf("Initiating Optimized Boot Sequence...\n");
    for (int i = 0; i < serviceCount; i++) {
        printf("Starting service: %s (Priority: %d) after %d seconds\n", 
               services[i].name, services[i].priority, services[i].delay);
        sleep(services[i].delay);
        // Simulate service start
        printf("Service %s is now running...\n", services[i].name);
    }
    printf("All services started successfully!\n");
}

void loadConfiguration() {
    // Simulating loading from a config file
    printf("Loading configurations...\n");
    addService("Network Manager", 1, 5);
    addService("Logging Service", 2, 2);
    addService("Database Service", 3, 3);
    addService("Web Server", 4, 4);
    addService("User Session Service", 5, 1);
}

void displayServices() {
    printf("\nLoaded Services:\n");
    for (int i = 0; i < serviceCount; i++) {
        printf("%d: %s (Priority: %d, Delay: %d seconds)\n", i + 1, 
               services[i].name, services[i].priority, services[i].delay);
    }
}

int main() {
    loadConfiguration();
    displayServices();
    optimizeBootSequence();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pcap.h>
#include <netinet/ip.h>

#define MAX_RULES 100
#define RULE_SIZE 16

typedef struct {
    char action[RULE_SIZE];
    char ip[RULE_SIZE];
} Rule;

Rule rules[MAX_RULES];
int rule_count = 0;

void add_rule(const char *action, const char *ip) {
    if (rule_count < MAX_RULES) {
        strncpy(rules[rule_count].action, action, RULE_SIZE);
        strncpy(rules[rule_count].ip, ip, RULE_SIZE);
        rule_count++;
    } else {
        printf("Maximum rule limit reached.\n");
    }
}

int check_rule(const char *packet_ip) {
    for (int i = 0; i < rule_count; i++) {
        if (strcmp(rules[i].ip, packet_ip) == 0) {
            if (strcmp(rules[i].action, "DENY") == 0) {
                return 0; // Deny the packet
            }
            if (strcmp(rules[i].action, "ALLOW") == 0) {
                return 1; // Allow the packet
            }
        }
    }
    return 1; // Default allow if no rules matched
}

void packet_handler(u_char *args, const struct pcap_pkthdr *header, const u_char *packet) {
    struct ip *ip_hdr = (struct ip *)(packet + 14); // Skip Ethernet header
    char packet_ip[INET_ADDRSTRLEN];

    inet_ntop(AF_INET, &(ip_hdr->ip_src), packet_ip, INET_ADDRSTRLEN);

    printf("Packet from IP: %s\n", packet_ip);

    if (check_rule(packet_ip)) {
        printf("Packet allowed.\n");
    } else {
        printf("Packet denied.\n");
    }
}

void initialize_rules() {
    add_rule("DENY", "192.168.1.5");
    add_rule("ALLOW", "192.168.1.100");
}

int main(int argc, char *argv[]) {
    char *dev;             // Name of the device to listen on
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;       // Handle for packet capture

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return EXIT_FAILURE;
    }

    dev = argv[1];

    initialize_rules();

    handle = pcap_open_live(dev, BUFSIZ, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Could not open device %s: %s\n", dev, errbuf);
        return EXIT_FAILURE;
    }

    pcap_loop(handle, 0, packet_handler, NULL);

    pcap_close(handle);
    return EXIT_SUCCESS;
}

