/******************************************************************************

    Start the video hardware emulation

******************************************************************************/

void gomoku_state::video_start()
{
	m_screen->register_screen_bitmap(m_bg_bitmap);

	m_fg_tilemap = &machine().tilemap().create(*m_gfxdecode, tilemap_get_info_delegate(*this, FUNC(gomoku_state::get_fg_tile_info)),TILEMAP_SCAN_ROWS,8,8,32, 32);

	m_fg_tilemap->set_transparent_pen(0);

	// make background bitmap
	m_bg_bitmap.fill(0x20);

	// board
	for (int y = 0; y < 256; y++)
	{
		for (int x = 0; x < 256; x++)
		{
			int bgdata = m_bg_d[m_bg_x[x] + (m_bg_y[y] << 4)];

			int color = 0x20;                       // outside frame (black)

			if (bgdata & 0x01) color = 0x21;    // board (brown)
			if (bgdata & 0x02) color = 0x20;    // frame line (while)

			m_bg_bitmap.pix((255 - y - 1) & 0xff, (255 - x + 7) & 0xff) = color;
		}
	}

	save_item(NAME(m_flipscreen)); // set but never used?
	save_item(NAME(m_bg_dispsw));
}


/******************************************************************************

    Display refresh

******************************************************************************/

uint32_t gomoku_state::screen_update(screen_device &screen, bitmap_ind16 &bitmap, const rectangle &cliprect)
{
	int color;

	// draw background layer
	if (m_bg_dispsw)
	{
		// copy bg bitmap
		copybitmap(bitmap, m_bg_bitmap, 0, 0, 0, 0, cliprect);

		// stone
		for (int y = 0; y < 256; y++)
		{
			for (int x = 0; x < 256; x++)
			{
				int bgoffs = ((((255 - x - 2) / 14) | (((255 - y - 10) / 14) << 4)) & 0xff);

				int bgdata = m_bg_d[m_bg_x[x] + (m_bg_y[y] << 4) ];
				int bgram = m_bgram[bgoffs];

				if (bgdata & 0x04)
				{
					if (bgram & 0x01)
					{
						color = 0x2f;   // stone (black)
					}
					else if (bgram & 0x02)
					{
						color = 0x22;   // stone (white)
					}
					else continue;
				}
				else continue;

				bitmap.pix((255 - y - 1) & 0xff, (255 - x + 7) & 0xff) = color;
			}
		}

		// cursor
		for (int y = 0; y < 256; y++)
		{
			for (int x = 0; x < 256; x++)
			{
				int bgoffs = ((((255 - x - 2) / 14) | (((255 - y - 10) / 14) << 4)) & 0xff);

				int bgdata = m_bg_d[m_bg_x[x] + (m_bg_y[y] << 4) ];
				int bgram = m_bgram[bgoffs];

				if (bgdata & 0x08)
				{
					if (bgram & 0x04)
					{
						color = 0x2f;   // cursor (black)
					}
					else if (bgram & 0x08)
					{
						color = 0x22;       // cursor (white)
					}
					else continue;
				}
				else continue;

				bitmap.pix((255 - y - 1) & 0xff, (255 - x + 7) & 0xff) = color;
			}
		}
	}
	else
	{
		bitmap.fill(0x20);
	}

	m_fg_tilemap->draw(screen, bitmap, cliprect, 0, 0);
	return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/wait.h>

// Recursive function to create a shared memory segment and store a message in it.
int create_shared_memory(int depth, int key) {
  // Create the shared memory segment.
  int shmid = shmget(key, 1024, IPC_CREAT | 0666);
  if (shmid == -1) {
    perror("shmget");
    return -1;
  }

  // Attach the shared memory segment to the current process.
  void *shmaddr = shmat(shmid, NULL, 0);
  if (shmaddr == (void *)-1) {
    perror("shmat");
    return -1;
  }

  // Store the message in the shared memory segment.
  char *message = "Hello from depth ";
  sprintf(shmaddr, "%s%d", message, depth);

  // Detach the shared memory segment from the current process.
  if (shmdt(shmaddr) == -1) {
    perror("shmdt");
    return -1;
  }

  // If the depth is greater than 0, create a child process and call the function recursively.
  if (depth > 0) {
    pid_t pid = fork();
    if (pid == -1) {
      perror("fork");
      return -1;
    } else if (pid == 0) {
      // Child process.
      int new_depth = depth - 1;
      int new_key = key + 1;
      int status = create_shared_memory(new_depth, new_key);
      exit(status);
    } else {
      // Parent process.
      int status;
      waitpid(pid, &status, 0);
      if (WEXITSTATUS(status) != 0) {
        return -1;
      }
    }
  }

  return 0;
}

// Recursive function to read the message from the shared memory segment and print it.
int read_shared_memory(int depth, int key) {
  // Attach the shared memory segment to the current process.
  int shmid = shmget(key, 1024, 0);
  if (shmid == -1) {
    perror("shmget");
    return -1;
  }

  // Attach the shared memory segment to the current process.
  void *shmaddr = shmat(shmid, NULL, 0);
  if (shmaddr == (void *)-1) {
    perror("shmat");
    return -1;
  }

  // Read the message from the shared memory segment.
  char *message = (char *)shmaddr;
  printf("%s\n", message);

  // Detach the shared memory segment from the current process.
  if (shmdt(shmaddr) == -1) {
    perror("shmdt");
    return -1;
  }

  // If the depth is greater than 0, create a child process and call the function recursively.
  if (depth > 0) {
    pid_t pid = fork();
    if (pid == -1) {
      perror("fork");
      return -1;
    } else if (pid == 0) {
      // Child process.
      int new_depth = depth - 1;
      int new_key = key + 1;
      int status = read_shared_memory(new_depth, new_key);
      exit(status);
    } else {
      // Parent process.
      int status;
      waitpid(pid, &status, 0);
      if (WEXITSTATUS(status) != 0) {
        return -1;
      }
    }
  }

  return 0;
}

int main() {
  // Create the shared memory segment and store a message in it.
  int depth = 10;
  int key = 1234;
  int status = create_shared_memory(depth, key);
  if (status != 0) {
    return status;
  }

  // Read the message from the shared memory segment and print it.
  status = read_shared_memory(depth, key);
  if (status != 0) {
    return status;
  }

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_PROCESSES 10

typedef struct {
    int id;
    int burstTime;
    int waitingTime;
    int turnaroundTime;
} Process;

void printProcess(Process p) {
    printf("🎉 Process %d | Burst Time: %d | Waiting Time: %d | Turnaround Time: %d\n", 
           p.id, p.burstTime, p.waitingTime, p.turnaroundTime);
}

void calculateWaitingTimeFCFS(Process processes[], int n) {
    processes[0].waitingTime = 0;
    for (int i = 1; i < n; i++) {
        processes[i].waitingTime = processes[i - 1].waitingTime + processes[i - 1].burstTime;
    }
}

void calculateTurnaroundTimeFCFS(Process processes[], int n) {
    for (int i = 0; i < n; i++) {
        processes[i].turnaroundTime = processes[i].waitingTime + processes[i].burstTime;
    }
}

void fcfsScheduling(Process processes[], int n) {
    printf("✨ First-Come-First-Serve Scheduling! 🎊\n");
    calculateWaitingTimeFCFS(processes, n);
    calculateTurnaroundTimeFCFS(processes, n);

    printf("\nHere are the results:\n");
    for (int i = 0; i < n; i++) {
        printProcess(processes[i]);
    }
}

void sjfScheduling(Process processes[], int n) {
    printf("✨ Shortest Job First Scheduling! 🎊\n");
    // Sort processes based on burst time
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (processes[j].burstTime > processes[j + 1].burstTime) {
                Process temp = processes[j];
                processes[j] = processes[j + 1];
                processes[j + 1] = temp;
            }
        }
    }
    calculateWaitingTimeFCFS(processes, n);
    calculateTurnaroundTimeFCFS(processes, n);

    printf("\nHere are the results:\n");
    for (int i = 0; i < n; i++) {
        printProcess(processes[i]);
    }
}

void roundRobinScheduling(Process processes[], int n, int quantum) {
    printf("✨ Round Robin Scheduling! 🎊\n");
    int remainingBurst[MAX_PROCESSES];
    for (int i = 0; i < n; i++) {
        remainingBurst[i] = processes[i].burstTime;
    }

    int time = 0;
    while (1) {
        int done = 1; // Flag to check if all processes are done
        for (int i = 0; i < n; i++) {
            if (remainingBurst[i] > 0) {
                done = 0; // There are more processes
                if (remainingBurst[i] > quantum) {
                    time += quantum;
                    remainingBurst[i] -= quantum;
                } else {
                    time += remainingBurst[i];
                    processes[i].waitingTime = time - processes[i].burstTime;
                    remainingBurst[i] = 0; 
                }
            }
        }
        if (done) break;
    }

    calculateTurnaroundTimeFCFS(processes, n);

    printf("\nHere are the results:\n");
    for (int i = 0; i < n; i++) {
        printProcess(processes[i]);
    }
}

int main() {
    Process processes[MAX_PROCESSES];
    int n, quantum;

    printf("🎈 Welcome to the CPU Scheduling Simulator! 🎈\n");
    printf("Enter the number of processes (max %d): ", MAX_PROCESSES);
    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        processes[i].id = i + 1;
        printf("Enter the burst time for Process %d: ", processes[i].id);
        scanf("%d", &processes[i].burstTime);
    }

    printf("\n*** Choose a scheduling algorithm ***\n");
    printf("1. First-Come-First-Serve\n");
    printf("2. Shortest Job First\n");
    printf("3. Round Robin\n");
    int choice;
    printf("Enter your choice (1/2/3): ");
    scanf("%d", &choice);

    if (choice == 1) {
        fcfsScheduling(processes, n);
    } else if (choice == 2) {
        sjfScheduling(processes, n);
    } else if (choice == 3) {
        printf("Enter time quantum for Round Robin: ");
        scanf("%d", &quantum);
        roundRobinScheduling(processes, n, quantum);
    } else {
        printf("🚫 Invalid choice! Please restart the program. 🚫\n");
    }

    printf("🎉 Thank you for using the CPU Scheduling Simulator! Goodbye! 🎊\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_FORTUNE 100
#define MAX_LENGTH 80

// structure to hold each fortune
typedef struct {
    char text[MAX_LENGTH];
    int length;
} fortune;

// function prototypes
void load_fortunes(fortune *fortunes);
int pick_random_fortune(fortune *fortunes, int num_fortunes);

int main(int argc, char *argv[]) {
    fortune fortunes[MAX_FORTUNE];
    load_fortunes(fortunes);

    int num_fortunes = sizeof(fortunes) / sizeof(fortunes[0]);
    int choice;

    printf("Welcome to the Automated Fortune Teller!\n");
    printf("Inspired by Romeo and Juliet.\n");
    printf("How many fortunes would you like to hear? ");
    scanf("%d", &choice);

    if (choice < 1 || choice > num_fortunes) {
        printf("Invalid choice.\n");
        return 1;
    }

    for (int i = 0; i < choice; i++) {
        int index = pick_random_fortune(fortunes, num_fortunes);
        printf("\nFortune #%d:\n%s\n", i+1, fortunes[index].text);
    }

    return 0;
}

// load fortunes from a file
void load_fortunes(fortune *fortunes) {
    FILE *fp;
    char line[MAX_LENGTH];
    int count = 0;

    fp = fopen("fortunes.txt", "r");
    if (fp == NULL) {
        printf("Error opening fortunes file.\n");
        exit(1);
    }

    while (fgets(line, MAX_LENGTH, fp)!= NULL) {
        if (count >= MAX_FORTUNE) {
            printf("Too many fortunes in file.\n");
            exit(1);
        }
        strcpy(fortunes[count].text, line);
        fortunes[count].length = strlen(line);
        count++;
    }

    fclose(fp);
}

// pick a random fortune from the array
int pick_random_fortune(fortune *fortunes, int num_fortunes) {
    return rand() % num_fortunes;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>

#define KEY_SIZE 16
#define BLOCK_SIZE 16
#define MAX_MESSAGE_SIZE 1024

typedef struct {
    char key[KEY_SIZE];
    char message[MAX_MESSAGE_SIZE];
} message_t;

void init_key(message_t *message);
void encrypt(message_t *message);
void decrypt(message_t *message);

int main() {
    message_t message;
    char encrypted_message[MAX_MESSAGE_SIZE];

    // Generate a random key
    srand(time(NULL));
    for (int i = 0; i < KEY_SIZE; i++) {
        message.key[i] = (char)rand() % 26 + 'A';
    }

    // Set the message
    strcpy(message.message, "This is a secret message");

    // Encrypt the message
    encrypt(&message);

    // Print the encrypted message
    printf("Encrypted message: %s\n", encrypted_message);

    // Decrypt the message
    decrypt(&message);

    // Print the decrypted message
    printf("Decrypted message: %s\n", message.message);

    return 0;
}

void init_key(message_t *message) {
    // Generate a random key
    srand(time(NULL));
    for (int i = 0; i < KEY_SIZE; i++) {
        message->key[i] = (char)rand() % 26 + 'A';
    }
}

void encrypt(message_t *message) {
    int i, j, k;
    char temp;

    // Loop through each block of the message
    for (i = 0; i < strlen(message->message); i += BLOCK_SIZE) {
        // Calculate the key schedule
        for (j = 0; j < BLOCK_SIZE; j++) {
            temp = message->key[i + j];
            message->key[i + j] = message->key[i + j + 1];
            message->key[i + j + 1] = temp;
        }

        // Encrypt the block
        for (k = 0; k < BLOCK_SIZE; k++) {
            temp = message->message[i + k];
            message->message[i + k] = (temp + message->key[i + k]) % 26 + 'A';
        }
    }
}

void decrypt(message_t *message) {
    int i, j, k;
    char temp;

    // Loop through each block of the message
    for (i = 0; i < strlen(message->message); i += BLOCK_SIZE) {
        // Calculate the key schedule
        for (j = 0; j < BLOCK_SIZE; j++) {
            temp = message->key[i + j];
            message->key[i + j] = message->key[i + j + 1];
            message->key[i + j + 1] = temp;
        }

        // Decrypt the block
        for (k = 0; k < BLOCK_SIZE; k++) {
            temp = message->message[i + k];
            message->message[i + k] = (temp - message->key[i + k]) % 26 + 'A';
        }
    }
}

