int main()
{
    int num_disks, current_pole, temp_pole;
    printf("Enter the number of disks: ");
    scanf("%d", &num_disks);
    printf("Enter the current pole: ");
    scanf("%d", &current_pole);
    printf("Enter the temporary pole: ");
    scanf("%d", &temp_pole);

    printf("\n");

    int disks[num_disks];
    int i;

    printf("Enter the disks: ");
    for(i = 0; i < num_disks; i++) {
        scanf("%d", &disks[i]);
