#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <unistd.h>

#define G 6.67430e-11 // Gravitational constant
#define PI 3.14159265358979323846 // Value of Pi

typedef struct {
    double x;
    double y;
    double mass;
    double velocityX;
    double velocityY;
} CelestialBody;

void initializeBody(CelestialBody *body, double x, double y, double mass, double velocityX, double velocityY) {
    body->x = x;
    body->y = y;
    body->mass = mass;
    body->velocityX = velocityX;
    body->velocityY = velocityY;
}

void updatePosition(CelestialBody *body, double deltaTime) {
    body->x += body->velocityX * deltaTime;
    body->y += body->velocityY * deltaTime;
}

void applyGravity(CelestialBody *body, CelestialBody *other, double deltaTime) {
    double dx = other->x - body->x;
    double dy = other->y - body->y;
    double distance = sqrt(dx * dx + dy * dy);

    if (distance == 0) return; // Avoid division by zero

    double force = (G * body->mass * other->mass) / (distance * distance);
    double accelerationX = (force / body->mass) * (dx / distance);
    double accelerationY = (force / body->mass) * (dy / distance);

    body->velocityX += accelerationX * deltaTime;
    body->velocityY += accelerationY * deltaTime;
}

void displayScene(CelestialBody *bodies, int numBodies) {
    system("clear");
    for (int i = 0; i < numBodies; i++) {
        printf("Body %d - Position: (%.2f, %.2f) | Mass: %.2f | Velocity: (%.2f, %.2f)\n",
               i, bodies[i].x, bodies[i].y, bodies[i].mass, bodies[i].velocityX, bodies[i].velocityY);
    }
    printf("\n");
}

void simulate(double totalTime, double deltaTime, CelestialBody *bodies, int numBodies) {
    for (double t = 0; t < totalTime; t += deltaTime) {
        for (int i = 0; i < numBodies; i++) {
            for (int j = 0; j < numBodies; j++) {
                if (i != j) {
                    applyGravity(&bodies[i], &bodies[j], deltaTime);
                }
            }
        }
        for (int i = 0; i < numBodies; i++) {
            updatePosition(&bodies[i], deltaTime);
        }
        displayScene(bodies, numBodies);
        usleep(100000); // Sleep for 0.1 seconds for smoother viewing
    }
}

int main() {
    const int numBodies = 3;
    CelestialBody bodies[numBodies];

    initializeBody(&bodies[0], 0.0, 0.0, 5.97e24, 0, 0);         // Earth
    initializeBody(&bodies[1], 384400000.0, 0.0, 7.35e22, 0, 1022); // Moon
    initializeBody(&bodies[2], 1.496e11, 0.0, 1.989e30, 0, 29780); // Sun

    double totalTime = 3600 * 24; // Simulate one day
    double deltaTime = 3600; // One hour

    printf("Welcome to the Cosmic Dance of Celestial Bodies!\n");
    simulate(totalTime, deltaTime, bodies, numBodies);

    printf("As the stars fade into the night, their love remains eternal.\n");
    return 0;
}

