#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main()
{
    // Create a socket
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Bind the socket to the server address
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = inet_addr("127.0.0.1");
    if (bind(sockfd, (struct sockaddr *) &server_addr, sizeof(server_addr)) == -1) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(sockfd, 5) == -1) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    // Accept an incoming connection
    struct sockaddr_in client_addr;
    socklen_t client_addr_len = sizeof(client_addr);
    int client_sockfd = accept(sockfd, (struct sockaddr *) &client_addr, &client_addr_len);
    if (client_sockfd == -1) {
        perror("accept");
        exit(EXIT_FAILURE);
    }

    // Read the request from the client
    char buffer[BUFFER_SIZE];
    int n = read(client_sockfd, buffer, BUFFER_SIZE);
    if (n == -1) {
        perror("read");
        exit(EXIT_FAILURE);
    }

    // Parse the request
    char *method = strtok(buffer, " ");
    char *path = strtok(NULL, " ");
    char *version = strtok(NULL, "\r\n");

    // Check if the request is valid
    if (strcmp(method, "GET") != 0 || strcmp(version, "HTTP/1.1") != 0) {
        // Send a 400 Bad Request response
        char *response = "HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n";
        write(client_sockfd, response, strlen(response));
        close(client_sockfd);
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Send a 200 OK response
    char *response = "HTTP/1.1 200 OK\r\nContent-Length: 11\r\n\r\nHello world!";
    write(client_sockfd, response, strlen(response));

    // Close the client socket
    close(client_sockfd);

    // Close the server socket
    close(sockfd);

    return EXIT_SUCCESS;
}

