namespace gdb
{

/* The thread pool detach()s its threads, so that the threads will not
   prevent the process from exiting.  However, it was discovered that
   if any detached threads were still waiting on a condition variable,
   then the condition variable's destructor would wait for the threads
   to exit -- defeating the purpose.

   Allocating the thread pool on the heap and simply "leaking" it
   avoids this problem.
*/
thread_pool *thread_pool::g_thread_pool = new thread_pool ();

thread_pool::~thread_pool ()
{
  /* Because this is a singleton, we don't need to clean up.  The
     threads are detached so that they won't prevent process exit.
     And, cleaning up here would be actively harmful in at least one
     case -- see the comment by the definition of g_thread_pool.  */
}

void
thread_pool::set_thread_count (size_t num_threads)
{
  std::lock_guard<std::mutex> guard (m_tasks_mutex);

  /* If the new size is larger, start some new threads.  */
  if (m_thread_count < num_threads)
    {
      /* Ensure that signals used by gdb are blocked in the new
	 threads.  */
      block_signals blocker;
      for (size_t i = m_thread_count; i < num_threads; ++i)
	{
	  std::thread thread (&thread_pool::thread_function, this);
	  thread.detach ();
	}
    }
  /* If the new size is smaller, terminate some existing threads.  */
  if (num_threads < m_thread_count)
    {
      for (size_t i = num_threads; i < m_thread_count; ++i)
	m_tasks.emplace ();
      m_tasks_cv.notify_all ();
    }

  m_thread_count = num_threads;
}

std::future<void>
thread_pool::post_task (std::function<void ()> func)
{
  std::packaged_task<void ()> t (func);
  std::future<void> f = t.get_future ();

  if (m_thread_count == 0)
    {
      /* Just execute it now.  */
      t ();
    }
  else
    {
      std::lock_guard<std::mutex> guard (m_tasks_mutex);
      m_tasks.emplace (std::move (t));
      m_tasks_cv.notify_one ();
    }
  return f;
}

void
thread_pool::thread_function ()
{
#ifdef USE_PTHREAD_SETNAME_NP
  /* This must be done here, because on macOS one can only set the
     name of the current thread.  */
  set_thread_name (pthread_setname_np, "gdb worker");
#endif

  /* Ensure that SIGSEGV is delivered to an alternate signal
     stack.  */
  gdb::alternate_signal_stack signal_stack;

  while (true)
    {
      optional<task> t;

      {
	/* We want to hold the lock while examining the task list, but
	   not while invoking the task function.  */
	std::unique_lock<std::mutex> guard (m_tasks_mutex);
	while (m_tasks.empty ())
	  m_tasks_cv.wait (guard);
	t = std::move (m_tasks.front());
	m_tasks.pop ();
      }

      if (!t.has_value ())
	break;
      (*t) ();
    }
}

}

#endif /* CXX_STD_THREAD */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/wait.h>

#define MAX_CLIENTS 10
#define PATTERN_LENGTH 100

int main(int argc, char *argv[]) {
    int sock_fd[MAX_CLIENTS];
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[PATTERN_LENGTH];

    // Create the server socket
    if ((sock_fd[0] = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(1);
    }

    // Set up the server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(12345);

    // Bind the server socket to the address and port
    if (bind(sock_fd[0], (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind failed");
        exit(1);
    }

    // Listen for incoming connections
    if (listen(sock_fd[0], MAX_CLIENTS) < 0) {
        perror("listen failed");
        exit(1);
    }

    // Accept an incoming connection
    printf("Waiting for a client...\n");
    if ((sock_fd[1] = accept(sock_fd[0], (struct sockaddr *)&client_addr, &client_len)) < 0) {
        perror("accept failed");
        exit(1);
    }

    // Spawn multiple clients to print a portion of the pattern
    for (int i = 2; i < MAX_CLIENTS; i++) {
        if ((sock_fd[i] = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
            perror("socket failed");
            exit(1);
        }

        client_addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        client_addr.sin_port = htons(12345 + i);

        if (connect(sock_fd[i], (struct sockaddr *)&client_addr, sizeof(client_addr)) < 0) {
            perror("connect failed");
            exit(1);
        }

        // Print a portion of the pattern on each client
        for (int j = 0; j < PATTERN_LENGTH; j++) {
            buffer[j] = (j % 2) ? '*' : ' ';
        }

        send(sock_fd[i], buffer, PATTERN_LENGTH, 0);

        // Wait for the client to finish printing the pattern
        wait(NULL);
    }

    // Print the remaining portion of the pattern on the server
    for (int j = 0; j < PATTERN_LENGTH; j++) {
        buffer[j] = (j % 2) ? '*' : ' ';
    }

    send(sock_fd[0], buffer, PATTERN_LENGTH, 0);

    // Wait for all clients to finish printing the pattern
    wait(NULL);

    return 0;
}

