#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_HISTORY 10

typedef struct {
    char date[11];
    float probability;
} ProbabilityRecord;

typedef struct {
    ProbabilityRecord records[MAX_HISTORY];
    int count;
} ProbabilityHistory;

void initializeHistory(ProbabilityHistory *history) {
    history->count = 0;
}

void recordProbability(ProbabilityHistory *history, float probability) {
    if (history->count < MAX_HISTORY) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        sprintf(history->records[history->count].date, "%02d-%02d-%04d", tm.tm_mday, tm.tm_mon + 1, tm.tm_year + 1900);
        history->records[history->count].probability = probability;
        history->count++;
    } else {
        printf("History is full! Cannot record more probabilities.\n");
    }
}

void displayHistory(const ProbabilityHistory *history) {
    printf("\nProbability History (Last %d Records):\n", MAX_HISTORY);
    for (int i = 0; i < history->count; i++) {
        printf("%s: %.2f%%\n", history->records[i].date, history->records[i].probability);
    }
}

float calculateAlienInvasionProbability(int encounters, int sightings) {
    if (encounters <= 0) {
        return 0.0; // Prevent division by zero.
    }
    return (float)sightings / encounters * 100.0; // Returns percentage.
}

int main() {
    int encounters, sightings;
    char choice;
    ProbabilityHistory history;

    initializeHistory(&history);
    srand(time(NULL)); // Seed the random number generator.

    printf("Welcome to the Alien Invasion Probability Calculator!\n");

    do {
        printf("\nEnter the number of alien encounters: ");
        scanf("%d", &encounters);
        printf("Enter the number of sightings: ");
        scanf("%d", &sightings);

        float probability = calculateAlienInvasionProbability(encounters, sightings);
        printf("Probability of alien invasion is: %.2f%%\n", probability);

        recordProbability(&history, probability);

        printf("Would you like to calculate another probability? (y/n): ");
        getchar(); // Consume newline character
        choice = getchar();

    } while (choice == 'y' || choice == 'Y');

    displayHistory(&history);
    printf("Thank you for using the Alien Invasion Probability Calculator!\n");

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <ctype.h>
int main()
{
    // Open the input file
    FILE *fp = fopen("romeo.txt", "r");
    if (fp == NULL)
    {
        printf("Error opening file.\n");
        return 1;
    }

    // Allocate memory for the output file
    char *output = (char*)malloc(sizeof(char)*1000);
    if (output == NULL)
    {
        printf("Error allocating memory.\n");
        fclose(fp);
        return 1;
    }

    // Read the input file line by line
    char line[1000];
    while (fgets(line, sizeof(line), fp)!= NULL)
    {
        // Remove trailing newline character
        line[strcspn(line, "\n")] = '\0';

        // Convert all characters to lowercase
        for (int i = 0; i < strlen(line); i++)
        {
            line[i] = tolower(line[i]);
        }

        // Replace all instances of the word "love" with "Romeo"
        if (strstr(line, "love")!= NULL)
        {
            strcpy(output, line);
            strcat(output, "Romeo");
            strcat(output, " and Juliet\n");
        }
        else
        {
            strcpy(output, line);
            strcat(output, "\n");
        }
    }

    // Close the input file
    fclose(fp);

    // Write the output file
    FILE *fp2 = fopen("output.txt", "w");
    if (fp2 == NULL)
    {
        printf("Error opening output file.\n");
        free(output);
        return 1;
    }

    fwrite(output, sizeof(char), strlen(output), fp2);

    // Free the allocated memory
    free(output);

    // Close the output file
    fclose(fp2);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_NODES 100
#define MAX_EDGES 1000

typedef struct Node {
    int id;
    int visited;
    int *adj;
} Node;

Node nodes[MAX_NODES];
int num_nodes, num_edges;
int graph[MAX_NODES][MAX_NODES];

void dfs(int node_id) {
    nodes[node_id].visited = true;
    printf("Visiting Node %d\n", node_id);

    for (int i = 0; i < num_nodes; ++i) {
        if (nodes[i].adj && graph[node_id][i] && !nodes[i].visited) {
            dfs(i);
        }
    }
}

void init_graph() {
    int source, destination;

    for (int i = 0; i < num_edges; ++i) {
        scanf("%d %d", &source, &destination);
        graph[source][destination] = 1;
        graph[destination][source] = 1;
    }
}

void init_nodes() {
    for (int i = 0; i < num_nodes; ++i) {
        nodes[i].id = i;
        nodes[i].visited = false;
        nodes[i].adj = malloc(num_nodes * sizeof(int));
    }
}

void map_topology() {
    for (int i = 0; i < num_nodes; ++i) {
        if (!nodes[i].visited) {
            dfs(i);
        }
    }
}

void build_adj_mat() {
    for (int i = 0; i < num_nodes; ++i) {
        for (int j = 0; j < num_nodes; ++j) {
            if (i == j) continue;
            if (graph[i][j]) {
                nodes[i].adj[j] = 1;
            }
        }
    }
}

int main() {
    printf("\nWelcome, dear reader, to this enchanting journey\n");
    printf("Through the mesmerizing world of network topology mapping!\n");
    printf("Enter the number of nodes and edges in the network:\n");
    scanf("%d %d", &num_nodes, &num_edges);

    init_nodes();
    init_graph();

    printf("Building adjacency matrix...\n");
    build_adj_mat();

    printf("Network Topology Mapping:\n");
    map_topology();

    return 0;
}

