template<class T1, class T2>
bool test_left_shift(
    T1 v1,
    T2 v2,
    const char *av1,
    const char *av2,
    char expected_result
){
    std::cout
        << "testing  "
        << av1 << " << " << av2
        << std::endl;
    {
        safe_t<T1> t1 = v1;
        using result_type = decltype(t1 << v2);
        static_assert(
            boost::safe_numerics::is_safe<result_type>::value,
            "Expression failed to return safe type"
        );

        try{
            // use auto to avoid checking assignment.
            auto result = t1 << v2;
            std::cout << make_result_display(result);
            if(expected_result == 'x'){
                std::cout
                    << " ! = "<< av1 << " << " << av2
                    << " failed to detect arithmetic error in left shift"
                    << std::endl;
                t1 << v2;
                return false;
            }
        }
        catch(const std::exception & e){
            if(expected_result == '.'){
                std::cout
                    << "erroneously detected arithmetic error in left shift"
                    << " == "<< av1 << " << " << av2
                    << ' ' << e.what()
                    << std::endl;
                try{
                    t1 << v2;
                }
                catch(std::exception){}
                return false;
            }
        }
    }
    {
        safe_t<T2> t2 = v2;
        using result_type = decltype(v1 << t2);
        static_assert(
            boost::safe_numerics::is_safe<result_type>::value,
            "Expression failed to return safe type"
        );

        try{
            // use auto to avoid checking assignment.
            auto result = v1 << t2;
            std::cout << make_result_display(result);
            if(expected_result == 'x'){
                std::cout
                    << " ! = "<< av1 << " << " << av2
                    << " failed to detect error in left shift"
                    << std::endl;
                v1 << t2;
                return false;
            }
        }
        catch(const std::exception & e){
            if(expected_result == '.'){
                std::cout
                    << " == "<< av1 << " << " << av2
                    << "erroneously detected error in left shift "
                    << ' ' << e.what()
                    << std::endl;
                try{
                    v1 << t2;
                }
                catch(std::exception){}
                return false;
            }
        }
    }
    {
        safe_t<T1> t1 = v1;
        safe_t<T2> t2 = v2;
        using result_type = decltype(t1 << t2);
        static_assert(
            boost::safe_numerics::is_safe<result_type>::value,
            "Expression failed to return safe type"
        );

        try{
            // use auto to avoid checking assignment.
            auto result = t1 << t2;
            std::cout << make_result_display(result);
            if(expected_result == 'x'){
                std::cout
                    << " ! = "<< av1 << " << " << av2
                    << " failed to detect error in left shift"
                    << std::endl;
                t1 << t2;
                return false;
            }
            std::cout << std::endl;
        }
        catch(const std::exception & e){
            if(expected_result == '.'){
                std::cout
                    << " == "<< av1 << " << " << av2
                    << " erroneously detected error in left shift"
                    << ' ' << e.what()
                    << std::endl;
                try{
                    t1 << t2;
                }
                catch(std::exception){}
                return false;
            }
        }
    }
    return true; // correct result
}

