#ifndef liblldb_Either_h_
#define liblldb_Either_h_

#include "llvm/ADT/Optional.h"

#include <functional>

namespace lldb_utility {
    template <typename T1, typename T2>
    class Either
    {
    private:
        enum class Selected
        {
            One, Two
        };

        Selected m_selected;
        union
        {
            T1 m_t1;
            T2 m_t2;
        };

    public:
        Either (const T1& t1)
        {
            m_t1 = t1;
            m_selected = Selected::One;
        }

        Either (const T2& t2)
        {
            m_t2 = t2;
            m_selected = Selected::Two;
        }

        Either (const Either<T1,T2>& rhs)
        {
            switch (rhs.m_selected)
            {
                case Selected::One:
                    m_t1 = rhs.GetAs<T1>().getValue();
                    m_selected = Selected::One;
                    break;
                case Selected::Two:
                    m_t2 = rhs.GetAs<T2>().getValue();
                    m_selected = Selected::Two;
                    break;
            }
        }

        template <class X, typename std::enable_if<std::is_same<T1,X>::value>::type * = nullptr>
        llvm::Optional<T1>
        GetAs() const
        {
            switch (m_selected)
            {
                case Selected::One:
                    return m_t1;
                default:
                    return llvm::Optional<T1>();
            }
        }

        template <class X, typename std::enable_if<std::is_same<T2,X>::value>::type * = nullptr>
        llvm::Optional<T2>
        GetAs() const
        {
            switch (m_selected)
            {
                case Selected::Two:
                    return m_t2;
                default:
                    return llvm::Optional<T2>();
            }
        }

        template <class ResultType>
        ResultType
        Apply (std::function<ResultType(T1)> if_T1,
               std::function<ResultType(T2)> if_T2) const
        {
            switch (m_selected)
            {
                case Selected::One:
                    return if_T1(m_t1);
                case Selected::Two:
                    return if_T2(m_t2);
            }
        }

        bool
        operator == (const Either<T1,T2>& rhs)
        {
            return (GetAs<T1>() == rhs.GetAs<T1>()) && (GetAs<T2>() == rhs.GetAs<T2>());
        }

        explicit
        operator bool ()
        {
            switch (m_selected)
            {
                case Selected::One:
                    return (bool)m_t1;
                case Selected::Two:
                    return (bool)m_t2;
            }
        }

        Either<T1,T2>&
        operator = (const Either<T1,T2>& rhs)
        {
            switch (rhs.m_selected)
            {
                case Selected::One:
                    m_t1 = rhs.GetAs<T1>().getValue();
                    m_selected = Selected::One;
                    break;
                case Selected::Two:
                    m_t2 = rhs.GetAs<T2>().getValue();
                    m_selected = Selected::Two;
                    break;
            }
            return *this;
        }

        ~Either ()
        {
            switch (m_selected)
            {
                case Selected::One:
                    m_t1.T1::~T1();
                    break;
                case Selected::Two:
                    m_t2.T2::~T2();
                    break;
            }
        }
    };

} // namespace lldb_utility

#endif // #ifndef liblldb_Either_h_

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    char *name;
    int age;
    char *occupation;
} Person;

int main() {
    Person *people = NULL;
    int num_people = 0;

    // Prompt user to enter number of people to add
    printf("Enter number of people to add: ");
    if (scanf("%d", &num_people)!= 1) {
        printf("Invalid input!\n");
        return 1;
    }

    // Allocate memory for people array
    people = (Person *)malloc(num_people * sizeof(Person));
    if (people == NULL) {
        printf("Memory allocation failed!\n");
        return 1;
    }

    // Prompt user to enter name, age, and occupation for each person
    for (int i = 0; i < num_people; i++) {
        printf("Enter name for person %d: ", i + 1);
        if (fgets(people[i].name, sizeof(people[i].name), stdin) == NULL) {
            printf("Input too long!\n");
            return 1;
        }
        people[i].name[strcspn(people[i].name, "\n")] = 0; // Remove trailing newline character

        printf("Enter age for person %d: ", i + 1);
        if (scanf("%d", &people[i].age)!= 1) {
            printf("Invalid age input!\n");
            return 1;
        }

        printf("Enter occupation for person %d: ", i + 1);
        if (fgets(people[i].occupation, sizeof(people[i].occupation), stdin) == NULL) {
            printf("Input too long!\n");
            return 1;
        }
        people[i].occupation[strcspn(people[i].occupation, "\n")] = 0; // Remove trailing newline character
    }

    // Print the list of people
    printf("List of people:\n");
    for (int i = 0; i < num_people; i++) {
        printf("Name: %s, Age: %d, Occupation: %s\n", people[i].name, people[i].age, people[i].occupation);
    }

    // Free memory
    free(people);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MATRIX_ROWS 10
#define MATRIX_COLS 10

typedef struct {
    int rows;
    int cols;
    int **data;
} matrix_t;

void matrix_init(matrix_t *mat) {
    mat->rows = MATRIX_ROWS;
    mat->cols = MATRIX_COLS;
    mat->data = calloc(MATRIX_ROWS, sizeof(int *));
    for (int i = 0; i < MATRIX_ROWS; i++) {
        mat->data[i] = calloc(MATRIX_COLS, sizeof(int));
    }
}

void matrix_print(matrix_t *mat) {
    for (int i = 0; i < MATRIX_ROWS; i++) {
        for (int j = 0; j < MATRIX_COLS; j++) {
            printf("%d ", mat->data[i][j]);
        }
        printf("\n");
    }
}

void matrix_add(matrix_t *a, matrix_t *b, matrix_t *res) {
    for (int i = 0; i < MATRIX_ROWS; i++) {
        for (int j = 0; j < MATRIX_COLS; j++) {
            res->data[i][j] = a->data[i][j] + b->data[i][j];
        }
    }
}

void matrix_mult(matrix_t *a, matrix_t *b, matrix_t *res) {
    for (int i = 0; i < MATRIX_ROWS; i++) {
        for (int j = 0; j < MATRIX_COLS; j++) {
            int sum = 0;
            for (int k = 0; k < MATRIX_ROWS; k++) {
                sum += a->data[i][k] * b->data[k][j];
            }
            res->data[i][j] = sum;
        }
    }
}

int main() {
    srand(time(NULL));

    matrix_t *a, *b, *c;
    matrix_init(&a);
    matrix_init(&b);
    matrix_init(&c);

    for (int i = 0; i < MATRIX_ROWS; i++) {
        for (int j = 0; j < MATRIX_COLS; j++) {
            int val = rand() % 10;
            a->data[i][j] = val;
            b->data[i][j] = val;
        }
    }

    matrix_add(a, b, c);
    matrix_mult(a, b, c);

    matrix_print(c);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WIDTH 25
#define HEIGHT 10
#define WALL '#'
#define PATH ' '
#define PLAYER '@'

int map[HEIGHT][WIDTH];

void generate_map() {
    int x, y, r, dx = 1, dy = 1;

    for (y = 0; y < HEIGHT; y++) {
        for (x = 0; x < WIDTH; x++) {
            map[y][x] = WALL;
        }
    }

    srand(time(NULL));

    map[HEIGHT / 2][WIDTH / 2] = PLAYER;

    for (r = 1; r < 3; r++) {
        for (y = 0; y < HEIGHT; y++) {
            for (x = 0; x < WIDTH; x++) {
                if (map[y][x] == WALL) {
                    if (rand() % 3 == 0) {
                        map[y + dy][x + dx] = PATH;
                        map[y][x] = PATH;
                        dx += (rand() % 3 - 1) > 0 ? 1 : -1;
                        dy += (rand() % 3 - 1) > 0 ? 1 : -1;
                    }
                }
            }
            dx = 1;
            dy = 1;
        }
        dx = 1;
        dy = 1;
    }
}

void print_map() {
    int y, x;

    for (y = 0; y < HEIGHT; y++) {
        for (x = 0; x < WIDTH; x++) {
            putchar(map[y][x]);
        }
        putchar('\n');
    }
}

int main() {
    generate_map();
    print_map();

    return 0;
}

